function getPalettes() {
  return state.palettes?.length ? state.palettes : FALLBACK_PALETTES;
}

function getFontThemes() {
  return state.fontThemes?.length ? state.fontThemes : FALLBACK_FONT_THEMES;
}

function matchPaletteId(brand = {}) {
  const pHex = String(brand.primary || '').toLowerCase();
  const aHex = String(brand.accent || '').toLowerCase();
  const iHex = String(brand.ink || '').toLowerCase();
  if (brand.paletteId) {
    const byId = getPalettes().find((p) => p.id === brand.paletteId);
    if (byId) return byId.id;
  }
  const hit = getPalettes().find(
    (p) =>
      p.brand.primary.toLowerCase() === pHex &&
      p.brand.accent.toLowerCase() === aHex &&
      p.brand.ink.toLowerCase() === iHex,
  );
  return hit?.id || 'slate-gold';
}

function palettesByGroup(palettes = []) {
  const byName = new Map();
  const groups = [];
  for (const p of palettes) {
    const name = p.group || 'Other';
    let group = byName.get(name);
    if (!group) {
      group = { name, items: [] };
      byName.set(name, group);
      groups.push(group);
    }
    group.items.push(p);
  }
  groups.sort((a, b) => {
    const ai = PALETTE_GROUP_ORDER.indexOf(a.name);
    const bi = PALETTE_GROUP_ORDER.indexOf(b.name);
    return (ai === -1 ? PALETTE_GROUP_ORDER.length : ai) - (bi === -1 ? PALETTE_GROUP_ORDER.length : bi);
  });
  return groups;
}

function paletteOptionsHtml(brand = {}) {
  const selected = matchPaletteId(brand);
  return palettesByGroup(getPalettes())
    .map((group) => {
      const options = group.items
        .map(
          (p) =>
            `<option value="${esc(p.id)}" ${p.id === selected ? 'selected' : ''}>${esc(p.label)}</option>`,
        )
        .join('');
      return `<optgroup label="${esc(group.name)}">${options}</optgroup>`;
    })
    .join('');
}

function paletteChipHtml(brand = {}, { id = '' } = {}) {
  const b = brand || {};
  return `<span class="palette-swatches"${id ? ` id="${esc(id)}"` : ''} aria-hidden="true">
    <span class="palette-swatch" style="background:${esc(b.primary || '#1C2B3A')}" data-tip="Primary"></span>
    <span class="palette-swatch" style="background:${esc(b.accent || '#E8A317')}" data-tip="Accent"></span>
  </span>`;
}

function paletteSwatchesHtml(brand = {}) {
  const id = matchPaletteId(brand);
  const palette = getPalettes().find((p) => p.id === id) || getPalettes()[0];
  return paletteChipHtml(palette?.brand || brand, { id: 'sc-brand-swatches' });
}

function palettePickerHtml(brand = {}) {
  const selected = matchPaletteId(brand);
  const selectedPalette = getPalettes().find((p) => p.id === selected);
  const menu = palettesByGroup(getPalettes())
    .map((group) => {
      const rows = group.items
        .map((p) => {
          const on = p.id === selected;
          return `<button type="button" class="palette-picker-option${on ? ' is-active' : ''}" role="option" id="sc-palette-opt-${esc(p.id)}" data-palette-id="${esc(p.id)}" aria-selected="${on ? 'true' : 'false'}">
            <span class="palette-picker-option-label">${esc(p.label)}</span>
            ${paletteChipHtml(p.brand)}
          </button>`;
        })
        .join('');
      return `<div class="palette-picker-group" role="presentation">${esc(group.name)}</div>${rows}`;
    })
    .join('');
  return `<div class="palette-picker">
    <span class="palette-picker-caption" id="sc-brand-palette-label">Palette</span>
    <select id="sc-brand-palette" class="sr-only" tabindex="-1" aria-hidden="true">
      ${paletteOptionsHtml(brand)}
    </select>
    <button type="button" class="palette-picker-trigger" id="sc-brand-palette-trigger" aria-haspopup="listbox" aria-expanded="false" aria-controls="sc-brand-palette-menu" aria-labelledby="sc-brand-palette-label" data-tip="Named color set. Apply saves it on the site.">
      <span class="palette-picker-value">${esc(selectedPalette?.label || 'Slate & Gold')}</span>
    </button>
    <div id="sc-brand-palette-menu" class="palette-picker-menu" role="listbox" aria-labelledby="sc-brand-palette-label" hidden>
      ${menu}
    </div>
  </div>`;
}

function wirePalettePicker() {
  const select = document.getElementById('sc-brand-palette');
  const trigger = document.getElementById('sc-brand-palette-trigger');
  const menu = document.getElementById('sc-brand-palette-menu');
  if (!select || !trigger || !menu) return;
  const options = () => [...menu.querySelectorAll('[data-palette-id]')];
  let activeIndex = Math.max(
    0,
    options().findIndex((el) => el.getAttribute('aria-selected') === 'true'),
  );

  const markActive = () => {
    const rows = options();
    rows.forEach((el, i) => el.classList.toggle('is-active', i === activeIndex));
    const active = rows[activeIndex];
    if (active) trigger.setAttribute('aria-activedescendant', active.id);
  };

  const onDocPointer = (event) => {
    if (!menu.isConnected || menu.hidden) {
      document.removeEventListener('mousedown', onDocPointer);
      return;
    }
    if (event.target.closest?.('.palette-picker')) return;
    setOpen(false);
  };

  const setOpen = (open) => {
    menu.hidden = !open;
    trigger.setAttribute('aria-expanded', open ? 'true' : 'false');
    document.removeEventListener('mousedown', onDocPointer);
    if (!open) return;
    const selected = options().findIndex((el) => el.dataset.paletteId === select.value);
    activeIndex = selected >= 0 ? selected : 0;
    markActive();
    options()[activeIndex]?.scrollIntoView({ block: 'nearest' });
    document.addEventListener('mousedown', onDocPointer);
  };

  const choose = (id) => {
    if (!id) {
      setOpen(false);
      return;
    }
    const rows = options();
    rows.forEach((el) => el.setAttribute('aria-selected', el.dataset.paletteId === id ? 'true' : 'false'));
    const label = getPalettes().find((p) => p.id === id)?.label || id;
    const valueEl = trigger.querySelector('.palette-picker-value');
    if (valueEl) valueEl.textContent = label;
    setOpen(false);
    if (select.value === id) return;
    select.value = id;
    select.dispatchEvent(new Event('change', { bubbles: true }));
  };

  trigger.addEventListener('click', () => setOpen(menu.hidden));
  trigger.addEventListener('keydown', (event) => {
    const rows = options();
    if (!rows.length) return;
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault();
      if (menu.hidden) {
        setOpen(true);
        return;
      }
      activeIndex =
        event.key === 'ArrowDown'
          ? Math.min(rows.length - 1, activeIndex + 1)
          : Math.max(0, activeIndex - 1);
      markActive();
      rows[activeIndex]?.scrollIntoView({ block: 'nearest' });
    } else if (event.key === 'Home' || event.key === 'End') {
      event.preventDefault();
      if (menu.hidden) setOpen(true);
      activeIndex = event.key === 'Home' ? 0 : rows.length - 1;
      markActive();
      rows[activeIndex]?.scrollIntoView({ block: 'nearest' });
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      if (menu.hidden) setOpen(true);
      else choose(rows[activeIndex]?.dataset.paletteId);
    } else if (event.key === 'Escape' && !menu.hidden) {
      event.preventDefault();
      setOpen(false);
    }
  });
  menu.addEventListener('click', (event) => {
    const row = event.target.closest?.('[data-palette-id]');
    if (!row) return;
    choose(row.dataset.paletteId);
  });
}

function updatePaletteSwatches(paletteId) {
  const palette = getPalettes().find((p) => p.id === paletteId);
  const root = document.getElementById('sc-brand-swatches');
  if (!palette?.brand || !root) return;
  const spans = root.querySelectorAll('.palette-swatch');
  const colors = [palette.brand.primary, palette.brand.accent];
  spans.forEach((el, i) => {
    if (colors[i]) el.style.background = colors[i];
  });
}

async function ensurePalettes() {
  if (state.palettes?.length) return state.palettes;
  try {
    const data = await api('/api/palettes');
    state.palettes = data.palettes || FALLBACK_PALETTES;
  } catch {
    state.palettes = FALLBACK_PALETTES;
  }
  return state.palettes;
}

async function ensureFontThemes() {
  if (state.fontThemes?.length) return state.fontThemes;
  try {
    const data = await api('/api/font-themes');
    state.fontThemes = data.themes || FALLBACK_FONT_THEMES;
  } catch {
    state.fontThemes = FALLBACK_FONT_THEMES;
  }
  return state.fontThemes;
}

function ensureSiteFontSampleStyles() {
  if (document.getElementById('rover-font-theme-samples')) return;
  const themes = getFontThemes();
  const hrefs = [...new Set(themes.map((t) => t.googleHref).filter(Boolean))];
  hrefs.forEach((href, i) => {
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = href;
    link.id = i === 0 ? 'rover-font-theme-samples' : `rover-font-theme-samples-${i}`;
    document.head.appendChild(link);
  });
}

function matchFontThemeId(brand = {}) {
  const id = String(brand.fontTheme || '').trim();
  if (id && getFontThemes().some((t) => t.id === id)) return id;
  return 'archivo-source';
}

function fontThemeCardsHtml(brand = {}, businessName = '') {
  const current = matchFontThemeId(brand);
  const name = String(businessName || 'Your Business').trim() || 'Your Business';
  return `<div class="font-theme-cards" role="radiogroup" aria-label="Text font">
    ${getFontThemes()
      .map((t) => {
        const on = t.id === current ? 'on' : '';
        return `<button type="button" class="font-theme-card ${on}" data-font-theme="${esc(t.id)}" role="radio" aria-checked="${
          t.id === current ? 'true' : 'false'
        }" data-tip="${esc(t.tip || t.label)}">
          <span class="font-theme-card-label">${esc(t.label)}</span>
          <span class="font-theme-card-sample-display" style="font-family:${esc(t.displayStack)}">Aa</span>
          <span class="font-theme-card-sample-name" style="font-family:${esc(t.displayStack)}">${esc(name)}</span>
          <span class="font-theme-card-sample-body" style="font-family:${esc(t.bodyStack)}">Clear body text for forms, FAQs, and trust copy.</span>
          <span class="font-theme-card-meta muted">${esc(t.displayFamily)} · ${esc(t.bodyFamily)}</span>
        </button>`;
      })
      .join('')}
  </div>`;
}

let opsTooltipActiveEl = null;

function hideOpsTooltip() {
  opsTooltipActiveEl = null;
  const tip = document.getElementById('ops-tooltip');
  if (!tip) return;
  tip.classList.add('hidden');
  tip.textContent = '';
}

function positionOpsTooltip(tipEl, anchorEl, clientX, clientY) {
  const pad = 12;
  const rect = tipEl.getBoundingClientRect();
  let left;
  let top;
  if (Number.isFinite(clientX) && Number.isFinite(clientY)) {
    left = clientX + 14;
    top = clientY + 18;
  } else if (anchorEl) {
    const r = anchorEl.getBoundingClientRect();
    left = r.left;
    top = r.bottom + 8;
  } else {
    return;
  }
  if (left + rect.width > window.innerWidth - pad) {
    left = Math.max(pad, window.innerWidth - rect.width - pad);
  }
  if (top + rect.height > window.innerHeight - pad) {
    top = Math.max(pad, (Number.isFinite(clientY) ? clientY : top) - rect.height - 12);
  }
  if (left < pad) left = pad;
  if (top < pad) top = pad;
  tipEl.style.left = `${Math.round(left)}px`;
  tipEl.style.top = `${Math.round(top)}px`;
}

function showOpsTooltip(anchorEl, clientX, clientY) {
  const tip = document.getElementById('ops-tooltip');
  if (!tip || !anchorEl) return;
  const text = String(anchorEl.getAttribute('data-tip') || '').trim();
  if (!text) {
    hideOpsTooltip();
    return;
  }
  // Avoid native browser tooltip stacking with #ops-tooltip
  anchorEl.removeAttribute('title');
  tip.textContent = text;
  tip.classList.remove('hidden');
  // Measure after show, then place
  positionOpsTooltip(tip, anchorEl, clientX, clientY);
}

function wireOpsTooltips() {
  const onMove = (event) => {
    if (!opsTooltipActiveEl) return;
    showOpsTooltip(opsTooltipActiveEl, event.clientX, event.clientY);
  };
  document.addEventListener('pointerover', (event) => {
    const el = event.target?.closest?.('[data-tip]');
    if (!el || !el.getAttribute('data-tip')) return;
    opsTooltipActiveEl = el;
    showOpsTooltip(el, event.clientX, event.clientY);
  });
  document.addEventListener('pointerout', (event) => {
    const el = event.target?.closest?.('[data-tip]');
    if (!el || el !== opsTooltipActiveEl) return;
    const next = event.relatedTarget?.closest?.('[data-tip]');
    if (next === opsTooltipActiveEl) return;
    hideOpsTooltip();
  });
  document.addEventListener('pointermove', onMove, { passive: true });
  document.addEventListener('focusin', (event) => {
    const el = event.target?.closest?.('[data-tip]');
    if (!el) return;
    opsTooltipActiveEl = el;
    showOpsTooltip(el);
  });
  document.addEventListener('focusout', (event) => {
    const el = event.target?.closest?.('[data-tip]');
    if (!el || el !== opsTooltipActiveEl) return;
    hideOpsTooltip();
  });
  window.addEventListener('scroll', hideOpsTooltip, true);
  window.addEventListener('resize', hideOpsTooltip);
  document.addEventListener(
    'click',
    (event) => {
      const tip = event.target?.closest?.('summary .tip-info');
      if (!tip) return;
      event.preventDefault();
      event.stopPropagation();
    },
    true,
  );
}

