const PIPELINE_RANK_SORT = {
  Discovery: 0,
  Research: 1,
  Website: 2,
  Launched: 3,
};

function isCandidateLaunched(c) {
  const m = c?.meta || {};
  return Boolean(m.lastLaunchAt || m.lastShipAt);
}

/** Pipeline rank for the Type column (highest wins). */
function candidatePipelineRank(c) {
  if (isCandidateLaunched(c)) return 'Launched';
  if (c?.decision === 'pursue') return 'Website';
  if (c?.stageFlags?.hasResearch) return 'Research';
  return 'Discovery';
}

function launchedBadgeHtml() {
  return `<span class="cand-live-badge" data-tip="Launched" aria-label="Launched"><svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true" focusable="false"><circle cx="8" cy="11" r="1.35" fill="currentColor"/><path d="M5.15 8.35a4.1 4.1 0 0 1 5.7 0" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round"/><path d="M3.55 6.35a6.4 6.4 0 0 1 8.9 0" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round"/></svg></span>`;
}

const STAGE_STEP_TIPS = {
  1: 'Search volumes done',
  2: 'Page check done',
  3: 'Write-up done',
  4: 'Renter search done',
};

const WEBSITE_TRACK_TIPS = {
  1: 'Site details done',
  2: 'Pages written',
  3: 'Site is live',
};

/** Highest completed Research→Prospects stage (0 = none). */
function candidateHighestStageStep(c) {
  const f = c?.stageFlags || {};
  if (f.hasProspects) return 4;
  if (f.hasNarrative) return 3;
  if (f.hasEnrichment) return 2;
  if (f.hasVolumes) return 1;
  return 0;
}

function isWebsiteLaunched(c) {
  const m = c?.meta || {};
  return Boolean(m.lastLaunchAt || m.lastShipAt || m.cloudflarePagesDone || m.dnsDone);
}

/** Durable Site-Config / Content / Launch complete (no in-session soft-done). */
function isWebsiteTrackComplete(c, track) {
  const f = c?.stageFlags || {};
  const m = c?.meta || {};
  if (track === 1) {
    if (!f.hasSiteConfig || !m.lastServiceAreaAt) return false;
    return Boolean(
      m.phoneSkippedAt ||
        m.lastPhoneAt ||
        f.hasSitePhone ||
        (c?.id && state.sitePhoneProvisioned?.[c.id]),
    );
  }
  if (track === 2) return Boolean(f.hasContent);
  if (track === 3) return isWebsiteLaunched(c) && Boolean(m.indexingDone);
  return false;
}

/** Highest completed Website track (0 = none). */
function candidateHighestWebsiteTrack(c) {
  if (isWebsiteTrackComplete(c, 3)) return 3;
  if (isWebsiteTrackComplete(c, 2)) return 2;
  if (isWebsiteTrackComplete(c, 1)) return 1;
  return 0;
}

/** Launched — never permanently deletable in Rover. Unlaunched Website is allowed. */
function isUndeletableCandidateRow(c) {
  return isCandidateLaunched(c);
}

function undeletableIdsInSelection(ids = [...state.selectedIds]) {
  return ids.filter((id) => {
    const c = state.candidates.find((x) => x.id === id);
    return isUndeletableCandidateRow(c);
  });
}

function stageStepIconHtml(step, tips = STAGE_STEP_TIPS) {
  const n = Number(step) || 0;
  if (n < 1 || n > 4) return '<span class="muted">—</span>';
  return `<span class="stage-step-icon stage-step-${n}" data-tip="${esc(
    tips[n] || '',
  )}">${n}</span>`;
}

function updateCandidateSelectionCount() {
  const nSelected = state.selectedIds.size;
  const el = document.getElementById('candidate-selection-count');
  if (el) el.textContent = `${nSelected} selected`;
  const bulkMeta = document.getElementById('candidate-bulk-summary-meta');
  if (bulkMeta) bulkMeta.textContent = nSelected ? `${nSelected} selected` : '';
  const countEl = document.getElementById('candidate-filter-count');
  if (countEl) {
    const n = filteredCandidates().length;
    const vis = state.candidateVisibilityFilter || 'active';
    const all = state.candidates.length;
    const archived = state.archivedCount ?? state.candidates.filter((c) => c.archived).length;
    const denom =
      vis === 'archived' ? archived : vis === 'all' ? all : Math.max(0, all - archived);
    countEl.textContent = `Showing ${n} / ${denom}`;
  }
  const batchSel = document.getElementById('candidate-batch-decision');
  const batchBtn = document.getElementById('candidate-batch-decision-btn');
  const groupAction = document.getElementById('candidate-group-action');
  const groupAddBtn = document.getElementById('candidate-group-add-btn');
  const groupRemoveBtn = document.getElementById('candidate-group-remove-btn');
  const addToSitesBtn = document.getElementById('candidate-add-to-sites-btn');
  const archiveBtn = document.getElementById('candidate-archive-btn');
  const unarchiveBtn = document.getElementById('candidate-unarchive-btn');
  const deleteBtn = document.getElementById('candidate-delete-btn');
  const disable = nSelected === 0;
  if (batchSel) batchSel.disabled = disable;
  if (batchBtn) batchBtn.disabled = disable;
  if (groupAction) groupAction.disabled = disable;
  if (groupAddBtn) groupAddBtn.disabled = disable;
  if (groupRemoveBtn) groupRemoveBtn.disabled = disable;
  if (addToSitesBtn) addToSitesBtn.disabled = disable;
  if (archiveBtn) archiveBtn.disabled = disable;
  if (unarchiveBtn) unarchiveBtn.disabled = disable;
  if (deleteBtn) {
    const blocked = undeletableIdsInSelection();
    deleteBtn.disabled = disable || blocked.length > 0;
    if (blocked.length) {
      setElementTip(
        deleteBtn,
        'Live sites cannot be deleted here.',
      );
    } else {
      setElementTip(
        deleteBtn,
        'Permanently delete selected sites that are not live.',
      );
    }
  }
}

function emptyStateForFilter() {
  const f = state.candidateDecisionFilter;
  const vis = state.candidateVisibilityFilter || 'active';
  if (!state.candidates.length) {
    return 'No candidates yet — Process a discovery batch (all decisions land in groups here).';
  }
  if (state.view === 'website-builder' && !state.candidates.some((c) => c.decision === 'pursue' && !c.archived)) {
    return 'No pursue Candidates yet — mark pursue in Research to open Website.';
  }
  if (vis === 'archived' && !(state.archivedCount ?? state.candidates.some((c) => c.archived))) {
    return 'No archived candidates — Archive hides rows from Active without deleting files.';
  }
  if (vis === 'archived') {
    return 'No archived candidates match these filters.';
  }
  if (f === 'pursue') {
    return state.view === 'website-builder'
      ? 'No pursue Candidates yet — mark pursue in Research to build here.'
      : 'No pursue yet — Process a discovery batch and Accept pursue rows.';
  }
  if (f === 'pass') {
    return `No ${f} candidates — archive groups fill when you Process discovery rows with that decision.`;
  }
  if (f === '__undecided') return 'No undecided candidates.';
  if (state.candidateBatchFilter) {
    return `No candidates from discovery batch “${state.candidateBatchFilter}”.`;
  }
  if (state.candidateGroupFilter === '__ungrouped') {
    return 'No ungrouped candidates for this filter.';
  }
  if (state.candidateGroupFilter) {
    const g = (state.candidateGroups || []).find((x) => x.id === state.candidateGroupFilter);
    return `No candidates in group “${g?.name || state.candidateGroupFilter}”.`;
  }
  if (state.candidateTextFilter) return 'No candidates match this search.';
  if (f) return `No candidates in the “${f}” decision group.`;
  return 'No candidates match these filters.';
}

/** Freeze row selection while Site-Config Service area (map) is open. */
function candidateSelectionLocked() {
  return (
    document.getElementById('view-candidates')?.classList.contains('sa-map-open') ||
    state.siteConfigOpenStep === 'service-area'
  );
}

const DETAIL_SHELF_KEY = 'ops.detailShelf';

function readDetailShelf() {
  try {
    return localStorage.getItem(DETAIL_SHELF_KEY) === '1';
  } catch {
    return false;
  }
}

function persistDetailShelf(on) {
  try {
    localStorage.setItem(DETAIL_SHELF_KEY, on ? '1' : '0');
  } catch {
    /* ignore */
  }
}

function detailShelfToggleInnerHtml(expanded) {
  const icon = expanded
    ? '<svg class="detail-shelf-toggle-icon" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m6 17 5-5-5-5"/><path d="m13 17 5-5-5-5"/></svg>'
    : '<svg class="detail-shelf-toggle-icon" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m11 17-5-5 5-5"/><path d="m18 17-5-5 5-5"/></svg>';
  return `${icon}<span>${expanded ? 'Collapse' : 'Expand'}</span>`;
}

function applyDetailShelf(on = readDetailShelf()) {
  const allowed = state.tab === 'website' && state.websiteOpenStep === 'images';
  const layout = document.getElementById('view-candidates');
  layout?.classList.toggle('layout-detail-shelf', Boolean(on) && allowed);
  const btn = document.getElementById('detail-shelf-toggle');
  if (btn) {
    btn.classList.toggle('hidden', !allowed);
    const expanded = Boolean(on) && allowed;
    btn.setAttribute('aria-expanded', expanded ? 'true' : 'false');
    btn.innerHTML = detailShelfToggleInnerHtml(expanded);
    setElementTip(btn, expanded ? 'Collapse to sidebar width' : 'Expand sidebar over the table');
  }
}

function toggleDetailShelf() {
  if (!(state.tab === 'website' && state.websiteOpenStep === 'images')) return;
  const next = !readDetailShelf();
  persistDetailShelf(next);
  applyDetailShelf(next);
  if (candidateSelectionLocked()) {
    requestAnimationFrame(() => {
      serviceAreaMount?.invalidateSize?.();
      requestAnimationFrame(() => serviceAreaMount?.invalidateSize?.());
    });
  }
}

function syncCandidatesDetailVisibility() {
  const empty = document.getElementById('empty-detail');
  const detail = document.getElementById('detail');
  const layout = document.getElementById('view-candidates');
  const saMapOpen = candidateSelectionLocked();
  const collapsed =
    !saMapOpen && state.selectedIds.size === 0 && !state.selectedId;
  layout?.classList.toggle('layout-detail-collapsed', collapsed);
  applyDetailShelf();

  if (!empty || !detail) return;
  if (state.selectedIds.size > 1) {
    empty.classList.add('hidden');
    detail.classList.remove('hidden');
    return;
  }
  if (state.selectedId && state.detail) {
    empty.classList.add('hidden');
    detail.classList.remove('hidden');
    return;
  }
  empty.classList.remove('hidden');
  detail.classList.add('hidden');
  empty.textContent =
    state.selectedIds.size === 0 && !state.selectedId
      ? 'Select rows to run stages · click a row to open detail'
      : 'Loading…';
}

function syncSitesDetailVisibility() {
  const layout = document.getElementById('view-sites');
  layout?.classList.toggle('layout-detail-collapsed', !state.selectedSiteId);
}

function syncPhoneDetailVisibility() {
  const layout = document.getElementById('view-phone');
  const mode = state.phone?.mode || 'combined';
  if (layout) layout.dataset.leadMode = mode;
  const open =
    mode === 'phone'
      ? Boolean(state.phone?.selectedCallId)
      : mode === 'forms'
        ? Boolean(state.phone?.forms?.selectedId)
        : false;
  layout?.classList.toggle('layout-detail-collapsed', !open);
  document.querySelectorAll('.lead-mode-btn').forEach((btn) => {
    const on = btn.dataset.leadMode === mode;
    btn.classList.toggle('is-active', on);
    btn.setAttribute('aria-selected', on ? 'true' : 'false');
  });
}

/** Click empty table/panel chrome to clear row selection (not rows, controls, or thead). */
const TABLE_DESELECT_IGNORE =
  'thead, input, select, button, a, label, textarea, .col-resize-handle, .candidate-bulk-details, .discovery-filters-bar, .sites-filters, .discovery-flow, .sites-gsc-status, .phone-calls-toolbar, #sa-map-canvas, .sa-map-canvas-host, .leaflet-container, .cand-niche, .cand-niche-input';
const TABLE_DESELECT_ROW =
  'tr[data-id], tr[data-call-id], tr[data-form-id], tr[data-row-idx], .phone-call-row';

function eventPath(e) {
  if (typeof e.composedPath === 'function') {
    try {
      const path = e.composedPath();
      if (Array.isArray(path) && path.length) return path;
    } catch {
      /* ignore */
    }
  }
  const path = [];
  let node = e.target;
  while (node) {
    path.push(node);
    node = node.parentNode;
  }
  return path;
}

function wireTableDeselectOnEmpty(roots, clearFn) {
  const list = (Array.isArray(roots) ? roots : [roots]).filter(Boolean);
  for (const root of list) {
    if (root.dataset.deselectWired === '1') continue;
    root.dataset.deselectWired = '1';
    root.addEventListener('click', (e) => {
      const path = eventPath(e);
      // Use path, not closest(): row click may re-render tbody mid-bubble and detach the tr
      // so `tbody tr[data-id]` no longer matches.
      if (
        path.some(
          (n) =>
            n &&
            typeof n.matches === 'function' &&
            (n.matches(TABLE_DESELECT_ROW) || n.matches(TABLE_DESELECT_IGNORE)),
        )
      ) {
        return;
      }
      clearFn();
    });
  }
}

function clearCandidateRowSelection() {
  if (candidateSelectionLocked()) return;
  if (!state.selectedId && state.selectedIds.size === 0 && !state.detail) return;
  state.selectedId = null;
  state.selectedIds.clear();
  state.detail = null;
  state.multiQueue = false;
  syncCandidatesDetailVisibility();
  renderList();
  renderActions();
  persistUiRestore();
}

function clearSitesRowSelection() {
  if (!state.selectedSiteId) return;
  state.selectedSiteId = null;
  renderSitesTable();
  renderSitesDetail();
}

function clearFormSelection() {
  if (!state.phone?.forms?.selectedId) return;
  state.phone.forms.selectedId = null;
  renderFormsTable();
  renderFormsDetail();
}

function clearPhoneCallSelection() {
  if (!state.phone?.selectedCallId) return;
  state.phone.selectedCallId = null;
  renderPhoneCalls();
  renderPhoneDetail();
}

function clearDiscoveryRowSelection() {
  if (!state.discoverySelected?.size) return;
  state.discoverySelected = new Set();
  state.discoveryCheckAnchor = null;
  renderDiscoveryTable();
}

async function beginCandidateNicheEdit(td) {
  if (!td || td.querySelector('input.cand-niche-input')) return;
  const id = td.dataset.id;
  const row = state.candidates.find((c) => c.id === id);
  if (!row) return;
  const afterEval = Boolean(row.nicheRenameLocked || td.dataset.nicheLocked === '1');
  if (afterEval) {
    const step1 = await showModal({
      title: 'Niche already evaluated',
      confirmLabel: 'Continue',
      cancelLabel: 'Cancel',
      bodyHtml:
        '<p>This niche was already used for <strong>SERP / Volume</strong> (and later stages). Scores and photos were measured against the current name.</p><p>You can still change the table name. That does not re-run evaluations.</p>',
    });
    if (!step1) return;
    const step2 = await showModal({
      title: 'Ripple effects',
      confirmLabel: 'Change niche',
      cancelLabel: 'Cancel',
      bodyHtml:
        '<p>Changing the niche now updates the <strong>root name</strong> (table, config, meta) only.</p><p>It does <strong>not</strong> re-run SERP, rewrite site copy, or retag photo groups. The live site can still say the old name until you re-run Site-config / Content / Push.</p>',
    });
    if (!step2) return;
  }
  const liveRow = state.candidates.find((c) => c.id === id) || row;
  window.setTimeout(() => {
    const cell =
      document.querySelector(`#candidate-table td.cand-niche[data-id="${CSS.escape(id)}"]`) ||
      td;
    if (!cell?.isConnected) return;
    startInlineNicheEdit(cell, liveRow, { confirmAfterEval: afterEval });
  }, 50);
}

function startInlineNicheEdit(td, row, { confirmAfterEval = false } = {}) {
  if (!td || td.querySelector('input.cand-niche-input')) return;
  const id = row.id;
  const current = String(row.niche || '').trim();
  const input = document.createElement('input');
  input.type = 'text';
  input.className = 'cand-niche-input';
  input.value = current;
  input.setAttribute('aria-label', 'Rename niche');
  td.replaceChildren(input);

  let done = false;
  let armed = false;
  const arm = () => {
    armed = true;
  };
  window.setTimeout(arm, 200);

  const finish = async (save) => {
    if (done) return;
    done = true;
    const next = String(input.value || '').replace(/\s+/g, ' ').trim();
    if (!save || !next || next === current) {
      renderList();
      return;
    }
    input.disabled = true;
    try {
      await api(`/api/candidates/${encodeURIComponent(id)}/niche`, {
        method: 'POST',
        body: JSON.stringify({ niche: next, confirmAfterEval: Boolean(confirmAfterEval) }),
      });
      row.niche = next;
      if (row.meta) row.meta.niche = next;
      const data = await api('/api/candidates');
      state.candidates = data.candidates || [];
      state.decisionCounts = data.decisionCounts || {};
      refreshDecisionFilterCounts();
      renderList();
      if (state.detail?.id === id) await loadSelectedCandidateDetail(id);
      if (state.selectedIds.size > 1) renderMultiDetail();
      else if (state.selectedId === id && state.detail) renderDetail();
      notifyCandidatesChanged({ type: 'candidates', ids: [id] });
    } catch (error) {
      await showModal({
        title: error?.code === 'NICHE_LOCKED' || /locked/i.test(error?.message || '')
          ? 'Niche is locked'
          : 'Rename failed',
        confirmLabel: 'OK',
        hideCancel: true,
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
      renderList();
    }
  };

  input.addEventListener('click', (e) => e.stopPropagation());
  input.addEventListener('dblclick', (e) => e.stopPropagation());
  input.addEventListener('input', arm);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      void finish(true);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      void finish(false);
    } else {
      arm();
    }
  });
  input.addEventListener('blur', () => {
    if (!armed) {
      window.setTimeout(() => {
        if (!done && document.activeElement !== input) input.focus();
      }, 0);
      return;
    }
    void finish(true);
  });
  input.focus();
  input.select();
}

async function persistCandidateDecision(id, decision, notes) {
  try {
    const row = state.candidates.find((c) => c.id === id);
    const body = {
      decision: decision || null,
      notes:
        notes !== undefined
          ? notes || null
          : row?.decisionNotes ?? null,
    };
    await api(`/api/candidates/${encodeURIComponent(id)}/decision`, {
      method: 'POST',
      body: JSON.stringify(body),
    });
    if (row) {
      row.decision = decision || null;
      if (notes !== undefined) row.decisionNotes = notes || null;
    }
    if (state.detail?.id === id) {
      await loadSelectedCandidateDetail(id);
    }
    const data = await api('/api/candidates');
    state.candidates = data.candidates || [];
    state.decisionCounts = data.decisionCounts || {};
    refreshDecisionFilterCounts();
    renderList();
    if (state.selectedIds.size > 1) renderMultiDetail();
    else if (state.selectedId === id && state.detail) renderDetail();
    else renderActions();
    notifyCandidatesChanged({ type: 'candidates', ids: [id] });
  } catch (error) {
    await showModal({
      title: 'Save failed',
      confirmLabel: 'OK',
      bodyHtml: `<p>${esc(error.message)}</p>`,
    });
    await loadCandidates();
  }
}

function clusterRosterRoleRank(role) {
  return shotgunRoleLabel(role) === 'Hub' ? 0 : 1;
}

function sortClusterRosterMembers(members) {
  const sort = state.clusterRosterSort || { key: 'population', dir: -1 };
  const dir = sort.dir === -1 ? -1 : 1;
  const key = sort.key || 'population';
  return [...(members || [])].sort((a, b) => {
    if (key === 'city') {
      const al = `${a.city || ''}, ${a.state || ''}`;
      const bl = `${b.city || ''}, ${b.state || ''}`;
      return al.localeCompare(bl) * dir;
    }
    if (key === 'role') {
      const cmp = clusterRosterRoleRank(a.role) - clusterRosterRoleRank(b.role);
      if (cmp) return cmp * dir;
      return `${a.city || ''}`.localeCompare(`${b.city || ''}`) * dir;
    }
    const ap = Number(a.population);
    const bp = Number(b.population);
    const aOk = Number.isFinite(ap) && ap > 0;
    const bOk = Number.isFinite(bp) && bp > 0;
    if (aOk !== bOk) return aOk ? -1 : 1;
    if (!aOk) return 0;
    return (ap - bp) * dir;
  });
}

function renderClusterRosterHtml(detail) {
  const members = detail.shotgunMembers || [];
  if (!detail.shotgunClusterId) return '';
  const sort = state.clusterRosterSort || { key: 'population', dir: -1 };
  const mark = (key) => (sort.key === key ? (sort.dir === 1 ? ' ▲' : ' ▼') : '');
  const rows = sortClusterRosterMembers(members)
    .map((m) => {
      const ck = parseClusterKey(m.clusterKey);
      const isHub =
        String(m.role).toLowerCase() === 'hub' ||
        String(m.role).toLowerCase() === 'main';
      const remove = isHub
        ? ''
        : `<button type="button" class="btn btn-sm cluster-remove-city" data-city="${esc(m.city)}" data-state="${esc(m.state)}">Remove</button>`;
      const fill = clusterColor(ck);
      const clStyle = fill ? ` style="color:${fill};font-weight:700"` : '';
      return `<tr>
        <td>${esc(cityMapLabel(m.city, ck, { hub: isHub }))}, ${esc(m.state)}</td>
        <td${clStyle}>${esc(ck ? String(ck) : '—')}</td>
        <td class="cluster-roster-pop">${esc(formatShotgunPop(m.population))}</td>
        <td>${remove}</td>
      </tr>`;
    })
    .join('');
  return `<div class="cluster-roster" data-cluster-id="${esc(detail.shotgunClusterId)}">
    <h4 class="scores-heading">Zone roster</h4>
    <table class="scores-table"><thead><tr>
      <th class="sortable" data-sort="city" data-tip="Sort by city">City${mark('city')}</th>
      <th class="sortable" data-sort="cluster" data-tip="Cluster number. Click to sort.">Cl${mark('cluster')}</th>
      <th class="sortable" data-sort="population" data-tip="Population. Click to sort.">Pop${mark('population')}</th>
      <th></th>
    </tr></thead>
    <tbody>${rows}</tbody></table>
    <p class="cluster-add-row">
      <input id="cluster-add-city" placeholder="City" />
      <input id="cluster-add-state" placeholder="ST" maxlength="2" style="width:3.2rem" />
      <button type="button" class="btn btn-sm" id="cluster-add-btn">Add city</button>
    </p>
  </div>`;
}

function renderList() {
  const thead = document.querySelector('#candidate-table thead');
  const tbody = document.querySelector('#candidate-table tbody');
  if (!thead || !tbody) return;
  renderSourceLegend('candidate-source-legend');
  const sort = state.candidateSort;
  thead.innerHTML = `<tr>${CANDIDATE_TABLE_COLS.map((c) => {
    if (c.key === '_select') {
      return `<th data-tip="${esc(c.tip || '')}"><input type="checkbox" id="candidate-select-all" data-tip="Select filtered" /></th>`;
    }
    if (c.key === '_live') {
      const mark = sort.key === c.key ? (sort.dir === 1 ? ' ▲' : ' ▼') : '';
      const cls = [c.sortable ? 'sortable' : '', c.cellClass || ''].filter(Boolean).join(' ');
      return `<th class="${cls}" data-sort="${esc(c.key)}" data-tip="${esc(c.tip || '')}">${mark}</th>`;
    }
    if (c.key === '_stageProgress' || c.key === '_websiteTrack') {
      const mark = sort.key === c.key ? (sort.dir === 1 ? ' ▲' : ' ▼') : '';
      const cls = [c.sortable ? 'sortable' : '', c.cellClass || ''].filter(Boolean).join(' ');
      return `<th class="${cls}" data-sort="${esc(c.key)}" data-tip="${esc(c.tip || '')}"><span class="th-label th-rover-mark">${esc(
        c.label,
      )}</span>${mark}</th>`;
    }
    const mark = sort.key === c.key ? (sort.dir === 1 ? ' ▲' : ' ▼') : '';
    const cls = [c.sortable ? 'sortable' : '', c.cellClass || ''].filter(Boolean).join(' ');
    const srcTip =
      c.source && DISCOVERY_SOURCES[c.source] ? DISCOVERY_SOURCES[c.source].tip : '';
    const fullTip = [c.tip || c.label, srcTip].filter(Boolean).join(' · ');
    return `<th class="${cls}" data-sort="${esc(c.key)}" data-tip="${esc(fullTip)}"><span class="th-label">${discoverySourceDot(
      c.source,
    )}${esc(c.label)}</span>${mark}</th>`;
  }).join('')}</tr>`;

  const list = sortCandidates(filteredCandidates());
  if (!list.length) {
    tbody.innerHTML = `<tr><td colspan="${CANDIDATE_TABLE_COLS.length}" class="muted">${esc(
      emptyStateForFilter(),
    )}</td></tr>`;
    syncHeaderSelectAll(document.getElementById('candidate-select-all'), {
      selectedCount: 0,
      totalCount: 0,
    });
    updateCandidateSelectionCount();
    renderActions();
    return;
  }

  tbody.innerHTML = list
    .map((c) => {
      const active = c.id === state.selectedId ? 'active' : '';
      const checked = state.selectedIds.has(c.id) ? 'checked' : '';
      const overallInputs = candidateOverallInputs(c);
      const overall =
        computeProposedScore(overallInputs) ?? c.proposedScore ?? null;
      const cells = CANDIDATE_TABLE_COLS.map((col) => {
        const tdClass = col.cellClass ? ` class="${esc(col.cellClass)}"` : '';
        if (col.key === '_select') {
          return `<td${tdClass}><input type="checkbox" class="cand-check" data-id="${esc(
            c.id,
          )}" ${checked} /></td>`;
        }
        if (col.key === '_live') {
          return `<td${tdClass}>${isCandidateLaunched(c) ? launchedBadgeHtml() : ''}</td>`;
        }
        if (col.key === '_stageProgress') {
          return `<td${tdClass}>${stageStepIconHtml(candidateHighestStageStep(c))}</td>`;
        }
        if (col.key === '_websiteTrack') {
          return `<td${tdClass}>${stageStepIconHtml(
            candidateHighestWebsiteTrack(c),
            WEBSITE_TRACK_TIPS,
          )}</td>`;
        }
        if (col.key === 'niche') {
          const locked = Boolean(c.nicheRenameLocked);
          const tip = 'Double-click to rename.';
          const nicheClass = col.cellClass ? `${col.cellClass} cand-niche` : 'cand-niche';
          return `<td class="${esc(nicheClass)}" data-id="${esc(c.id)}" data-niche-locked="${
            locked ? '1' : '0'
          }" data-tip="${esc(tip)}"><span class="cell-text">${esc(c.niche || '—')}</span></td>`;
        }
        if (col.key === 'city') {
          const hub = String(c.shotgunRole || '').toLowerCase() === 'hub';
          const name = c.primaryCity || '—';
          const label = hub ? `★ ${name}` : name;
          const zoneBtn = c.shotgunClusterId
            ? ` <button type="button" class="btn btn-sm zone-map-open" data-zone-id="${esc(c.shotgunClusterId)}" data-tip="Open Zone map">Zone</button>`
            : '';
          return `<td${tdClass}><span class="cell-text">${esc(label)}</span>${zoneBtn}</td>`;
        }
        if (col.key === 'state') {
          return `<td${tdClass}><span class="cell-text">${esc(c.state || '—')}</span></td>`;
        }
        if (col.key === 'shotgunSg') {
          const sg = formatZnDisplay(c.sgNumber ?? c.shotgunSg);
          return `<td${tdClass}><span class="cell-text">${esc(sg || '—')}</span></td>`;
        }
        if (col.key === 'shotgunClusterKey') {
          const ck = rowClusterKey(c);
          const fill = clusterColor(ck);
          const style = fill ? ` style="color:${fill};font-weight:700"` : '';
          return `<td${tdClass}><span class="cell-text"${style}>${esc(ck ? String(ck) : '—')}</span></td>`;
        }
        if (col.key === 'population') {
          return `<td${tdClass}>${
            c.population == null ? '—' : esc(String(c.population))
          }</td>`;
        }
        if (col.key === 'researchMap') {
          const city = c.primaryCity || c.city || '';
          const st = c.state || '';
          if (!city || !st) return `<td${tdClass} class="muted">—</td>`;
          return `<td${tdClass}><button type="button" class="btn btn-sm cand-open-map" data-city="${esc(
            city,
          )}" data-state="${esc(st)}" data-tip="Open Map zoomed to ${esc(city)}, ${esc(
            st,
          )}">Map</button></td>`;
        }
        if (col.key === 'mapPack') {
          return `<td${tdClass}>${mapPackHtml(c.mapPackPresent, {
            reviewsLabel: c.mapPackReviewsLabel,
            avgReviews: c.mapPackAvgReviews,
            maxReviews: c.mapPackMaxReviews,
            hasLsa: c.hasLocalServicesAds,
          })}</td>`;
        }
        if (col.key === 'volume') {
          const honesty = adsVolumeHonesty({
            volumesSkipped: c.volumesSkipped,
            adsLocationFallback: c.adsLocationFallback,
            estimatedMonthlySearchVolume: c.estimatedMonthlySearchVolume,
            estimatedMonthlySearchVolumeRaw: c.estimatedMonthlySearchVolumeRaw,
          });
          return `<td${tdClass}>${demandVolumeHtml(
            honesty.mode === 'estimate'
              ? c.estimatedMonthlySearchVolume
              : c.demandVolumeSum ?? c.clusterVolumeSum,
            {
              alpha: c.suburbOverlapFactor,
              honesty,
            },
          )}</td>`;
        }
        if (col.key === 'jobCost') {
          return `<td${tdClass}><span class="cell-text">${esc(
            c.jobCostText || '—',
          )}</span></td>`;
        }
        if (col.key === 'orgHome') {
          const all = c.organicHomeCount;
          const niche = c.organicHomeNicheCount;
          if (all == null && niche == null) return `<td${tdClass}>—</td>`;
          const label =
            niche != null && all != null ? `${niche}/${all}` : esc(String(niche ?? all));
          const tip =
            niche != null && all != null
              ? `${niche} of ${all} homepages match this service.`
              : 'Homepage count.';
          return `<td${tdClass} data-tip="${esc(tip)}">${label}</td>`;
        }
        if (col.key === 'orgSub') {
          const all = c.organicSubCount;
          const niche = c.organicSubNicheCount;
          if (all == null && niche == null) return `<td${tdClass}>—</td>`;
          const label =
            niche != null && all != null ? `${niche}/${all}` : esc(String(niche ?? all));
          const tip =
            niche != null && all != null
              ? `${niche} of ${all} inner pages match this service.`
              : 'Inner page count.';
          return `<td${tdClass} data-tip="${esc(tip)}">${label}</td>`;
        }
        if (col.key === 'avgCpc') {
          if (c.averageCpc == null) return `<td${tdClass}>—</td>`;
          return `<td${tdClass}>$${esc(String(c.averageCpc))}</td>`;
        }
        if (col.key === 'proposedScore') {
          return `<td${tdClass}>${overallScoreHtml(overallInputs, overall, {
            compact: true,
          })}</td>`;
        }
        if (col.key === 'demand') {
          const v = overallInputs.demand;
          const estimated = overallInputs.demandSource === 'claude_estimate';
          return `<td${tdClass}>${
            v == null
              ? '—'
              : metricHtml({
                  value: v,
                  max: 10,
                  polarity: 'higher-better',
                  label: 'Demand',
                  extraTip: estimated
                    ? `${SCORE_INPUT_TIPS.demand} This number is a rough guess.`
                    : SCORE_INPUT_TIPS.demand,
                  suffix: estimated ? 'est.' : '',
                })
          }</td>`;
        }
        if (col.key === 'competition') {
          const v = overallInputs.competition;
          return `<td${tdClass}>${
            v == null
              ? '—'
              : metricHtml({
                  value: v,
                  max: 10,
                  polarity: 'higher-better',
                  label: 'Organic openness',
                  extraTip: competitionOpennessTip({
                    score: v,
                    uniqueDomainCount: c.uniqueOrganicDomains,
                    homepageCount: c.organicHomeCount,
                    medianDomainRank: c.medianDomainRank,
                  }),
                })
          }</td>`;
        }
        if (col.key === 'disp') {
          const disp = overallInputs.displaceability;
          if (disp == null) return `<td${tdClass}>—</td>`;
          return `<td${tdClass}>${metricHtml({
            value: disp,
            max: 10,
            polarity: 'higher-better',
            label: 'Displaceability',
            extraTip: SCORE_INPUT_TIPS.displaceability,
          })}</td>`;
        }
        if (col.key === 'jobValue') {
          const v = overallInputs.jobValue;
          return `<td${tdClass}>${
            v == null
              ? '—'
              : metricHtml({
                  value: v,
                  max: 10,
                  polarity: 'higher-better',
                  label: 'Job value',
                  extraTip: SCORE_INPUT_TIPS.jobValue,
                })
          }</td>`;
        }
        if (col.key === 'serpSoftness') {
          return `<td${tdClass}>${serpSoftnessHtml(c.serpSoftness)}</td>`;
        }
        if (col.key === 'decision') {
          const recTip = [c.recommended_decision, c.recommended_reason]
            .filter(Boolean)
            .join(' — ');
          const tip = recTip
            ? `Recommend: ${recTip}`
            : 'Saves as you choose.';
          return `<td${tdClass} data-tip="${esc(tip)}"><select class="cand-decision" data-id="${esc(c.id)}">${CANDIDATE_DECISION_OPTS.map(
            (o) =>
              `<option value="${esc(o)}" ${
                (c.decision || '') === o ? 'selected' : ''
              }>${esc(o || '—')}</option>`,
          ).join('')}</select></td>`;
        }
        if (col.key === 'prospects') {
          if (c.prospectCount == null) return `<td${tdClass}>—</td>`;
          const tip =
            c.highPriority != null ? `${c.highPriority} high priority` : 'Number of possible renters.';
          return `<td${tdClass} data-tip="${esc(tip)}">${esc(String(c.prospectCount))}${
            c.highPriority != null
              ? ` <span class="muted">(${esc(String(c.highPriority))}↑)</span>`
              : ''
          }</td>`;
        }
        if (col.key === 'batch') {
          const bid = c.source?.batchId || '';
          return `<td${tdClass}><span class="cell-text">${esc(
            bid || '—',
          )}</span></td>`;
        }
        if (col.key === 'notes') {
          const notes = c.decisionNotes || '';
          return `<td${tdClass}><input class="cand-notes" data-id="${esc(
            c.id,
          )}" value="${esc(notes)}" /></td>`;
        }
        if (col.key === 'apiSpend') {
          const spend = candidateApiSpendBreakdown(c);
          const tip = candidateApiSpendTip(spend);
          const label =
            spend.total == null ? '—' : esc(formatMoney(spend.total));
          return `<td${tdClass} data-tip="${esc(tip)}">${label}</td>`;
        }
        if (col.key === '_rank') {
          return `<td${tdClass}>${esc(candidatePipelineRank(c))}</td>`;
        }
        return `<td${tdClass}>—</td>`;
      });
      const sgAttr = clusterRowAttr(c);
      return `<tr class="${active}" data-id="${esc(c.id)}"${sgAttr}>${cells.join('')}</tr>`;
    })
    .join('');

  syncHeaderSelectAll(document.getElementById('candidate-select-all'), {
    selectedCount: list.filter((c) => state.selectedIds.has(c.id)).length,
    totalCount: list.length,
  });

  document.getElementById('candidate-select-all')?.addEventListener('change', (e) => {
    if (candidateSelectionLocked()) {
      e.target.checked = list.every((c) => state.selectedIds.has(c.id));
      return;
    }
    const on = e.target.checked;
    for (const c of list) {
      if (on) state.selectedIds.add(c.id);
      else state.selectedIds.delete(c.id);
    }
    updateCandidateSelectionCount();
    renderList();
    if (state.selectedIds.size > 1) {
      renderActions();
      renderMultiDetail();
    } else if (state.selectedIds.size === 1) {
      void selectCandidate([...state.selectedIds][0]);
    } else {
      renderActions();
      syncCandidatesDetailVisibility();
    }
  });
  thead.querySelectorAll('th.sortable').forEach((th) => {
    th.addEventListener('click', () => {
      const key = th.dataset.sort;
      if (state.candidateSort.key === key) state.candidateSort.dir *= -1;
      else state.candidateSort = { key, dir: key === 'proposedScore' || key === '_live' || key === '_rank' || key === '_websiteTrack' ? -1 : 1 };
      persistUiRestore();
      renderList();
    });
  });
  tbody.querySelectorAll('tr').forEach((tr) => {
    tr.addEventListener('click', (e) => {
      if (
        e.target.closest(
          'input.cand-check, select.cand-decision, input.cand-notes, input.cand-niche-input, button.cand-open-map',
        )
      )
        return;
      selectCandidate(tr.dataset.id);
    });
  });
  tbody.querySelectorAll('button.cand-open-map').forEach((btn) => {
    btn.addEventListener('click', async (e) => {
      e.stopPropagation();
      const city = btn.dataset.city || '';
      const st = btn.dataset.state || '';
      setView('map');
      try {
        await openResearchMap({ city, state: st }, { api, esc, showModal });
      } catch (error) {
        await showModal({
          title: 'Map failed',
          confirmLabel: 'OK',
          hideCancel: true,
          bodyHtml: `<p>${esc(error.message)}</p>`,
        });
      }
    });
  });
  tbody.querySelectorAll('.cand-check').forEach((cb) => {
    const applyCandShiftRange = (e) => {
      const id = cb.dataset.id;
      return applyShiftRangeCheckboxClick(e, {
        visibleKeys: list.map((c) => c.id),
        clickedKey: id,
        anchorKey: state.candidateCheckAnchor,
        setAnchor: (key) => {
          state.candidateCheckAnchor = key;
        },
        setSelected: (key, on) => {
          if (on) state.selectedIds.add(key);
          else state.selectedIds.delete(key);
        },
      });
    };
    cb.addEventListener('pointerdown', (e) => {
      e.stopPropagation();
      if (candidateSelectionLocked()) {
        e.preventDefault();
        cb.checked = state.selectedIds.has(cb.dataset.id);
        return;
      }
      if (!e.shiftKey || state.candidateCheckAnchor == null) return;
      blockShiftRangePointerDown(e, state.candidateCheckAnchor);
      if (applyCandShiftRange(e)) afterCandidateCheckboxSelection(list);
    });
    cb.addEventListener('click', (e) => {
      e.stopPropagation();
      if (candidateSelectionLocked()) {
        e.preventDefault();
        cb.checked = state.selectedIds.has(cb.dataset.id);
        return;
      }
      if (applyCandShiftRange(e)) afterCandidateCheckboxSelection(list);
    });
    cb.addEventListener('change', (e) => {
      e.stopPropagation();
      if (candidateSelectionLocked()) {
        cb.checked = state.selectedIds.has(cb.dataset.id);
        return;
      }
      const id = cb.dataset.id;
      if (consumeShiftRangeChange(cb, id)) {
        cb.checked = state.selectedIds.has(id);
        return;
      }
      state.candidateCheckAnchor = id;
      if (cb.checked) state.selectedIds.add(id);
      else state.selectedIds.delete(id);
      afterCandidateCheckboxSelection(list);
    });
  });
  tbody.querySelectorAll('select.cand-decision').forEach((sel) => {
    sel.addEventListener('click', (e) => e.stopPropagation());
    sel.addEventListener('change', (e) => {
      e.stopPropagation();
      void persistCandidateDecision(sel.dataset.id, sel.value);
    });
  });
  tbody.querySelectorAll('td.cand-niche').forEach((td) => {
    td.addEventListener('dblclick', (e) => {
      e.preventDefault();
      e.stopPropagation();
      void beginCandidateNicheEdit(td);
    });
  });
  tbody.querySelectorAll('input.cand-notes').forEach((inp) => {
    inp.addEventListener('click', (e) => e.stopPropagation());
    inp.addEventListener('blur', () => {
      const row = state.candidates.find((x) => x.id === inp.dataset.id);
      const next = inp.value;
      if ((row?.decisionNotes || '') === next) return;
      void persistCandidateDecision(inp.dataset.id, row?.decision || '', next);
    });
  });
  updateCandidateSelectionCount();
  renderActions();
  enableTableColumnResize(document.getElementById('candidate-table'), {
    freezeCols: 7,
  });
}

async function bindClusterRoster(detail) {
  const clusterId = detail?.shotgunClusterId;
  if (!clusterId) return;
  document.querySelectorAll('.cluster-roster th.sortable').forEach((th) => {
    th.addEventListener('click', () => {
      const key = th.dataset.sort;
      if (!key) return;
      const cur = state.clusterRosterSort || { key: 'population', dir: -1 };
      if (cur.key === key) state.clusterRosterSort = { key, dir: cur.dir === 1 ? -1 : 1 };
      else state.clusterRosterSort = { key, dir: key === 'population' ? -1 : 1 };
      const wrap = document.querySelector('.cluster-roster');
      if (!wrap) return;
      wrap.outerHTML = renderClusterRosterHtml(detail);
      void bindClusterRoster(detail);
    });
  });
  document.getElementById('cluster-add-btn')?.addEventListener('click', async () => {
    const city = String(document.getElementById('cluster-add-city')?.value || '').trim();
    const stateAbbr = String(document.getElementById('cluster-add-state')?.value || '').trim().toUpperCase();
    if (!city || stateAbbr.length !== 2) {
      showToast('Enter a city and two-letter state', { tone: 'warn' });
      return;
    }
    try {
      await api(`/api/shotgun-clusters/${encodeURIComponent(clusterId)}/members`, {
        method: 'POST',
        body: JSON.stringify({ city, state: stateAbbr }),
      });
      showToast(`Added ${city}, ${stateAbbr} to the cluster`);
      await loadCandidates();
      await selectCandidate(detail.id);
    } catch (error) {
      if (error.code === 'OUTSIDE_CLUSTER_BAND' || /outside the typical cluster/i.test(error.message || '')) {
        const ok = await showModal({
          title: 'Outside typical cluster',
          confirmLabel: 'Add anyway',
          bodyHtml: `<p>${esc(error.message)}</p>`,
        });
        if (!ok) return;
        await api(`/api/shotgun-clusters/${encodeURIComponent(clusterId)}/members`, {
          method: 'POST',
          body: JSON.stringify({ city, state: stateAbbr, confirmOutside: true }),
        });
        showToast(`Added ${city}, ${stateAbbr} to the cluster`);
        await loadCandidates();
        await selectCandidate(detail.id);
        return;
      }
      await showModal({
        title: 'Could not add city',
        confirmLabel: 'OK',
        hideCancel: true,
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });
  document.querySelectorAll('.cluster-remove-city').forEach((btn) => {
    btn.addEventListener('click', async () => {
      const city = btn.dataset.city;
      const st = btn.dataset.state;
      const pick = { archive: false, delete: false };
      const choice = await showModal({
        title: `Remove ${city}, ${st}?`,
        confirmLabel: 'Keep as standalone',
        cancelLabel: 'Cancel',
        bodyHtml: `<p>Remove this Cluster City from the cluster. Evaluation data is kept.</p>
          <p class="muted small">Site-config updates now. Already-launched HTML location pages stay until the next Assemble / Write.</p>
          <p class="cluster-remove-extra">
            <button type="button" class="btn" id="cluster-remove-archive">Archive instead</button>
            <button type="button" class="btn danger" id="cluster-remove-delete">Delete permanently</button>
          </p>`,
        afterOpen: (body) => {
          body.querySelector('#cluster-remove-archive')?.addEventListener('click', () => {
            pick.archive = true;
            document.getElementById('modal-confirm')?.click();
          });
          body.querySelector('#cluster-remove-delete')?.addEventListener('click', () => {
            pick.delete = true;
            document.getElementById('modal-confirm')?.click();
          });
        },
      });
      if (!choice) return;
      if (pick.delete) {
        const typed = await showModal({
          title: 'Type to confirm permanent delete',
          confirmLabel: 'Delete permanently',
          danger: true,
          requireTypedConfirm: 'DELETE',
          bodyHtml: `<p>Remove <strong>${esc(city)}, ${esc(st)}</strong> from the cluster and permanently delete its Rover files and local assembled folder. This cannot be undone from the UI.</p>
            <p class="muted small">Launched cities are blocked. Unlaunched Research and Website Cluster Cities can be deleted.</p>`,
        });
        if (!typed) return;
      }
      const disposition = pick.delete ? 'delete' : pick.archive ? 'archive' : 'standalone';
      try {
        const result = await api(`/api/shotgun-clusters/${encodeURIComponent(clusterId)}/members/remove`, {
          method: 'POST',
          body: JSON.stringify({ city, state: st, disposition }),
        });
        showToast(
          pick.delete ? `Deleted ${city}, ${st}` : `Removed ${city}, ${st}`,
        );
        await loadCandidates();
        const removedId = result.removed?.candidateId;
        const stillHere = state.candidates.some((c) => c.id === detail.id);
        if (pick.delete && removedId && detail.id === removedId) {
          const hub = (result.cluster?.members || []).find((m) => {
            const r = String(m.role || '').toLowerCase();
            return r === 'hub' || r === 'main';
          });
          if (hub?.candidateId) await selectCandidate(hub.candidateId);
          else {
            state.selectedId = null;
            state.detail = null;
            syncCandidatesDetailVisibility();
            renderList();
            renderActions();
          }
        } else if (stillHere) {
          await selectCandidate(detail.id);
        } else {
          renderList();
          renderActions();
        }
      } catch (error) {
        if (error.code === 'UNDELETABLE_CANDIDATE') {
          await showModal({
            title: 'Cannot delete Launched',
            confirmLabel: 'OK',
            hideCancel: true,
            bodyHtml: `<p>Launched Candidates cannot be permanently deleted from Rover.</p>
              <p>${esc(error.message)}</p>
              <p class="muted">Keep as standalone or Archive instead.</p>`,
          });
          return;
        }
        await showModal({
          title: 'Could not remove city',
          confirmLabel: 'OK',
          hideCancel: true,
          bodyHtml: `<p>${esc(error.message)}</p>`,
        });
      }
    });
  });
}

let websiteLeaseTimer = 0;
let websiteLeaseUiWired = false;

function websiteLeaseNeeded() {
  if (state.view !== 'website-builder') return false;
  if (state.selectedIds.size > 1) return false;
  const id = state.selectedId;
  if (!id) return false;
  const c = state.candidates.find((x) => x.id === id) || state.detail;
  if (!c) return false;
  return c.decision === 'pursue' || isWebsiteLaunched(c);
}

function applyWebsiteLeaseState(candidateId, payload) {
  state.websiteLease = {
    candidateId: candidateId || null,
    mine: payload?.mine !== false,
    holderTabId: payload?.holderTabId || null,
  };
  syncWebsiteWriteLockBanner();
}

function syncWebsiteWriteLockBanner() {
  const el = document.getElementById('website-write-lock-banner');
  const detail = document.getElementById('detail');
  if (!el || !detail) return;
  if (!websiteLeaseUiWired) {
    websiteLeaseUiWired = true;
    el.addEventListener('click', (ev) => {
      if (ev.target.closest('.website-lease-takeover')) {
        ev.preventDefault();
        void takeoverWebsiteWriteLease();
      }
    });
    window.addEventListener('pagehide', releaseWebsiteWriteLeaseOnLeave);
  }
  const locked =
    websiteLeaseNeeded() &&
    String(state.websiteLease.candidateId || '') === String(state.selectedId || '') &&
    state.websiteLease.mine === false;
  detail.classList.toggle('website-write-locked', locked);
  if (!locked) {
    el.classList.add('hidden');
    el.hidden = true;
    el.innerHTML = '';
    return;
  }
  el.hidden = false;
  el.classList.remove('hidden');
  el.innerHTML = `<p><strong>Website editing is locked in another tab.</strong> You can look. You cannot change grades, photos, Site-Config, or Visual Edit until that tab closes or you Take over.</p><button type="button" class="btn website-lease-takeover">Take over</button>`;
}

function stopWebsiteLeaseHeartbeat() {
  if (websiteLeaseTimer) {
    clearInterval(websiteLeaseTimer);
    websiteLeaseTimer = 0;
  }
}

function writeSiteInFlightTrack() {
  const track = state._writeSiteTrack;
  if (!track?.jobId || !track?.candidateId) return null;
  if (state._writeSiteHandledJobId === track.jobId) return null;
  return track;
}

function leaseIdsToHeartbeat() {
  const ids = [];
  if (websiteLeaseNeeded() && state.websiteLease.mine && state.websiteLease.candidateId) {
    ids.push(String(state.websiteLease.candidateId));
  }
  const track = writeSiteInFlightTrack();
  if (track && writeSiteTrackHoldsLease(track.candidateId, track)) {
    const tid = String(track.candidateId);
    if (!ids.includes(tid)) ids.push(tid);
  }
  return ids;
}

function startWebsiteLeaseHeartbeat() {
  stopWebsiteLeaseHeartbeat();
  websiteLeaseTimer = setInterval(() => {
    const ids = leaseIdsToHeartbeat();
    if (!ids.length) {
      stopWebsiteLeaseHeartbeat();
      return;
    }
    for (const leaseId of ids) {
      api(`/api/candidates/${encodeURIComponent(leaseId)}/website-lease/heartbeat`, {
        method: 'POST',
        body: '{}',
        quietLock: true,
      }).catch((error) => {
        if (error?.code !== 'WEBSITE_WRITE_LOCKED') return;
        if (String(state.websiteLease.candidateId || '') !== String(leaseId)) return;
        applyWebsiteLeaseState(leaseId, { mine: false, holderTabId: error.holderTabId });
      });
    }
  }, 5000);
}

async function releaseHeldWebsiteLease(id) {
  if (!id) return;
  try {
    await api(`/api/candidates/${encodeURIComponent(id)}/website-lease`, { method: 'DELETE' });
  } catch {
    /* ignore */
  }
}

function releaseWebsiteWriteLeaseOnLeave() {
  const ids = new Set();
  if (state.websiteLease.candidateId && state.websiteLease.mine) {
    ids.add(state.websiteLease.candidateId);
  }
  const track = writeSiteInFlightTrack();
  if (track?.candidateId) ids.add(track.candidateId);
  for (const id of ids) {
    try {
      fetch(`/api/candidates/${encodeURIComponent(id)}/website-lease`, {
        method: 'DELETE',
        headers: { 'content-type': 'application/json', 'X-Rover-Tab-Id': ROVER_TAB_ID },
        keepalive: true,
      });
    } catch {
      /* ignore */
    }
  }
}

async function refreshWebsiteWriteLease() {
  stopWebsiteLeaseHeartbeat();
  const prev = state.websiteLease.candidateId;
  const holdTrack = writeSiteInFlightTrack();
  if (!websiteLeaseNeeded()) {
    stopWebsiteLeaseHeartbeat();
    if (prev && state.websiteLease.mine) await releaseHeldWebsiteLease(prev);
    if (holdTrack?.candidateId && holdTrack.candidateId !== prev) {
      await releaseHeldWebsiteLease(holdTrack.candidateId);
    }
    applyWebsiteLeaseState(null, { mine: true, holderTabId: null });
    return;
  }
  const id = state.selectedId;
  if (
    prev &&
    prev !== id &&
    state.websiteLease.mine &&
    !writeSiteTrackHoldsLease(prev, holdTrack)
  ) {
    await releaseHeldWebsiteLease(prev);
  }
  try {
    const claimed = await api(`/api/candidates/${encodeURIComponent(id)}/website-lease`, {
      method: 'POST',
      body: JSON.stringify({ takeover: false }),
    });
    applyWebsiteLeaseState(id, claimed);
    if (claimed.mine || writeSiteTrackHoldsLease(holdTrack?.candidateId, holdTrack)) {
      startWebsiteLeaseHeartbeat();
    } else {
      stopWebsiteLeaseHeartbeat();
    }
  } catch {
    applyWebsiteLeaseState(id, { mine: true, holderTabId: null });
    if (writeSiteTrackHoldsLease(holdTrack?.candidateId, holdTrack)) startWebsiteLeaseHeartbeat();
  }
}

async function takeoverWebsiteWriteLease() {
  const id = state.selectedId;
  if (!id) return;
  const ok = await showModal({
    title: 'Take over editing?',
    confirmLabel: 'Take over',
    bodyHtml:
      '<p>This will steal editing from the other tab. Unsaved typing there can be lost.</p>',
  });
  if (!ok) return;
  try {
    const claimed = await api(`/api/candidates/${encodeURIComponent(id)}/website-lease`, {
      method: 'POST',
      body: JSON.stringify({ takeover: true }),
    });
    applyWebsiteLeaseState(id, claimed);
    if (claimed.mine) startWebsiteLeaseHeartbeat();
  } catch (error) {
    showToast(error.message || 'Could not take over editing.', { tone: 'err' });
  }
}

async function selectCandidate(id) {
  if (candidateSelectionLocked()) return;
  if (state.selectedId && state.selectedId !== id) stopWebsiteLeaseHeartbeat();
  state.selectedId = id;
  syncWebsiteWriteLockBanner();
  state.multiQueue = false;
  state.contentOpenStep = null;
  state.websiteOpenStep = null;
  state.siteConfigOpenStep = null;
  state.contentFollowCurrent = undefined;
  state.websiteFollowCurrent = undefined;
  state.siteConfigFollowCurrent = undefined;
  state.contentSoftCurrent = null;
  state.websiteSoftCurrent = null;
  state.siteConfigSoftCurrent = null;
  state.contentSoftDone = {};
  state.websiteSoftDone = {};
  state.siteConfigSoftDone = {};
  state.assembleProgress = { visible: false, detail: '', done: null, total: null };
  state.preparePreviewHold = false;
  state.preparePreviewJobId = null;
  state.preparePreviewTab = null;
  state.reviewImageSlots = [];
  state.reviewBa = null;
  state.reviewPhotoGroupMenuOpen = false;
  if (state.selectedIds.size > 1) {
    renderList();
    renderMultiDetail();
    renderActions();
    persistUiRestore();
    return;
  }
  // Keep checkbox selection aligned with the open detail (avoids Accept hitting another id)
  state.selectedIds.clear();
  state.selectedIds.add(id);
  renderList();
  syncCandidatesDetailVisibility();
  document.getElementById('empty-detail').classList.add('hidden');
  document.getElementById('detail').classList.remove('hidden');
  try {
    await loadSelectedCandidateDetail(id);
    if (state.selectedId === id) {
      await refreshWebsiteWriteLease();
      renderDetail();
    }
  } catch (error) {
    if (error?.name === 'AbortError') return;
    throw error;
  } finally {
    persistUiRestore();
  }
}

function renderMultiDetail() {
  const ids = [...state.selectedIds];
  if (ids.length <= 1) {
    state.multiQueue = false;
    if (state.selectedId) renderDetail();
    return;
  }
  state.multiQueue = true;
  document.getElementById('empty-detail').classList.add('hidden');
  document.getElementById('detail').classList.remove('hidden');
  const titleEl = document.getElementById('detail-title');
  titleEl.textContent = `${ids.length} candidates selected`;
  setElementTip(titleEl, '');
  titleEl.removeAttribute('aria-label');
  const idTip = document.getElementById('detail-id-tip');
  if (idTip) {
    idTip.classList.add('hidden');
    setElementTip(idTip, '');
    idTip.setAttribute('aria-label', 'Candidate id');
  }
  document.getElementById('detail-sub').textContent =
    'Stage rail runs on the full selection · click a row to focus one candidate';
  renderActions();
  document.querySelectorAll('.tab').forEach((tab) => {
    tab.classList.toggle('active', tab.dataset.tab === 'overview');
  });
  const byId = new Map(state.candidates.map((c) => [c.id, c]));
  const batchKids = state.lastBatchJob?.children || [];
  const jobById = new Map(batchKids.map((c) => [c.candidateId, c]));
  const agg = aggregateSelectedFlags();
  const draftCount = agg.hasNarrativeDraft || 0;
  const busy = Boolean(state.activeJobId || state.activeBatchJobId || state.claudeBusy);
  const rows = ids
    .map((id) => {
      const c = byId.get(id) || { id };
      const job = jobById.get(id);
      const jobCell = job
        ? `${esc(job.status)}${job.error ? ` · ${esc(job.error)}` : ''}`
        : '—';
      return `<tr data-focus-id="${esc(id)}">
        <td>${esc(id)}</td>
        <td>${esc(c.niche || '')}</td>
        <td>${esc([c.primaryCity, c.state].filter(Boolean).join(', '))}</td>
        <td>${esc(c.stage || '')}</td>
        <td>${esc(c.decision || '—')}</td>
        <td>${jobCell}</td>
      </tr>`;
    })
    .join('');
  const narrBatch =
    draftCount > 0
      ? `<div class="narrative-actions multi-queue-narrative">
          <button type="button" class="btn primary" data-act="accept" ${busy ? 'disabled' : ''} data-tip="Accept the saved write-ups for the selected rows.">Accept draft (${draftCount})</button>
          <button type="button" class="btn danger" data-act="reject" ${busy ? 'disabled' : ''} data-tip="Throw away the saved write-ups for the selected rows.">Reject draft (${draftCount})</button>
        </div>`
      : '';
  document.getElementById('tab-panels').innerHTML = `
    <div class="multi-queue">
      <p class="muted">Queue for batch stages. Focus a row for Narrative tab Accept / single detail.</p>
      ${narrBatch}
      <table>
        <thead><tr><th>ID</th><th>Niche</th><th>City</th><th>Stage</th><th>Decision</th><th>Last batch</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>`;
  document.querySelectorAll('[data-focus-id]').forEach((tr) => {
    tr.addEventListener('click', () => selectCandidate(tr.dataset.focusId));
  });
  document.querySelectorAll('#tab-panels [data-act]').forEach((btn) => {
    btn.addEventListener('click', () => handleAction(btn.dataset.act, btn));
  });
  enableResizableTablesIn(document.getElementById('tab-panels'), {
    storagePrefix: 'detail:multi',
  });
}

function stageCheckMark() {
  return `<span class="stage-check" ${tipAttr('Completed')}>✓</span>`;
}

function stageDraftMark() {
  return `<span class="stage-draft" ${tipAttr('A draft is saved and not accepted yet.')}>draft</span>`;
}

function updateTabCompletion() {
  const f = state.detail?.stageFlags || {};
  const labels = {
    overview: 'Overview',
    serp: '1 · SERP / Volume',
    keywords: '1 · Keywords',
    enrichment: '2 · Enrich',
    narrative: '3 · Narrative',
    'site-config': '1 · Site-Config',
    content: '2 · Content',
    website: '3 · Launch',
    prospects: '4 · Prospects',
  };
  document.querySelectorAll('.tab').forEach((tab) => {
    const key = tab.dataset.tab;
    const base = labels[key] || tab.textContent.replace(/[✓·].*$/, '').trim();
    let done = false;
    let draft = false;
    if (key === 'serp') done = Boolean(f.hasResearch);
    if (key === 'keywords') done = Boolean(f.hasVolumes);
    if (key === 'enrichment') done = Boolean(f.hasEnrichment);
    if (key === 'narrative') {
      done = Boolean(f.hasNarrative);
      draft = Boolean(f.hasNarrativeDraft) && !f.hasNarrative;
    }
    if (key === 'site-config') {
      done = isWebsiteTrackComplete(state.detail, 1);
      draft = Boolean(f.hasSiteConfigDraft) && !f.hasSiteConfig;
    }
    if (key === 'content') {
      done = isWebsiteTrackComplete(state.detail, 2);
      draft =
        !f.hasContentUnreadable &&
        (Boolean(f.hasContentDraft) || Boolean(f.hasContentBrief)) &&
        !f.hasContent;
    }
    if (key === 'website') {
      const meta = state.detail?.meta || {};
      done = isWebsiteTrackComplete(state.detail, 3);
      draft =
        Boolean(meta.lastAssembleAt || meta.lastSiteStagingAt) &&
        !isWebsiteLaunched(state.detail);
    }
    if (key === 'prospects') done = Boolean(f.hasProspects);
    tab.classList.toggle('tab-done', done);
    tab.classList.toggle('tab-draft', draft);
    tab.innerHTML = done
      ? `${esc(base)} ${stageCheckMark()}`
      : draft
        ? `${esc(base)} ${stageDraftMark()}`
        : esc(base);
    tab.classList.toggle('active', key === state.tab);
    if (key === 'keywords') {
      setElementTip(tab, 'Keyword search volume for this city.');
    }
  });
}

