/** Bare hostname for NAP / Domain field (no protocol, path, or trailing slash). */
function normalizeDomainHostname(raw) {
  let s = String(raw || '').trim().toLowerCase();
  if (!s) return '';
  s = s.replace(/^https?:\/\//i, '');
  s = s.replace(/^www\./i, '');
  s = s.split('/')[0].split('?')[0].split('#')[0].trim();
  s = s.replace(/\.$/, '');
  if (!/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/i.test(s)) {
    return s.includes('.') ? s : '';
  }
  return s;
}

/** Mirrors ops/lib/site-config.mjs businessNameFromDomain (browser cannot import ops/lib). */
function businessNameFromDomainClient(domain, { primaryCity, niche } = {}) {
  const normKey = (s) =>
    String(s || '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '');
  const titleWord = (w) => {
    const s = String(w || '').trim();
    if (!s) return '';
    if (/^(hvac|llc|inc)$/i.test(s)) return s.toUpperCase();
    return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
  };
  const suffixes = ['experts', 'solutions', 'group', 'elite', 'pros', 'pro'];
  const leftover = [
    'installation',
    'installations',
    'repair',
    'repairs',
    'service',
    'services',
    'cleaning',
    'plumbing',
    'plumber',
    'roofing',
    'concrete',
    'drywall',
    'sewer',
    'drain',
    'fencing',
    'fence',
    'painting',
    'garage',
    'windows',
    'siding',
    'hvac',
    'door',
    'doors',
  ];

  let host = String(domain || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./, '');
  host = host.split('/')[0].split('?')[0].split('#')[0].replace(/\.$/, '');
  const label = (host.split('.')[0] || host).replace(/[^a-z0-9]/g, '');
  if (!label) return '';

  let rest = label;
  const parts = [];

  const cityRaw = String(primaryCity || '').trim();
  const citySlug = normKey(cityRaw);
  if (citySlug && rest.startsWith(citySlug)) {
    parts.push(cityRaw);
    rest = rest.slice(citySlug.length);
  }

  const nicheRaw = String(niche || '').trim();
  const nicheLabel = nicheRaw
    .split(/\s+/)
    .filter(Boolean)
    .map(titleWord)
    .join(' ');
  const nicheSlug = normKey(nicheRaw);
  if (nicheSlug && rest.startsWith(nicheSlug)) {
    parts.push(nicheLabel);
    rest = rest.slice(nicheSlug.length);
  } else if (nicheRaw) {
    const nicheWords = nicheRaw.split(/\s+/).filter(Boolean);
    const peeled = [];
    let cursor = rest;
    for (const w of nicheWords) {
      const ws = normKey(w);
      if (ws && cursor.startsWith(ws)) {
        peeled.push(w);
        cursor = cursor.slice(ws.length);
      } else {
        peeled.length = 0;
        break;
      }
    }
    if (peeled.length) {
      parts.push(peeled.map(titleWord).join(' '));
      rest = cursor;
    }
  }

  const sortedSuffixes = [...suffixes].sort((a, b) => b.length - a.length);
  const suffixParts = [];
  let guard = 0;
  while (rest && guard++ < 8) {
    let hit = false;
    for (const suf of sortedSuffixes) {
      if (rest === suf || (rest.endsWith(suf) && rest.length >= suf.length)) {
        suffixParts.unshift(titleWord(suf));
        rest = rest.slice(0, -suf.length);
        hit = true;
        break;
      }
    }
    if (!hit) break;
  }

  if (rest) {
    const known = [...leftover].sort((a, b) => b.length - a.length);
    let cursor = rest;
    let peelGuard = 0;
    while (cursor && peelGuard++ < 24) {
      let hit = false;
      for (const k of known) {
        if (cursor.startsWith(k)) {
          parts.push(titleWord(k));
          cursor = cursor.slice(k.length);
          hit = true;
          break;
        }
      }
      if (hit) continue;
      let bestIdx = -1;
      let bestLen = 0;
      for (const k of known) {
        const idx = cursor.indexOf(k);
        if (idx > 0 && (bestIdx < 0 || idx < bestIdx || (idx === bestIdx && k.length > bestLen))) {
          bestIdx = idx;
          bestLen = k.length;
        }
      }
      if (bestIdx > 0) {
        parts.push(titleWord(cursor.slice(0, bestIdx)));
        cursor = cursor.slice(bestIdx);
        continue;
      }
      parts.push(titleWord(cursor));
      break;
    }
  }

  parts.push(...suffixParts);
  const name = parts.join(' ').replace(/\s+/g, ' ').trim();
  if (name) return name;
  return label
    .split(/[^a-z0-9]+/i)
    .filter(Boolean)
    .map(titleWord)
    .join(' ');
}

/** Parse Claude domain-pick paste into up to 10 suggestion rows. */
function parseDomainPickPaste(text) {
  const raw = String(text || '').trim();
  if (!raw) return [];
  const out = [];
  const pushRow = (domain, available, note) => {
    const host = normalizeDomainHostname(domain);
    if (!host || out.some((r) => r.domain === host)) return;
    let avail = null;
    if (available === true || available === 'true' || available === 'yes') avail = true;
    else if (available === false || available === 'false' || available === 'no') avail = false;
    out.push({
      domain: host,
      available: avail,
      note: String(note || '').trim() || null,
    });
  };
  try {
    const start = raw.indexOf('{');
    const end = raw.lastIndexOf('}');
    if (start >= 0 && end > start) {
      const obj = JSON.parse(raw.slice(start, end + 1));
      const list = Array.isArray(obj?.domains) ? obj.domains : Array.isArray(obj) ? obj : null;
      if (list) {
        for (const row of list) {
          if (typeof row === 'string') pushRow(row, null, null);
          else if (row && typeof row === 'object') {
            pushRow(row.domain || row.host || row.url, row.available, row.note || row.reason);
          }
          if (out.length >= 10) break;
        }
      }
    }
  } catch {
    /* fall through to line parse */
  }
  if (!out.length) {
    for (const line of raw.split(/\r?\n/)) {
      const cleaned = line
        .replace(/^\s*[-*•]\s*/, '')
        .replace(/^\s*\d+[.)]\s*/, '')
        .trim();
      if (!cleaned) continue;
      const hostMatch = cleaned.match(
        /(?:https?:\/\/)?(?:www\.)?([a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+)/i,
      );
      if (!hostMatch) continue;
      pushRow(hostMatch[1], null, cleaned.replace(hostMatch[0], '').replace(/^[\s—\-|:]+/, '').trim());
      if (out.length >= 10) break;
    }
  }
  return out.slice(0, 10);
}

function writeDomainPickToNap(
  { domainPick: pickPatch, domain, businessName, email } = {},
  candidateId,
) {
  const id = candidateId || state.selectedId || state.detail?.id;
  const prev = siteConfigNapFromLocal(id);
  const prevPick =
    prev.domainPick && typeof prev.domainPick === 'object' ? prev.domainPick : {};
  const nap = {
    ...prev,
    domainPick: pickPatch ? { ...prevPick, ...pickPatch } : prevPick,
  };
  if (domain != null) nap.domain = String(domain);
  if (businessName != null) nap.businessName = String(businessName);
  if (email != null) nap.email = String(email);
  writeSiteConfigNapLocal(nap, id);
  return nap;
}

function domainSuggestCity(d) {
  const baPkg = d?.businessAddress;
  const draft = d?.siteConfigDraft;
  const accepted = d?.siteConfig;
  const pack = d?.approved;
  return String(
    (baPkg?.city && String(baPkg.city).trim()) ||
      (draft || accepted)?.primaryCity ||
      pack?.primaryCity ||
      pack?.city ||
      '',
  ).trim();
}

function domainSuggestNiche(d) {
  return String(
    d?.approved?.niche || d?.siteConfig?.niche || d?.summary?.niche || d?.niche || '',
  ).trim();
}

function domainSuggestionSignature(rows) {
  return (Array.isArray(rows) ? rows : [])
    .map((row) => {
      const host = String(row?.domain || '')
        .trim()
        .toLowerCase();
      const avail = row?.available === true ? '1' : row?.available === false ? '0' : '';
      return `${host}|${avail}|${row?.note || ''}`;
    })
    .join('\n');
}

const nicheDomainPatternCache = new Map();
const nicheDomainPatternPending = new Set();
const nicheDomainPatternFailed = new Set();
let nicheDomainPatternEpoch = 0;

function rememberNicheDomainPatterns(niche, patterns) {
  const key = nichePatternKey(niche);
  const list = Array.isArray(patterns)
    ? patterns.map((item) => String(item || '').trim()).filter(Boolean)
    : [];
  if (key) {
    nicheDomainPatternEpoch += 1;
    nicheDomainPatternCache.set(key, list);
    nicheDomainPatternFailed.delete(key);
  }
  return list;
}

async function loadNicheDomainPatterns(niche) {
  const key = nichePatternKey(niche);
  if (!key) return [];
  if (nicheDomainPatternCache.has(key)) return nicheDomainPatternCache.get(key);
  const epoch = nicheDomainPatternEpoch;
  const data = await api(`/api/niche-domain-patterns?niche=${encodeURIComponent(niche)}`);
  if (nicheDomainPatternEpoch !== epoch && nicheDomainPatternCache.has(key)) {
    return nicheDomainPatternCache.get(key);
  }
  return rememberNicheDomainPatterns(niche, data?.patterns);
}

function ensureNicheDomainPatterns(niche) {
  const key = nichePatternKey(niche);
  if (
    !key ||
    nicheDomainPatternCache.has(key) ||
    nicheDomainPatternPending.has(key) ||
    nicheDomainPatternFailed.has(key)
  ) {
    return;
  }
  nicheDomainPatternPending.add(key);
  loadNicheDomainPatterns(niche)
    .catch(() => {
      if (!nicheDomainPatternCache.has(key)) nicheDomainPatternFailed.add(key);
    })
    .finally(() => {
      nicheDomainPatternPending.delete(key);
      if (state.tab !== 'site-config') return;
      if (nichePatternKey(domainSuggestNiche(state.detail)) !== key) return;
      const patternInput = document.getElementById('sc-domain-niche-pattern');
      if (
        patternInput &&
        document.activeElement === patternInput &&
        patternInput.value.trim()
      ) {
        return;
      }
      renderDetail();
    });
}

function suggestionsWithNichePatterns(suggestions, niche, city) {
  const key = nichePatternKey(niche);
  if (!key || !nicheDomainPatternCache.has(key) || !city) return suggestions || [];
  return mergeNicheDomainSuggestions(suggestions || [], nicheDomainPatternCache.get(key), city);
}

async function saveNicheDomainPattern(d) {
  const niche = domainSuggestNiche(d);
  const raw = document.getElementById('sc-domain-niche-pattern')?.value || '';
  if (!niche) {
    showToast('This candidate has no niche to save a pattern on.', { tone: 'warn' });
    return;
  }
  const norm = normalizeNicheDomainPattern(raw);
  if (!norm.ok) {
    showToast(norm.error, { tone: 'warn' });
    return;
  }
  try {
    const result = await api('/api/niche-domain-patterns', {
      method: 'POST',
      body: JSON.stringify({ niche, pattern: raw }),
    });
    const patterns = rememberNicheDomainPatterns(niche, result.patterns);
    const city = domainSuggestCity(d);
    const prev = siteConfigNapFromLocal(d.id);
    const suggestions = mergeNicheDomainSuggestions(
      prev.domainPick?.suggestions || [],
      patterns,
      city,
    );
    writeDomainPickToNap({ domainPick: { suggestions } }, d.id);
    state.tab = 'site-config';
    state.siteConfigOpenStep = 'domain';
    state.siteConfigSoftCurrent = 'domain';
    renderDetail();
    showToast(
      result.added
        ? `Saved ${result.pattern} for this niche.`
        : `${result.pattern} is already saved for this niche.`,
    );
  } catch (error) {
    showToast(error.message || 'Could not save the pattern.', { tone: 'warn' });
  }
}

async function removeNicheDomainPatternFromCandidate(d, pattern) {
  const niche = domainSuggestNiche(d);
  if (!niche || !pattern) return;
  try {
    const result = await api('/api/niche-domain-patterns/remove', {
      method: 'POST',
      body: JSON.stringify({ niche, pattern }),
    });
    const patterns = rememberNicheDomainPatterns(niche, result.patterns);
    const city = domainSuggestCity(d);
    const host = expandNicheDomainPattern(pattern, city);
    const prev = siteConfigNapFromLocal(d.id);
    const filtered = (prev.domainPick?.suggestions || []).filter((row) => {
      const rowHost = String(row?.domain || '')
        .trim()
        .toLowerCase();
      return !host || rowHost !== host;
    });
    const suggestions = mergeNicheDomainSuggestions(filtered, patterns, city);
    writeDomainPickToNap({ domainPick: { suggestions } }, d.id);
    state.tab = 'site-config';
    state.siteConfigOpenStep = 'domain';
    state.siteConfigSoftCurrent = 'domain';
    renderDetail();
    showToast('Removed that pattern from this niche.');
  } catch (error) {
    showToast(error.message || 'Could not remove the pattern.', { tone: 'warn' });
  }
}

function formatPageNameList(names) {
  const list = (names || []).map((name) => String(name || '').trim()).filter(Boolean);
  if (list.length <= 1) return esc(list[0] || '');
  if (list.length === 2) return `${esc(list[0])} and ${esc(list[1])}`;
  return `${list.slice(0, -1).map((name) => esc(name)).join(', ')}, and ${esc(list[list.length - 1])}`;
}

function contentBuildNextHtml({ includeAccept = false, launched = false } = {}) {
  const api = effectiveClaudeUiMode() === 'api';
  const push = launched
    ? ` Then click <strong>3 · Launch</strong> and <strong>Push updates</strong>.`
    : '';
  if (api) {
    const accept = includeAccept
      ? ` When that finishes, click <strong>Accept content</strong>.${push}`
      : '';
    return `Click <strong>2 · Content</strong>, then <strong>Structure</strong>, then <strong>Write site with Claude</strong>.${accept}`;
  }
  const accept = includeAccept
    ? `, then work through to <strong>Accept content</strong>.${push}`
    : '';
  return `Click <strong>2 · Content</strong>, then <strong>Structure</strong>, then <strong>Site research</strong>${accept}`;
}

function siteConfigNextStep({
  accepted,
  detail,
  hasContent,
  launched,
  serviceAreaDone,
  phoneDone,
}) {
  const suburbs = (Array.isArray(accepted?.targetSuburbs) ? accepted.targetSuburbs : [])
    .map((name) => String(name || '').trim())
    .filter(Boolean);
  const serviceAreaSaved = Boolean(detail?.meta?.lastServiceAreaAt) || serviceAreaDone;
  const pending = Array.isArray(detail?.pendingLocationPages) ? detail.pendingLocationPages : [];
  const extras = Array.isArray(detail?.extraLocationPages) ? detail.extraLocationPages : [];
  if (!serviceAreaSaved) {
    return {
      kind: 'service-area',
      html: `Open <strong>Service area</strong>, mark the cities you want as pages, and accept.`,
    };
  }
  if (!hasContent) {
    if (!phoneDone) {
      return {
        kind: 'phone',
        html: `Click <strong>Provision phone number</strong>, or <strong>Skip</strong>.`,
      };
    }
    return {
      kind: 'write-site',
      html: contentBuildNextHtml(),
    };
  }
  const configAt = String(detail?.meta?.lastSiteConfigAt || '');
  const contentAt = String(detail?.meta?.lastContentAt || '');
  if (configAt && contentAt && configAt > contentAt) {
    return {
      kind: 'rewrite',
      html: contentBuildNextHtml({ includeAccept: true, launched }),
    };
  }
  if (!suburbs.length) {
    const primary = String(accepted?.primaryCity || accepted?.city || 'the primary city').trim();
    const remove = extras.length ? ` Prepare removes ${formatPageNameList(extras)}.` : '';
    const ship = launched
      ? `Click <strong>3 · Launch</strong>, then <strong>Prepare preview</strong>, then <strong>Push updates</strong>.${remove}`
      : `Click <strong>3 · Launch</strong>, then <strong>Prepare preview</strong>.${remove}`;
    return {
      kind: 'primary-only',
      html: `<strong>Only ${esc(primary)} is a location page.</strong> ${ship}`,
    };
  }
  if (pending.length) {
    return {
      kind: 'write-pages',
      html: `<strong>Write ${formatPageNameList(pending)}.</strong> ${contentBuildNextHtml({ includeAccept: true, launched })}`,
    };
  }
  if (launched) {
    return {
      kind: 'push',
      html: `Click <strong>3 · Launch</strong>, then <strong>Push updates</strong>.`,
    };
  }
  return {
    kind: 'prepare',
    html: `Click <strong>3 · Launch</strong>, then <strong>Prepare preview</strong>.`,
  };
}

function siteConfigAcceptedSummaryHtml(accepted, nextStepHtml) {
  if (!accepted) return '';
  const bits = [accepted.businessName, accepted.primaryCity || accepted.city, accepted.state]
    .map((x) => String(x || '').trim())
    .filter(Boolean);
  const domain = String(accepted.domain || '').trim();
  return statusLineHtml(
    `Accepted${bits.length ? `: <strong>${esc(bits.join(' · '))}</strong>` : ''}${
      domain ? ` · <code>${esc(domain)}</code>` : ''
    }. ${nextStepHtml}`,
  );
}

/** Strip markdown bold for Review Images Search line (stale manifests may still store **). */
function stripMdBoldDisplay(s) {
  return String(s || '')
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/^\*\*|\*\*$/g, '')
    .trim();
}

