function photoLibGroupStills() {
  const lib = photoLibCurrent();
  const groupId = lib.groupId;
  const groupName = lib.view?.group?.name || '';
  const photos = [];
  const seen = new Set();
  const add = (filename, previewUrl, label) => {
    if (!filename || !previewUrl || seen.has(`${groupId}\0${filename}`)) return;
    seen.add(`${groupId}\0${filename}`);
    photos.push({ groupId, groupName, filename, previewUrl, label });
  };
  for (const sec of lib.view?.sections || []) {
    for (const s of sec.slots || []) {
      add(s.filename, s.previewUrl, s.label || s.filename);
      for (const v of s.variants || []) {
        add(v.filename, v.previewUrl, s.label || v.filename);
      }
    }
  }
  return { photos, groupName, groupId };
}

async function openPhotoLibSeeMore(matchKey) {
  const { photos, groupName, groupId } = photoLibGroupStills();
  if (!groupId) return;
  if (!photos.length) {
    await showModal({
      title: 'See More',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: '<p>No photos in this group.</p>',
    });
    return;
  }
  await showSeeMorePicker({
    title: groupName ? `Group — ${groupName}` : 'Photo group',
    photos,
    onPick: async (fromGroupId, filename) => {
      beginSlotBusy(matchKey, document.querySelector(`#photo-group-body ${reviewCardAttrSel('data-match-key', matchKey)}`));
      await api(`/api/photo-groups/${encodeURIComponent(groupId)}/slots/use-file`, {
        method: 'POST',
        body: JSON.stringify({ matchKey, fromGroupId, filename }),
      });
      await loadPhotoGroupView();
      renderPhotoView();
      await settleSlotBusy(matchKey);
      showToast('Loaded photo from group.');
    },
  });
}

function photoLibGroupBaPairs() {
  const lib = photoLibCurrent();
  const groupId = lib.groupId;
  const groupName = lib.view?.group?.name || '';
  const pairs = [];
  const seen = new Set();
  const add = (beforeFilename, afterFilename, beforeUrl, afterUrl, label) => {
    if (!beforeFilename || !afterFilename || !beforeUrl || !afterUrl) return;
    const id = `${groupId}\0${beforeFilename}\0${afterFilename}`;
    if (seen.has(id)) return;
    seen.add(id);
    pairs.push({
      groupId,
      groupName,
      beforeFilename,
      afterFilename,
      beforeUrl,
      afterUrl,
      label,
    });
  };
  const labelFor = (p) => {
    const role = p.serviceName ? p.serviceName : `Home ${p.pairIndex || 1}`;
    return groupName ? `${role} · ${groupName}` : role;
  };
  for (const p of [...(lib.view?.beforeAfter?.home || []), ...(lib.view?.beforeAfter?.services || [])]) {
    add(p.before?.filename, p.after?.filename, p.beforeUrl, p.afterUrl, labelFor(p));
    for (const v of p.variants || []) {
      add(v.beforeFilename, v.afterFilename, v.beforeUrl, v.afterUrl, labelFor(p));
    }
  }
  return { pairs, groupName, groupId };
}

async function openPhotoLibBaSeeMore(matchKey) {
  const { pairs, groupName, groupId } = photoLibGroupBaPairs();
  if (!groupId) return;
  if (!pairs.length) {
    await showModal({
      title: 'See More',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: '<p>No before/after pairs in this group.</p>',
    });
    return;
  }
  await showSeeMorePicker({
    title: groupName ? `Group — ${groupName}` : 'Photo group',
    photos: pairs,
    ba: true,
    onPick: async ({ groupId: fromGroupId, beforeFilename, afterFilename }) => {
      beginSlotBusy(
        matchKey,
        document.querySelector(`#photo-group-body ${reviewCardAttrSel('data-match-key', matchKey)}`),
      );
      await api(`/api/photo-groups/${encodeURIComponent(groupId)}/before-after/use-pair`, {
        method: 'POST',
        body: JSON.stringify({ matchKey, fromGroupId, beforeFilename, afterFilename }),
      });
      await loadPhotoGroupView();
      renderPhotoView();
      await settleSlotBusy(matchKey);
      showToast('Loaded before/after pair from group.');
    },
  });
}

async function showSeeMorePicker({ title, photos, ba = false, onPick }) {
  const cards = photos
    .map((p) => {
      if (ba) {
        return `<button type="button" class="see-more-card ba" data-group-id="${esc(p.groupId)}" data-before-filename="${esc(p.beforeFilename)}" data-after-filename="${esc(p.afterFilename)}">
        <div class="slot-variant-pair">
          <img class="slot-zoom-tray" src="${esc(p.beforeUrl)}" alt="" data-zoom-src="${esc(p.beforeUrl)}" />
          <img class="slot-zoom-tray" src="${esc(p.afterUrl)}" alt="" data-zoom-src="${esc(p.afterUrl)}" />
        </div>
        <span class="see-more-card-meta">${esc(p.label || '')}</span>
      </button>`;
      }
      return `<button type="button" class="see-more-card" data-group-id="${esc(p.groupId)}" data-filename="${esc(p.filename)}">
        <img class="slot-zoom-tray" src="${esc(p.previewUrl)}" alt="${esc(p.label || '')}" data-zoom-src="${esc(p.previewUrl)}" />
        <span class="see-more-card-meta">${esc(p.label || p.filename)}</span>
      </button>`;
    })
    .join('');
  const hint = ba
    ? 'Click a pair to use it in this slot. Previous live pair goes to the tray.'
    : 'Click a photo to use it in this slot. Previous live photo goes to the tray.';
  let picked = null;
  await showModal({
    title,
    confirmLabel: 'Close',
    hideCancel: true,
    bodyHtml: `<p class="muted">${hint}</p>
      <input id="see-more-search" class="modal-type-confirm-input see-more-search" type="search" placeholder="Search titles…" autocomplete="off" spellcheck="false" />
      <p class="muted small see-more-empty hidden">No matching titles</p>
      <div class="see-more-grid">${cards}</div>`,
    afterOpen: (bodyEl) => {
      const searchEl = bodyEl.querySelector('#see-more-search');
      const emptyEl = bodyEl.querySelector('.see-more-empty');
      const cardEls = [...bodyEl.querySelectorAll('.see-more-card')];
      const applyFilter = () => {
        const q = String(searchEl?.value || '')
          .trim()
          .toLowerCase();
        let visible = 0;
        for (const btn of cardEls) {
          const label = (btn.querySelector('.see-more-card-meta')?.textContent || '').toLowerCase();
          const match = !q || label.includes(q);
          btn.classList.toggle('hidden', !match);
          if (match) visible += 1;
        }
        emptyEl?.classList.toggle('hidden', visible > 0);
      };
      searchEl?.addEventListener('input', applyFilter);
      searchEl?.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') e.preventDefault();
      });
      setTimeout(() => searchEl?.focus(), 0);
      cardEls.forEach((btn) => {
        btn.addEventListener('click', () => {
          if (picked) return;
          const groupId = btn.getAttribute('data-group-id');
          if (ba) {
            const beforeFilename = btn.getAttribute('data-before-filename');
            const afterFilename = btn.getAttribute('data-after-filename');
            if (!groupId || !beforeFilename || !afterFilename) return;
            picked = { groupId, beforeFilename, afterFilename };
          } else {
            const filename = btn.getAttribute('data-filename');
            if (!groupId || !filename) return;
            picked = { groupId, filename };
          }
          for (const card of cardEls) card.disabled = true;
          document.getElementById('modal-confirm')?.click();
        });
      });
    },
  });
  if (!picked) return;
  try {
    if (ba) await onPick(picked);
    else await onPick(picked.groupId, picked.filename);
  } catch (error) {
    await settleSlotBusy();
    await showModal({
      title: ba ? 'Use pair failed' : 'Use photo failed',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>${esc(error.message)}</p>`,
    });
  }
}

function openaiGenerateBtnHtml({ pair = false, extra = '', bulk = false, flux } = {}) {
  const configured = fluxIsOpenaiConfigured(flux);
  const label = pair ? 'OpenAI pair' : 'OpenAI';
  const tip = configured
    ? bulk
      ? 'Generate the selected photos. About $0.04 each, or $0.09 for a pair. The previous image is kept.'
      : pair
      ? 'Generate this before-and-after pair, about $0.09. The previous pair is kept.'
      : 'Generate this photo, about $0.04. The previous photo is kept.'
    : 'Photo generation is not set up yet.';
  const disabled = configured ? '' : ' disabled';
  const bulkClass = bulk ? ' slot-generate-selected-openai' : '';
  return `<button type="button" class="btn btn-sm btn-ai slot-generate-openai${pair ? ' ba' : ''}${bulkClass}" data-tip="${esc(tip)}"${disabled}${extra}>${slotAiMark('openai')}<span>${esc(label)}</span></button>`;
}

function slotSourceActionsHtml({
  kind = 'photo',
  viewpointKey,
  generateExtra = '',
  copyHtml = '',
  filesHtml = '',
} = {}) {
  const generate =
    kind === 'ba'
      ? openaiGenerateBtnHtml({ pair: true, extra: generateExtra })
      : openaiGenerateBtnHtml({ extra: generateExtra });
  const files = String(filesHtml || '').trim()
    ? `<div class="slot-files-row">${filesHtml}</div>`
    : '';
  return `<div class="slot-source-actions">
    <div class="slot-ai-group">
      ${baViewpointSegmentHtml(viewpointKey)}
      ${baOccupancySegmentHtml(viewpointKey)}
      <div class="slot-ai-group-btns">${generate}${copyHtml}${chatgptOpenBtnHtml()}</div>
    </div>
    ${files}
  </div>`;
}

function selectedGenerateCostLine(nSlots, nPairs) {
  const gen = 0.04;
  const pair = 0.09;
  const total = nSlots * gen + nPairs * pair;
  const bits = [];
  if (nSlots) bits.push(`${nSlots} photo${nSlots === 1 ? '' : 's'} ≈ $${(nSlots * gen).toFixed(2)}`);
  if (nPairs) bits.push(`${nPairs} pair${nPairs === 1 ? '' : 's'} ≈ $${(nPairs * pair).toFixed(2)}`);
  return bits.length ? `${bits.join(' · ')} (about $${total.toFixed(2)})` : '';
}

function countSlotsBySource(slots) {
  const out = { stock: 0, openai: 0, photoGroup: 0 };
  for (const s of slots || []) {
    const k = imagesSlotSourceKind(s);
    if (k === 'stock' || k === 'openai') out[k] += 1;
    else if (k === 'photo-group') out.photoGroup += 1;
  }
  return out;
}

function reviewViewpointKeyFromCheckId(checkId) {
  const id = String(checkId || '');
  return id.startsWith('ba:') ? id.slice(3) : id;
}

function selectedReviewCheckIds() {
  const checks = state.imageSlotChecks || {};
  return Object.keys(checks).filter((id) => checks[id]);
}

function reviewSelectionAgrees(kind) {
  const ids = selectedReviewCheckIds();
  if (!ids.length) return '';
  const values = ids.map((id) => {
    const key = reviewViewpointKeyFromCheckId(id);
    return kind === 'occupancy' ? getBaOccupancy(key) : getBaViewpoint(key);
  });
  return values.every((value) => value === values[0]) ? values[0] : '';
}

function visibleReviewCheckCount() {
  const grid = document.getElementById('ca-image-slots-grid');
  if (!grid) return 0;
  return grid.querySelectorAll('.image-slot-card .slot-check-input').length;
}

function reviewCardForCheckId(root, checkId) {
  const id = String(checkId || '');
  if (!root) return null;
  if (id.startsWith('ba:')) {
    return root.querySelector(
      `.photo-ba-card[data-match-key="${CSS.escape(reviewViewpointKeyFromCheckId(id))}"]`,
    );
  }
  return root.querySelector(`.image-slot-card[data-slot-key="${CSS.escape(id)}"]`);
}

function applyReviewSelectionScene(root, { viewpoint, occupancy } = {}) {
  const ids = selectedReviewCheckIds();
  if (!ids.length) return;
  for (const id of ids) {
    const key = reviewViewpointKeyFromCheckId(id);
    const card = reviewCardForCheckId(root, id);
    if (card) stashSlotPromptDraft(card);
    if (viewpoint) {
      const next = setBaViewpoint(key, viewpoint);
      card?.querySelectorAll('[data-ba-viewpoint]').forEach((button) => {
        button.classList.toggle('active', button.dataset.baViewpoint === next);
      });
    }
    if (occupancy) {
      const next = setBaOccupancy(key, occupancy);
      card?.querySelectorAll('[data-ba-occupancy]').forEach((button) => {
        button.classList.toggle('active', button.dataset.baOccupancy === next);
      });
    }
    if (card) fillBaPromptsPanel(card);
  }
  renderReviewFluxToolbar();
}

async function applyReviewSelectionGrade(candidateId, grade) {
  const selected = selectedReviewCheckIds();
  const slotKeys = selected.filter((id) => !String(id).startsWith('ba:'));
  const baKeys = selected.filter((id) => String(id).startsWith('ba:')).map((id) => String(id).slice(3));
  if (!slotKeys.length && !baKeys.length) return;
  let data;
  try {
    data = await withReviewImagesWork({ label: 'Updating match…' }, () =>
      api(`/api/candidates/${encodeURIComponent(candidateId)}/images/match-grades`, {
        method: 'POST',
        body: JSON.stringify({ matchGrade: grade, slotKeys, baKeys }),
      }),
    );
  } catch (error) {
    await showModal({
      title: 'Could not set match grade',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>${esc(error.message)}</p>`,
    });
    return;
  }
  const applied = Number(data?.applied) || 0;
  const skipped = Array.isArray(data?.skipped) ? data.skipped : [];
  if (!applied) {
    const reasons = [...new Set(skipped.map((row) => row?.reason).filter(Boolean))];
    await showModal({
      title: 'Could not set match grade',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>${esc(reasons.join(' ') || 'No selected photo can be graded.')}</p>`,
    });
    return;
  }
  if (data.baStatus) state.reviewBa = data.baStatus;
  for (const slot of data.slots || []) upsertReviewSlotState(slot);
  paintReviewImageSlotsFromState(candidateId, { renderToolbar: true });
  if (skipped.length) {
    showToast(`${skipped.length} left unchanged (empty or upload).`, { tone: 'warn' });
  }
}

function reviewSelectionGrade() {
  const grades = selectedReviewCheckIds()
    .map(reviewCheckMatchGrade)
    .filter((grade) => grade === 'poor' || grade === 'ok' || grade === 'good');
  if (!grades.length) return '';
  return grades.every((grade) => grade === grades[0]) ? grades[0] : '';
}

function reviewCheckMatchGrade(checkId) {
  const id = String(checkId || '');
  if (id.startsWith('ba:')) {
    const raw = id.slice(3);
    const pair = listReviewBaPairs(state.reviewBa).find((row) => {
      const key = row.matchKey || (row.slug ? `svc:${row.slug}` : `home:${row.pairIndex || 1}`);
      return key === raw;
    });
    return imagesSlotGrade(pair ? baPairAsReviewSlot(pair) : null);
  }
  const slot = (state.reviewImageSlots || []).find((row) => row.key === id);
  return imagesSlotGrade(slot);
}

function reviewBulkGradeHtml(n) {
  const disabled = n < 1 ? ' disabled' : '';
  const current = reviewSelectionGrade();
  const seg = (grade, label) => {
    const active = current === grade;
    return `<button type="button" class="ads-mode-seg${active ? ' active' : ''}" data-review-bulk-grade="${esc(
      grade,
    )}"${disabled}>${imagesMatchDotHtml(grade, '', { tipped: false })}${esc(label)}</button>`;
  };
  return `<span class="ads-mode-segment review-bulk-scene review-bulk-grade" role="group" aria-label="Set selected photos to Poor, Ok, or Good" ${tipAttr(
    'Poor, Ok, or Good for every selected photo and before/after',
  )}>
    ${seg('poor', 'Poor')}
    ${seg('ok', 'Ok')}
    ${seg('good', 'Good')}
  </span>`;
}

function reviewBulkSceneHtml(n) {
  const disabled = n < 1 ? ' disabled' : '';
  const viewpoint = reviewSelectionAgrees('viewpoint');
  const occupancy = reviewSelectionAgrees('occupancy');
  const seg = (attr, value, label, active) =>
    `<button type="button" class="ads-mode-seg${active ? ' active' : ''}" ${attr}="${esc(value)}"${disabled}>${esc(label)}</button>`;
  return `<span class="ads-mode-segment review-bulk-scene" role="group" aria-label="Set selected photos to inside or outside" ${tipAttr(
    'Inside or Outside for every selected photo and before/after',
  )}>
    ${seg('data-review-bulk-viewpoint', 'inside', 'Inside', viewpoint === 'inside')}
    ${seg('data-review-bulk-viewpoint', 'outside', 'Outside', viewpoint === 'outside')}
  </span>
  <span class="ads-mode-segment review-bulk-scene review-bulk-occupancy" role="group" aria-label="Set selected photos to problem, workers, finished, or customers" ${tipAttr(
    'Problem, Workers, Finished, or Customers for every selected photo and before/after',
  )}>
    ${seg('data-review-bulk-occupancy', 'none', 'Problem', occupancy === 'none')}
    ${seg('data-review-bulk-occupancy', 'workers', 'Workers', occupancy === 'workers')}
    ${seg('data-review-bulk-occupancy', 'finished', 'Finished', occupancy === 'finished')}
    ${seg('data-review-bulk-occupancy', 'customers', 'Customers', occupancy === 'customers')}
  </span>
  ${reviewBulkGradeHtml(n)}`;
}

function fluxToolbarHtml({
  nSlots,
  nPairs,
  flux,
  id,
  repull = false,
  sourceCounts = null,
  titleSearch = false,
  bulkScene = false,
}) {
  const n = nSlots + nPairs;
  const openaiExtra = n < 1 ? ' disabled' : '';
  const repullBtn = repull
    ? `<button type="button" class="btn btn-sm review-selected-repull" data-tip="Re-pull stock for selected photo slots (not Before &amp; after)"${
        nSlots < 1 ? ' disabled' : ''
      }>Re-pull</button>`
    : '';
  const selectBtn = bulkScene
    ? `<button type="button" class="btn btn-sm flux-select-all" data-tip="Select every photo and before/after currently shown"${
        visibleReviewCheckCount() < 1 ? ' disabled' : ''
      }>Select all</button>`
    : '';
  const unselectBtn = `<button type="button" class="btn btn-sm flux-unselect-all" data-tip="Clear every selected photo and before/after"${
    n < 1 ? ' disabled' : ''
  }>Unselect all</button>`;
  const bulkSceneHtml = bulkScene ? reviewBulkSceneHtml(n) : '';
  const titleSearchHtml = titleSearch
    ? `<input id="review-title-search" class="modal-type-confirm-input flux-toolbar-title-search" type="search" placeholder="Search titles…" autocomplete="off" spellcheck="false" value="${esc(state.imageTitleFilter || '')}" />`
    : '';
  if (bulkScene) {
    return `<div class="flux-toolbar review-images-row review-images-work" id="${esc(id)}">
    ${reviewClusterHtml(
      'Select',
      `<span class="review-selected-count">Selected images ${esc(String(n))}</span>
      ${selectBtn}
      ${unselectBtn}
      ${bulkSceneHtml}`,
    )}
    ${reviewClusterHtml(
      'Generate',
      `${repullBtn}
      ${openaiGenerateBtnHtml({ bulk: true, extra: openaiExtra, flux })}`,
    )}
    ${reviewClusterHtml('Search', titleSearchHtml, 'review-images-cluster-search')}
  </div>`;
  }
  const sourceBtns = repull ? reviewSourceFiltersHtml(sourceCounts) : '';
  return `<div class="flux-toolbar" id="${esc(id)}">
    <span class="review-selected-count">Selected images ${esc(String(n))}</span>
    ${selectBtn}
    ${unselectBtn}
    ${bulkSceneHtml}
    ${sourceBtns}
    <span class="flux-toolbar-sep" role="separator" aria-hidden="true"></span>
    <span class="flux-toolbar-generate-label">Generate</span>
    ${repullBtn}
    ${openaiGenerateBtnHtml({ bulk: true, extra: openaiExtra, flux })}
    ${titleSearchHtml}
  </div>`;
}

