      state.claudeBusy = false;
      state.activeAct = null;
      state.jobStatusLine = '';
      syncClaudeModeToggle();
      renderDetail();
      await showModal({
        title: 'Fill site-config failed',
        confirmLabel: 'OK',
        hideCancel: true,
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
