function formatSiteMetricNum(n, digits = 0) {
  if (n == null || n === '') return '—';
  const num = Number(n);
  if (!Number.isFinite(num)) return '—';
  return digits > 0 ? num.toFixed(digits) : String(Math.round(num));
}

/** Format Y axis tick for Sites charts. */
function formatSitesChartAxis(v, yFormat) {
  const n = Number(v);
  if (!Number.isFinite(n)) return '';
  if (yFormat === 'percent') return `${Math.round(n)}%`;
  return String(Math.round(n));
}

/** Round step of 1, 2, 5, or 10 × 10^n. Labels are integers, so the step is at least 1. */
function chartNiceStep(range, targetCount = 4) {
  const rough = range / Math.max(targetCount, 1);
  if (!(rough > 0)) return 1;
  const pow = 10 ** Math.floor(Math.log10(rough));
  const err = rough / pow;
  const nice = err <= 1.5 ? 1 : err <= 3 ? 2 : err <= 7 ? 5 : 10;
  return Math.max(1, nice * pow);
}

function chartYTicks(yMin, yMax, yFormat) {
  const range = yMax - yMin;
  if (!(range > 0)) return [yMin];
  const step = chartNiceStep(range, 4);
  const start = Math.ceil(yMin / step - 1e-9);
  const end = Math.floor(yMax / step + 1e-9);
  const ticks = [];
  const seen = new Set();
  for (let i = start; i <= end && ticks.length < 8; i += 1) {
    const value = i * step;
    const label = formatSitesChartAxis(value, yFormat);
    if (!label || seen.has(label)) continue;
    seen.add(label);
    ticks.push(value);
  }
  return ticks.length ? ticks : [yMin, yMax];
}

function chartYAxisMarkup({ yTicks, yFormat, yAt, w, h, pad }) {
  const baseline = h - pad.b;
  return yTicks
    .map((value) => {
      const y = yAt(value);
      const onBase = Math.abs(y - baseline) < 1;
      const line = onBase
        ? ''
        : `<line x1="${pad.l}" y1="${y.toFixed(1)}" x2="${w - pad.r}" y2="${y.toFixed(1)}" stroke="currentColor" stroke-opacity="0.18" stroke-dasharray="3 3" />`;
      const labelY = Math.min(h - 4, Math.max(9, y));
      return `${line}<text x="${(pad.l - 4).toFixed(1)}" y="${labelY.toFixed(1)}" fill="currentColor" font-size="10" opacity="0.55" text-anchor="end" dominant-baseline="middle">${esc(formatSitesChartAxis(value, yFormat))}</text>`;
    })
    .join('');
}

/**
 * Simple multi-series SVG line chart.
 * series: [{ label, color, points: [{ y }] }] — null/NaN y dropped.
 * opts: { yLabel, width, height, yFormat: 'number'|'percent', invertY, minPoints, xStart, xEnd, xTicks }
 * xTicks: [{ index, text }] drawn along the x-axis. xStart/xEnd are the two-label fallback.
 */
function renderSvgLineChart(
  container,
  seriesList,
  { yLabel = '', width = 320, height = 110, yFormat = 'number', invertY = false, minPoints = 2, xStart = '', xEnd = '', xTicks = [] } = {},
) {
  if (!container) return;

  const cleaned = (seriesList || [])
    .map((s) => ({
      label: s.label || '',
      color: s.color || '#2a9d8f',
      points: (s.points || [])
        .map((p) => {
          const y = p == null || typeof p !== 'object' ? Number(p) : Number(p.y);
          return Number.isFinite(y) ? { y } : null;
        })
        .filter(Boolean),
    }))
    .filter((s) => s.points.length > 0);

  const series =
    cleaned.filter((s) => s.points.length >= minPoints).length > 0
      ? cleaned.filter((s) => s.points.length >= minPoints)
      : minPoints <= 1
        ? cleaned
        : [];

  if (!series.length) {
    container.innerHTML = `<div class="sites-chart-empty muted small">No data yet</div>`;
    return;
  }

  const w = Math.max(40, Math.round(width) || 320);
  const h = Math.max(40, Math.round(height) || 110);
  const axisTicks = (xTicks || []).filter((tick) => tick && tick.text);
  const pad = { t: 14, r: 10, b: axisTicks.length || xStart || xEnd ? 26 : 12, l: 34 };
  const allY = series.flatMap((s) => s.points.map((p) => p.y));
  let yMin = Math.min(...allY);
  let yMax = Math.max(...allY);
  if (yMin === yMax) {
    if (yFormat === 'percent') {
      yMin = Math.max(0, yMin - 5);
      yMax = Math.min(100, yMax + 5);
      if (yMin === yMax) {
        yMin = 0;
        yMax = 100;
      }
    } else if (invertY) {
      yMin = Math.max(1, yMin - 1);
      yMax = yMax + 1;
    } else {
      yMin = Math.max(0, yMin - 1);
      yMax = yMax + 1;
    }
  } else {
    const padAmt = (yMax - yMin) * 0.08 || 1;
    yMin -= padAmt;
    yMax += padAmt;
    if (yFormat === 'percent') {
      yMin = Math.max(0, yMin);
      yMax = Math.min(100, yMax);
    } else if (!invertY && yMin > 0 && yMin < (yMax - yMin) * 0.2) {
      yMin = 0;
    }
  }
  if (!invertY && yFormat !== 'percent' && Math.min(...allY) >= 0) yMin = Math.max(0, yMin);
  if (yMax <= yMin) yMax = yMin + 1;

  const yTicks = chartYTicks(yMin, yMax, yFormat);
  const widestTick = Math.max(2, ...yTicks.map((value) => formatSitesChartAxis(value, yFormat).length));
  pad.l = Math.max(34, Math.ceil(8 + widestTick * 6.2));

  const maxPts = Math.max(...series.map((s) => s.points.length));
  const xAt = (i, len) =>
    pad.l + (i / Math.max((len || maxPts) - 1, 1)) * (w - pad.l - pad.r);
  const yAt = (v) => {
    const t = (v - yMin) / (yMax - yMin);
    const norm = invertY ? t : 1 - t;
    return pad.t + norm * (h - pad.t - pad.b);
  };

  const paths = series
    .map((s) => {
      const d = s.points
        .map((p, i) => {
          const cmd = i === 0 ? 'M' : 'L';
          return `${cmd}${xAt(i, s.points.length).toFixed(1)},${yAt(p.y).toFixed(1)}`;
        })
        .join(' ');
      return `<path d="${d}" fill="none" stroke="${esc(s.color)}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />`;
    })
    .join('');

  const dots =
    maxPts <= 24
      ? series
          .map((s) =>
            s.points
              .map(
                (p, i) =>
                  `<circle cx="${xAt(i, s.points.length).toFixed(1)}" cy="${yAt(p.y).toFixed(
                    1,
                  )}" r="2.25" fill="${esc(s.color)}" />`,
              )
              .join(''),
          )
          .join('')
      : '';

  const legend = series
    .map(
      (s) =>
        `<li class="sites-chart-legend-item">
          <span class="sites-chart-legend-dot" style="background:${esc(s.color)}"></span>
          <span class="sites-chart-legend-label">${esc(s.label)}</span>
        </li>`,
    )
    .join('');

  container.innerHTML = `<div class="sites-chart-plot">
    <svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${esc(
      yLabel || 'chart',
    )}">
      <line x1="${pad.l}" y1="${pad.t}" x2="${pad.l}" y2="${h - pad.b}" stroke="currentColor" stroke-opacity="0.12" />
      <line x1="${pad.l}" y1="${h - pad.b}" x2="${w - pad.r}" y2="${h - pad.b}" stroke="currentColor" stroke-opacity="0.12" />
      ${chartYAxisMarkup({ yTicks, yFormat, yAt, w, h, pad })}
      ${paths}${dots}
      ${chartXAxisLabels({ axisTicks, xStart, xEnd, maxPts, xAt, w, h, pad })}
    </svg>
  </div>
  <ul class="sites-chart-legend">${legend}</ul>`;
}

function renderSitesPortfolioCharts() {
  const wrap = document.getElementById('sites-portfolio-charts');
  if (!wrap) return;
  const traffic = state.sitesPortfolio?.traffic || [];
  const ranks = state.sitesPortfolio?.ranks || [];
  const hasAny = traffic.length || ranks.length || (state.sites || []).some((s) => s.clicks28d != null);
  wrap.classList.toggle('hidden', !hasAny && !(state.gscStatus?.connected));

  renderSvgLineChart(
    document.getElementById('sites-chart-traffic'),
    [
      {
        label: 'Clicks',
        color: '#2a9d8f',
        points: traffic.map((r) => ({ y: r.clicks })),
      },
      {
        label: 'Impressions',
        color: '#e9c46a',
        points: traffic.map((r) => ({ y: r.impressions })),
      },
    ],
    { yLabel: 'Portfolio traffic', yFormat: 'number', minPoints: 2 },
  );

  renderSvgLineChart(
    document.getElementById('sites-chart-ranks'),
    [
      {
        label: '% on page 1',
        color: '#457b9d',
        points: ranks
          .filter((r) => r.page1Share != null && Number.isFinite(Number(r.page1Share)))
          .map((r) => ({ y: Math.round(Number(r.page1Share) * 100) })),
      },
    ],
    { yLabel: 'Primary on page 1', yFormat: 'percent', minPoints: 2 },
  );
}

function isGscAuthRevokedError(error) {
  return (
    error?.code === 'GSC_AUTH_REVOKED' ||
    /expired or revoked/i.test(String(error?.message || ''))
  );
}

async function showGscReconnectModal(error) {
  await showModal({
    title: 'Reconnect GSC',
    confirmLabel: 'OK',
    hideCancel: true,
    bodyHtml: `<p>${esc(
      error?.message || 'GSC login expired — reconnect Google Search Console.',
    )}</p>
      <p class="muted small">Click <strong>Connect GSC</strong> and sign in with the Google account that owns the Domain properties.</p>`,
  });
}

function gscSignedIn() {
  const g = state.gscStatus || {};
  return Boolean(g.configured && g.connected);
}

const GSC_SYNC_TIP =
  'Load the last 28 days of clicks and queries.';
const GSC_INDEX_TIP =
  'Check which sitemap pages Google has indexed.';
const GSC_CONNECT_FIRST_TIP = 'Connect Search Console first.';

function renderGscConnectionPill() {
  const el = document.getElementById('sites-gsc-connection');
  if (!el) return;
  const label = el.querySelector('.gsc-connection-label');
  const g = state.gscStatus || {};
  el.classList.remove('is-connected', 'is-disconnected', 'is-unconfigured');
  let text = 'Not connected';
  let tip = 'Search Console is not connected.';
  let cls = 'is-disconnected';
  if (state.gscStatus && !g.configured) {
    text = 'GSC not set up';
    tip = 'Search Console is not set up yet.';
    cls = 'is-unconfigured';
  } else if (g.connected) {
    text = 'Connected';
    tip = g.email ? `Connected as ${g.email}` : 'Search Console is connected';
    cls = 'is-connected';
  }
  el.classList.add(cls);
  if (label) label.textContent = text;
  el.setAttribute('data-tip', tip);
  el.setAttribute('aria-label', tip);
}

function applyGscMetricsButtonState() {
  const busy = Boolean(state.sitesMetricsBusy);
  const ready = gscSignedIn();
  const g = state.gscStatus || {};
  const blockedTip = state.gscStatus && !g.configured ? 'Search Console is not set up yet.' : GSC_CONNECT_FIRST_TIP;
  const pairs = [
    ['sites-gsc-sync-btn', ready ? GSC_SYNC_TIP : blockedTip],
    ['sites-index-check-btn', ready ? GSC_INDEX_TIP : blockedTip],
    ['sites-gsc-sync-one', ready ? GSC_SYNC_TIP : blockedTip],
    ['sites-index-check-one', ready ? GSC_INDEX_TIP : blockedTip],
  ];
  for (const [id, tip] of pairs) {
    const el = document.getElementById(id);
    if (!el) continue;
    el.disabled = busy || !ready;
    el.setAttribute('data-tip', tip);
  }
}

function updateSitesGscConnectButton() {
  const connectBtn = document.getElementById('sites-gsc-connect-btn');
  const g = state.gscStatus || {};
  if (connectBtn) {
    connectBtn.textContent = g.connected ? 'Reconnect GSC' : 'Connect GSC';
    connectBtn.classList.remove('hidden');
    connectBtn.hidden = false;
    connectBtn.setAttribute(
      'data-tip',
      g.connected
        ? 'Sign in again if the login expired.'
        : 'Connect Google Search Console.',
    );
    if (!g.configured) connectBtn.disabled = true;
    else connectBtn.disabled = Boolean(state.sitesMetricsBusy);
  }
  renderGscConnectionPill();
  applyGscMetricsButtonState();
}

function renderSitesGscStatus() {
  const el = document.getElementById('sites-gsc-status');
  const g = state.gscStatus || {};
  if (el) {
    if (state.gscStatus && !g.configured) {
      el.textContent =
        'GSC: set GOOGLE_GSC_CLIENT_ID + GOOGLE_GSC_CLIENT_SECRET in .env (Desktop OAuth). Redirect: ' +
        (g.redirectUri || 'http://127.0.0.1:8787/api/gsc/oauth/callback');
    } else if (g.connected) {
      const when = g.updatedAt ? String(g.updatedAt).slice(0, 16).replace('T', ' ') : '';
      el.textContent = `Signed in${g.email ? ` as ${g.email}` : ''}${when ? ` · ${when}` : ''}.`;
    } else {
      el.textContent = `Not connected. Click Connect GSC to sign in. Redirect URI must be allowed: ${
        g.redirectUri || ''
      }`;
    }
  }
  updateSitesGscConnectButton();
}

/** Sites eligible for GSC/rank bulk jobs (matches server metricsEligibleSites). */
function sitesMetricsEligible() {
  return (state.sites || []).filter((s) => {
    if (!s.lastLaunchAt && !s.lastShipAt) return false;
    if (!['live', 'listed', 'rented', 'building'].includes(String(s.status || ''))) return false;
    return Boolean(s.domain || s.liveUrl);
  });
}

/** Eligible sites whose Launched-table checkboxes are checked right now. */
function selectedSitesForMetrics() {
  const ids = [];
  document.querySelectorAll('#sites-table tbody input.sites-check:checked').forEach((input) => {
    const id = input.dataset.id;
    if (id) ids.push(id);
  });
  if (!ids.length) return [];
  const byId = new Map(sitesMetricsEligible().map((site) => [site.id, site]));
  const seen = new Set();
  const sites = [];
  for (const id of ids) {
    if (seen.has(id)) continue;
    seen.add(id);
    const site = byId.get(id);
    if (site) sites.push(site);
  }
  return sites;
}

function sitesMetricsConfirmTitle(action, sites) {
  const n = sites.length;
  const noun = `site${n === 1 ? '' : 's'}`;
  const names = sites.map((site) => siteMetricsDomainLabel(site));
  const named = names.length <= 3 ? names.join(', ') : `${names.slice(0, 3).join(', ')} and ${n - 3} more`;
  return `${action} for ${n} selected ${noun}: ${named}?`;
}

function sitesMetricsNameList(sites) {
  const items = sites.map((site) => `<li>${esc(siteMetricsDomainLabel(site))}</li>`).join('');
  return `<ul class="muted small" style="max-height:160px;overflow:auto;margin:0.6rem 0 0;padding-left:1.2rem">${items}</ul>`;
}

function siteMetricsDomainLabel(s) {
  return s?.domain || s?.liveUrl || s?.id || 'site';
}

function setSitesMetricsProgress({ visible, label, detail, pct } = {}) {
  const wrap = document.getElementById('sites-metrics-progress');
  const bar = document.getElementById('sites-metrics-progress-bar');
  const labelEl = document.getElementById('sites-metrics-progress-label');
  const detailEl = document.getElementById('sites-metrics-progress-detail');
  if (wrap) {
    wrap.classList.toggle('hidden', !visible);
    if (labelEl && label != null) labelEl.textContent = label;
    if (detailEl && detail != null) detailEl.textContent = detail;
    if (pct == null || !Number.isFinite(Number(pct))) {
      setDeterminateProgress(bar, {});
    } else {
      setDeterminateProgress(bar, { done: Number(pct), total: 100 });
    }
  }
}

function setSitesMetricsButtonsDisabled(busy) {
  state.sitesMetricsBusy = Boolean(busy);
  const ids = [
    'sites-gsc-sync-btn',
    'sites-index-check-btn',
    'sites-rank-sync-btn',
    'sites-add-btn',
    'sites-refresh-btn',
    'sites-kw-add',
    'sites-kw-save',
    'sites-rank-check-one',
    'sites-index-check-one',
    'sites-gsc-sync-one',
  ];
  for (const id of ids) {
    const el = document.getElementById(id);
    if (el) el.disabled = Boolean(busy);
  }
  updateSitesGscConnectButton();
}

function clearSitesGscConnectWait() {
  const wait = state._sitesGscConnectWait;
  if (!wait) return;
  if (wait.pollTimer) clearInterval(wait.pollTimer);
  if (wait.timeoutTimer) clearTimeout(wait.timeoutTimer);
  if (wait.onFocus) window.removeEventListener('focus', wait.onFocus);
  state._sitesGscConnectWait = null;
}

async function finishSitesGscConnectWait({ connected = false, timedOut = false } = {}) {
  clearSitesGscConnectWait();
  try {
    await loadSites();
  } catch {
    /* ignore */
  }
  setSitesMetricsProgress({ visible: false, label: '', detail: '', pct: null });
  setSitesMetricsButtonsDisabled(false);
  if (timedOut && !connected) {
    await showModal({
      title: 'GSC connect still waiting',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>No connection confirmed after 2 minutes. Finish Google sign-in in the popup, or click <strong>Connect GSC</strong> again.</p>`,
    });
  } else if (connected) {
    setSitesMetricsProgress({
      visible: true,
      label: 'GSC connected',
      detail: 'Ready to Sync GSC',
      pct: 100,
    });
    setTimeout(() => {
      if (!state.sitesMetricsBusy) {
        setSitesMetricsProgress({ visible: false, label: '', detail: '', pct: null });
      }
    }, 1500);
  }
}

function startSitesGscConnectWait() {
  clearSitesGscConnectWait();
  setSitesMetricsButtonsDisabled(true);
  setSitesMetricsProgress({
    visible: true,
    label: 'Waiting for Google sign-in…',
    detail: 'Complete consent in the popup window',
    pct: null,
  });

  const poll = async () => {
    try {
      const status = await api('/api/gsc/status');
      state.gscStatus = status;
      if (status?.connected) {
        await finishSitesGscConnectWait({ connected: true });
      }
    } catch {
      /* keep waiting */
    }
  };

  const onFocus = () => {
    poll();
  };

  const pollTimer = setInterval(poll, 2000);
  const timeoutTimer = setTimeout(() => {
    if (state._sitesGscConnectWait) {
      finishSitesGscConnectWait({ timedOut: true });
    }
  }, 120000);

  state._sitesGscConnectWait = { pollTimer, timeoutTimer, onFocus };
  window.addEventListener('focus', onFocus);
}

/**
 * Run an async Sites metrics job with progress bar + button lock.
 * @param {{ label: string, detail?: string }} start
 * @param {(ctx: { setProgress: Function }) => Promise<void>} fn
 */
async function withSitesMetricsBusy(start, fn) {
  if (state.sitesMetricsBusy) return;
  state.sitesMetricsStop = false;
  setSitesMetricsButtonsDisabled(true);
  setSitesMetricsProgress({
    visible: true,
    label: start.label || 'Working…',
    detail: start.detail || 'Starting…',
    pct: start.pct != null ? start.pct : null,
  });
  try {
    await fn({
      setProgress: (opts) => setSitesMetricsProgress({ visible: true, ...opts }),
    });
  } finally {
    setSitesMetricsProgress({ visible: false, label: '', detail: '', pct: null });
    setSitesMetricsButtonsDisabled(false);
  }
}

async function syncSitesGscSequential(siteList) {
  const sites = Array.isArray(siteList) ? siteList : [];
  if (!sites.length) {
    await showModal({
      title: 'GSC sync',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>No eligible sites (need status live/listed/rented/building and a domain).</p>`,
    });
    return;
  }
  let synced = 0;
  let failed = 0;
  const errors = [];
  let authRevoked = null;
  await withSitesMetricsBusy(
    { label: 'Syncing GSC…', detail: `0/${sites.length}`, pct: 0 },
    async ({ setProgress }) => {
      for (let i = 0; i < sites.length; i += 1) {
        if (state.sitesMetricsStop) break;
        const s = sites[i];
        const label = siteMetricsDomainLabel(s);
        setProgress({
          label: 'Syncing GSC…',
          detail: `${i + 1}/${sites.length} · ${label}`,
          pct: Math.round(((i + 0.5) / sites.length) * 100),
        });
        try {
          const result = await api('/api/gsc/sync', {
            method: 'POST',
            body: JSON.stringify({ siteId: s.id }),
          });
          if (result.ok) synced += 1;
          else {
            failed += 1;
            errors.push(`${label}: ${result.error || 'failed'}`);
          }
        } catch (error) {
          if (isGscAuthRevokedError(error)) {
            authRevoked = error;
            break;
          }
          failed += 1;
          errors.push(`${label}: ${error.message || error}`);
        }
        setProgress({
          label: 'Syncing GSC…',
          detail: `${i + 1}/${sites.length} · ${label}`,
          pct: Math.round(((i + 1) / sites.length) * 100),
        });
      }
      await loadSites();
    },
  );
  if (authRevoked) {
    await showGscReconnectModal(authRevoked);
    return;
  }
  await showModal({
    title: 'GSC sync',
    confirmLabel: 'OK',
    hideCancel: true,
    bodyHtml: `<p>Synced ${esc(synced)} · failed ${esc(failed)}</p>${
      state.sitesMetricsStop ? '<p>Stopped. Sites not started were left alone.</p>' : ''
    }${
      errors.length
        ? `<pre class="muted small" style="white-space:pre-wrap;max-height:160px;overflow:auto">${esc(
            errors.slice(0, 12).join('\n'),
          )}</pre>`
        : ''
    }`,
  });
}

async function checkSitesRanksSequential(siteList) {
  const sites = Array.isArray(siteList) ? siteList : [];
  if (!sites.length) {
    await showModal({
      title: 'Rank check',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>No eligible sites (need status live/listed/rented/building and a domain).</p>`,
    });
    return;
  }
  let checked = 0;
  let failed = 0;
  let costUsd = 0;
  let rankPostSkipped = false;
  let rankStopped = false;
  const errors = [];
  await withSitesMetricsBusy(
    {
      label: 'Checking ranks (Standard queue)…',
      detail: `0/${sites.length} sites`,
      pct: 0,
    },
    async ({ setProgress }) => {
      let timer = null;
      const paint = (progress) => {
        const kwTotal = Number(progress?.keywordsTotal) || 0;
        const kwReady = Number(progress?.keywordsReady) || 0;
        const sitesDone = Number(progress?.sitesDone) || 0;
        const sitesTotal = Number(progress?.sitesTotal) || sites.length;
        const detail = kwTotal
          ? `${kwReady}/${kwTotal} keywords ready · ${sitesDone}/${sitesTotal} sites`
          : `${sitesDone}/${sitesTotal} sites`;
        const pct = kwTotal
          ? Math.round((kwReady / kwTotal) * 100)
          : sitesTotal
            ? Math.round((sitesDone / sitesTotal) * 100)
            : 0;
        setProgress({
          label: 'Checking ranks (Standard queue)…',
          detail,
          pct,
        });
      };
      try {
        timer = setInterval(() => {
          api('/api/ranks/progress')
            .then((progress) => {
              if (progress?.running) paint(progress);
            })
            .catch(() => {});
        }, 2000);
        if (state.sitesMetricsStop) {
          rankPostSkipped = true;
          return;
        }
        const result = await api('/api/ranks/sync', {
          method: 'POST',
          body: JSON.stringify({ siteIds: sites.map((site) => site.id) }),
        });
        checked = Number(result.checked) || 0;
        failed = Number(result.failed) || 0;
        costUsd = Number(result.costUsd) || 0;
        rankStopped = Boolean(result.stopped);
        for (const row of result.results || []) {
          if (row.ok) continue;
          errors.push(`${row.domain || row.siteId}: ${row.error || 'finished with errors'}`);
        }
        await loadSites();
      } finally {
        if (timer) clearInterval(timer);
      }
    },
  );
  if (rankPostSkipped) {
    await showModal({
      title: 'Rank check',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: '<p>Stopped before the rank check was sent.</p>',
    });
    return;
  }
  await showModal({
    title: 'Rank sync',
    confirmLabel: 'OK',
    hideCancel: true,
    bodyHtml: `<p>Checked ${esc(checked)} · failed ${esc(failed)} · cost ~$${esc(
      Number(costUsd || 0).toFixed(4),
    )}</p>${
      rankStopped
        ? '<p>Stopped. Keywords not posted were left alone. Keywords already ready were saved.</p>'
        : ''
    }${
      errors.length
        ? `<pre class="muted small" style="white-space:pre-wrap;max-height:160px;overflow:auto">${esc(
            errors.slice(0, 12).join('\n'),
          )}</pre>`
        : ''
    }`,
  });
}

const INDEX_CHECK_CONCURRENCY = 4;

async function checkSitesIndexSequential(siteList) {
  const sites = Array.isArray(siteList) ? siteList : [];
  if (!sites.length) {
    await showModal({
      title: 'Index check',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>No eligible sites (need status live/listed/rented/building and a domain).</p>`,
    });
    return;
  }
  let checked = 0;
  let failed = 0;
  let cached = 0;
  let fetched = 0;
  const errors = [];
  let authRevoked = null;
  await withSitesMetricsBusy(
    {
      label: 'Checking index…',
      detail: `0/${sites.length}`,
      pct: 0,
    },
    async ({ setProgress }) => {
      const running = [];
      let cursor = 0;
      let done = 0;
      let stop = false;

      const paint = () => {
        const names = running.map((job) => job.label).join(', ');
        const inflight = running.length
          ? ` · ${running.length} running${names ? ` · ${names}` : ''}`
          : '';
        setProgress({
          label: 'Checking index…',
          detail: state.sitesMetricsStop
            ? `Stopping… ${done}/${sites.length}`
            : `${done}/${sites.length}${inflight}`,
          pct: Math.round((done / sites.length) * 100),
        });
      };

      const runOne = async (site) => {
        const label = siteMetricsDomainLabel(site);
        const job = { label };
        running.push(job);
        paint();
        try {
          const result = await api(`/api/sites/${encodeURIComponent(site.id)}/index-check`, {
            method: 'POST',
            body: JSON.stringify({}),
          });
          cached += Number(result.inspectCached) || 0;
          fetched += Number(result.inspectFetched) || 0;
          if (result.stopped) {
            /* URLs already inspected were saved. */
          } else if (result.ok) checked += 1;
          else {
            failed += 1;
            errors.push(`${label}: ${result.error || 'finished with errors'}`);
          }
        } catch (error) {
          if (isGscAuthRevokedError(error)) {
            if (!authRevoked) authRevoked = error;
            stop = true;
            return;
          }
          failed += 1;
          errors.push(`${label}: ${error.message || error}`);
        } finally {
          const idx = running.indexOf(job);
          if (idx >= 0) running.splice(idx, 1);
          done += 1;
          paint();
        }
      };

      const worker = async () => {
        while (!stop && !state.sitesMetricsStop && cursor < sites.length) {
          const site = sites[cursor];
          cursor += 1;
          await runOne(site);
        }
      };

      const workers = Math.min(INDEX_CHECK_CONCURRENCY, sites.length);
      await Promise.all(Array.from({ length: workers }, () => worker()));
      await loadSites();
    },
  );
  if (authRevoked) {
    await showGscReconnectModal(authRevoked);
    return;
  }
  await showModal({
    title: 'Index check',
    confirmLabel: 'OK',
    hideCancel: true,
    bodyHtml: `<p>Checked ${esc(checked)} · failed ${esc(failed)} · inspected ${esc(fetched)} URLs · skipped ${esc(cached)} cached</p>${
      state.sitesMetricsStop ? '<p>Stopped. Sites not started were left alone.</p>' : ''
    }${
      errors.length
        ? `<pre class="muted small" style="white-space:pre-wrap;max-height:160px;overflow:auto">${esc(
            errors.slice(0, 12).join('\n'),
          )}</pre>`
        : ''
    }`,
  });
}

let sitesLoadInFlight = null;

function sitesTableHasRows() {
  return Boolean(document.querySelector('#sites-table tbody tr[data-id]'));
}

function setSitesTableLoading(visible) {
  noteTabWorking('sites', Boolean(visible));
  const wrap = document.querySelector('#view-sites .sites-table-wrap');
  const card = document.getElementById('sites-table-loading');
  if (wrap) wrap.classList.toggle('is-loading', Boolean(visible));
  if (!card) return;
  card.classList.toggle('hidden', !visible);
  card.hidden = !visible;
  card.setAttribute('aria-busy', visible ? 'true' : 'false');
}

function renderSitesLoadError(message) {
  setSitesTableLoading(false);
  const table = document.getElementById('sites-table');
  const tbody = table?.querySelector('tbody');
  const thead = table?.querySelector('thead');
  if (thead) thead.innerHTML = '';
  if (tbody) {
    const detail = String(message || 'Unknown error');
    tbody.innerHTML = `<tr><td class="muted">Could not load launched sites. ${esc(detail)}</td></tr>`;
  }
  const countEl = document.getElementById('sites-filter-count');
  if (countEl) countEl.textContent = '';
}

async function loadSites() {
  if (sitesLoadInFlight) return sitesLoadInFlight;
  const showPlaceholder = !sitesTableHasRows();
  if (showPlaceholder) {
    setSitesTableLoading(true);
    const countEl = document.getElementById('sites-filter-count');
    if (countEl) countEl.textContent = 'Loading…';
  } else {
    const countEl = document.getElementById('sites-filter-count');
    if (countEl) countEl.textContent = 'Refreshing…';
  }
  sitesLoadInFlight = (async () => {
    try {
      const data = await api('/api/sites');
      state.sites = data.sites || [];
      state.launchedGroups = data.groups || [];
      const knownSiteIds = new Set(state.sites.map((s) => s.id));
      for (const id of [...state.selectedSiteIds]) {
        if (!knownSiteIds.has(id)) state.selectedSiteIds.delete(id);
      }
      state.siteStatuses = data.statuses || [];
      state.sitePaymentMethods = data.paymentMethods || [];
      state.siteBillingCycles = data.billingCycles || [];
      state.gscStatus = data.gsc || null;
      state.sitesPortfolio = data.portfolio || { traffic: [], ranks: [] };
      setSitesTableLoading(false);
      fillSitesStateFilter();
      fillLaunchedGroupSelects();
      fillZoneNumberFilters();
      renderSitesGscStatus();
      renderSitesPortfolioCharts();
      renderSitesTable();
      renderSitesDetail();
    } catch (error) {
      setSitesTableLoading(false);
      if (showPlaceholder) {
        renderSitesLoadError(error?.message);
      } else {
        try {
          renderSitesTable();
        } catch {
          /* keep the rows already on screen */
        }
      }
      throw error;
    } finally {
      sitesLoadInFlight = null;
    }
  })();
  return sitesLoadInFlight;
}

function fillSitesStateFilter() {
  const sel = document.getElementById('sites-filter-state');
  if (!sel) return;
  const current = state.siteFilters.state || '';
  const states = [
    ...new Set(state.sites.map((s) => String(s.state || '').trim().toUpperCase()).filter(Boolean)),
  ].sort();
  sel.innerHTML =
    `<option value="">State: all</option>` +
    states.map((st) => `<option value="${esc(st)}">${esc(st)}</option>`).join('');
  sel.value = current;
}

function filteredSites() {
  const text = String(state.siteFilters.text || '')
    .trim()
    .toLowerCase();
  const status = state.siteFilters.status || '';
  const st = String(state.siteFilters.state || '')
    .trim()
    .toUpperCase();
  const groupF = state.siteFilters.group || '';
  const zoneF = state.siteFilters.zone || '';
  const clusterF = state.siteFilters.cluster || '';
  let rows = state.sites.filter((s) => {
    if (status && s.status !== status) return false;
    if (st && String(s.state || '').toUpperCase() !== st) return false;
    if (groupF === '__ungrouped') {
      if ((s.groupIds || []).length) return false;
    } else if (groupF && !(s.groupIds || []).includes(groupF)) {
      return false;
    }
    if (zoneF) {
      const zn = Number(s.sgNumber ?? s.shotgunSg);
      if (!Number.isFinite(zn) || String(zn) !== String(zoneF)) return false;
    }
    if (clusterF === '0') {
      if (rowClusterKey(s)) return false;
    } else if (clusterF && String(rowClusterKey(s)) !== String(clusterF)) {
      return false;
    }
    if (!text) return true;
    const hay = [
      s.niche,
      s.city,
      s.state,
      s.domain,
      s.businessName,
      s.candidateId,
      s.email,
      s.shotgunSg,
      formatZnDisplay(s.sgNumber ?? s.shotgunSg),
      shotgunRoleLabel(s.shotgunRole, s),
      rowClusterKey(s) ? `cluster ${rowClusterKey(s)}` : '',
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase();
    return hay.includes(text);
  });

  const { key, dir } = state.siteSort;
  rows = [...rows].sort((a, b) => {
    const av = siteSortValue(a, key);
    const bv = siteSortValue(b, key);
    if (av == null && bv == null) return 0;
    if (av == null) return 1;
    if (bv == null) return -1;
    if (typeof av === 'number' && typeof bv === 'number') return (av - bv) * dir;
    return String(av).localeCompare(String(bv), undefined, { sensitivity: 'base' }) * dir;
  });
  return rows;
}

function siteSortValue(s, key) {
  if (key === 'shotgunSg') {
    const n = Number(s.sgNumber ?? s.shotgunSg);
    return Number.isFinite(n) && n >= 1 ? n : null;
  }
  if (key === 'shotgunClusterKey') {
    const n = rowClusterKey(s);
    return n >= 1 ? n : null;
  }
  if (key === 'shotgunRole') {
    if (String(s.shotgunRole || '').toLowerCase() === 'hub') return 1;
    const ck = rowClusterKey(s);
    return ck >= 1 ? ck + 1 : null;
  }
  return s[key];
}

function formatSiteMoney(n) {
  if (n == null || n === '') return '—';
  return formatMoney(n, 0);
}

function formatSiteDate(iso) {
  if (!iso) return '—';
  try {
    return new Date(iso).toLocaleDateString();
  } catch {
    return String(iso).slice(0, 10);
  }
}

function formatSiteWordCount(n) {
  if (n == null || n === '') return '—';
  const num = Number(n);
  if (!Number.isFinite(num)) return '—';
  if (num >= 10000) {
    const k = num / 1000;
    return `${k >= 100 ? Math.round(k) : k.toFixed(1).replace(/\.0$/, '')}k`;
  }
  return String(Math.round(num));
}

function formatSitemapIndexed(s) {
  if (s?.inspectIndexed == null && s?.inspectSubmitted == null) return '—';
  if (s.inspectSubmitted == null) return formatSiteMetricNum(s.inspectIndexed);
  return `${s.inspectIndexed ?? 0}/${s.inspectSubmitted}`;
}

function sitemapIndexedTip(s) {
  if (s?.inspectIndexed == null && s?.inspectSubmitted == null) {
    return s?.inspectError ? `No index check yet. ${s.inspectError}` : 'No index check yet.';
  }
  const when = s.inspectCheckedAt ? formatSiteDate(s.inspectCheckedAt) : '';
  const whenBit = when ? ` Last checked ${when}.` : '';
  const err = s.inspectError ? ` ${s.inspectError}` : '';
  return `${s.inspectIndexed ?? 0} of ${s.inspectSubmitted ?? '—'} sitemap pages are indexed.${whenBit}${err}`;
}

function formatSiteInventoryLine(s) {
  const pages = s.pageCount == null ? '—' : String(s.pageCount);
  const words = s.wordCount == null ? '—' : formatSiteWordCount(s.wordCount);
  const idx =
    s.inspectIndexed == null && s.inspectSubmitted == null
      ? 'Indexed —'
      : `Indexed ${s.inspectIndexed ?? 0} / ${s.inspectSubmitted ?? '—'} sitemap URLs`;
  const notIdx =
    s.inspectNotIndexed == null ? '' : ` · ${s.inspectNotIndexed} not indexed`;
  return `${idx}${notIdx} · ${pages} pages on site · ${words} words`;
}

function renderGscMetricRowsHtml(rows, keyName) {
  const list = Array.isArray(rows) ? rows : [];
  if (!list.length) {
    return `<tr><td colspan="5" class="muted">No ${keyName === 'query' ? 'queries' : 'pages'} with impressions yet (GSC only reports search traffic).</td></tr>`;
  }
  return list
    .map((row) => {
      const label = row[keyName] || '—';
      const ctr = row.ctr == null ? '—' : `${(Number(row.ctr) * 100).toFixed(1)}%`;
      return `<tr>
        <td>${esc(label)}</td>
        <td>${esc(formatSiteMetricNum(row.clicks))}</td>
        <td>${esc(formatSiteMetricNum(row.impressions))}</td>
        <td>${esc(ctr)}</td>
        <td>${esc(formatSiteMetricNum(row.position, 1))}</td>
      </tr>`;
    })
    .join('');
}

function renderGscQueriesTableHtml(s) {
  const gsc = s?.metrics?.gsc || {};
  const queries = gsc.topQueries || [];
  const pages = gsc.topPages || [];
  return `
      <h3 class="sites-kw-heading heading-with-info"><span>GSC queries (28d)</span><button type="button" class="tip-info" data-tip="Searches that showed this site. Empty until Google has traffic." aria-label="About GSC queries">i</button></h3>
      <div class="sites-gsc-table-wrap">
        <table class="sites-gsc-table">
          <thead><tr><th>Query</th><th>Clicks</th><th>Impr</th><th>CTR</th><th>Pos</th></tr></thead>
          <tbody>${renderGscMetricRowsHtml(queries, 'query')}</tbody>
        </table>
      </div>
      <h3 class="sites-kw-heading">GSC pages (28d)</h3>
      <div class="sites-gsc-table-wrap">
        <table class="sites-gsc-table">
          <thead><tr><th>Page</th><th>Clicks</th><th>Impr</th><th>CTR</th><th>Pos</th></tr></thead>
          <tbody>${renderGscMetricRowsHtml(pages, 'page')}</tbody>
        </table>
      </div>`;
}

function emptyStateForSitesFilter() {
  if (!state.sites.length) {
    return 'No launched sites yet — Run Launch on a Website candidate.';
  }
  const groupF = state.siteFilters.group || '';
  if (groupF === '__ungrouped') return 'No ungrouped launched sites for this filter.';
  if (groupF) {
    const g = (state.launchedGroups || []).find((x) => x.id === groupF);
    return `No launched sites in group “${g?.name || groupF}”.`;
  }
  if (state.siteFilters.text || state.siteFilters.status || state.siteFilters.state) {
    return 'No launched sites match these filters.';
  }
  return 'No launched sites match these filters.';
}

function updateSitesSelectionCount() {
  const nSelected = state.selectedSiteIds.size;
  const el = document.getElementById('sites-selection-count');
  if (el) el.textContent = `${nSelected} selected`;
  const disable = nSelected === 0;
  const groupAction = document.getElementById('sites-group-action');
  const groupAddBtn = document.getElementById('sites-group-add-btn');
  const groupRemoveBtn = document.getElementById('sites-group-remove-btn');
  if (groupAction) groupAction.disabled = disable;
  if (groupAddBtn) groupAddBtn.disabled = disable;
  if (groupRemoveBtn) groupRemoveBtn.disabled = disable;
}

function afterSitesCheckboxSelection(rows) {
  updateSitesSelectionCount();
  syncHeaderSelectAll(document.getElementById('sites-select-all'), {
    selectedCount: rows.filter((s) => state.selectedSiteIds.has(s.id)).length,
    totalCount: rows.length,
  });
}

function renderSitesTable() {
  const table = document.getElementById('sites-table');
  if (!table) return;
  const thead = table.querySelector('thead');
  const tbody = table.querySelector('tbody');
  const rows = filteredSites();
  const countEl = document.getElementById('sites-filter-count');
  if (countEl) {
    countEl.textContent = `${rows.length} of ${state.sites.length}`;
  }
  const colCount = SITE_TABLE_COLS.length + 1;

  thead.innerHTML = `<tr><th class="sites-select-col" data-tip="Select filtered"><input type="checkbox" id="sites-select-all" data-tip="Select filtered" /></th>${SITE_TABLE_COLS.map(
    (col) => {
      const tip = col.tip ? ` data-tip="${esc(col.tip)}"` : '';
      const cls = [col.sortable === false ? '' : 'sortable', col.cellClass || '']
        .filter(Boolean)
        .join(' ');
      const classAttr = cls ? ` class="${esc(cls)}"` : '';
      if (col.sortable === false) {
        return `<th${classAttr}${tip}>${esc(col.label)}</th>`;
      }
      const active = state.siteSort.key === col.key;
      const arrow = active ? (state.siteSort.dir > 0 ? ' ↑' : ' ↓') : '';
      return `<th${classAttr} data-sort="${esc(col.key)}"${tip}>${esc(col.label)}${arrow}</th>`;
    },
  ).join('')}</tr>`;

  if (!rows.length) {
    tbody.innerHTML = `<tr><td colspan="${colCount}" class="muted">${esc(emptyStateForSitesFilter())}</td></tr>`;
  } else {
    tbody.innerHTML = rows
      .map((s) => {
        const active = s.id === state.selectedSiteId ? 'active' : '';
        const checked = state.selectedSiteIds.has(s.id) ? 'checked' : '';
        const domainCell = s.liveUrl
          ? `<a href="${esc(s.liveUrl)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">${esc(
              s.domain || s.liveUrl,
            )}</a>`
          : esc(s.domain || '—');
        const city = s.city || '';
        const st = s.state || '';
        const mapCell =
          !city || !st
            ? `<td class="muted">—</td>`
            : `<td><button type="button" class="btn btn-sm sites-open-map" data-city="${esc(
                city,
              )}" data-state="${esc(st)}" data-tip="Open Map zoomed to ${esc(city)}, ${esc(
                st,
              )}">Map</button></td>`;
        const ck = rowClusterKey(s);
        const fill = clusterColor(ck);
        const clStyle = fill ? ` style="color:${fill};font-weight:700"` : '';
        const hub = String(s.shotgunRole || '').toLowerCase() === 'hub';
        const cityLabel = cityMapLabel(s.city || '—', rowClusterKey(s), { hub });
        const zoneBtn = s.shotgunClusterId
          ? ` <button type="button" class="btn btn-sm zone-map-open" data-zone-id="${esc(s.shotgunClusterId)}">Zone</button>`
          : '';
        const sgAttr = clusterRowAttr(s);
        return `<tr class="${active}" data-id="${esc(s.id)}"${sgAttr}>
          <td class="sites-select-col"><input type="checkbox" class="sites-check" data-id="${esc(
            s.id,
          )}" ${checked} /></td>
          <td>${esc(s.niche || '—')}</td>
          <td>${esc(cityLabel)}${zoneBtn}</td>
          <td>${esc(s.state || '—')}</td>
          <td class="col-sg">${esc(formatZnDisplay(s.sgNumber ?? s.shotgunSg) || '—')}</td>
          <td class="col-sg-role"${clStyle}>${esc(ck ? String(ck) : '—')}</td>
          ${mapCell}
          <td>${domainCell}</td>
          <td><span class="site-status site-status-${esc(s.status || '')}">${esc(s.status || '—')}</span></td>
          <td>${esc(formatSiteMetricNum(s.clicks28d))}</td>
          <td>${esc(formatSiteMetricNum(s.impressions28d))}</td>
          <td>${esc(formatSiteMetricNum(s.pageCount))}</td>
          <td>${esc(formatSiteWordCount(s.wordCount))}</td>
          <td data-tip="${esc(sitemapIndexedTip(s))}">${esc(formatSitemapIndexed(s))}</td>
          <td>${esc(s.primaryPosition == null ? '—' : s.primaryPosition)}</td>
          <td>${esc(s.primaryPage == null ? '—' : s.primaryPage)}</td>
          <td>${esc(formatSiteDate(s.gscLastSyncAt))}</td>
          <td>${esc(formatSiteDate(s.lastRankCheckAt))}</td>
          <td>${esc(formatSiteMoney(s.targetRentUsd))}</td>
          <td>${esc(formatSiteMoney(s.actualRentUsd))}</td>
          <td>${esc(formatSiteDate(s.lastLaunchAt))}</td>
        </tr>`;
      })
      .join('');
  }

  afterSitesCheckboxSelection(rows);

  document.getElementById('sites-select-all')?.addEventListener('change', (e) => {
    const on = e.target.checked;
    for (const s of rows) {
      if (on) state.selectedSiteIds.add(s.id);
      else state.selectedSiteIds.delete(s.id);
    }
    renderSitesTable();
  });
  thead.querySelectorAll('th.sortable').forEach((th) => {
    th.addEventListener('click', () => {
      const key = th.dataset.sort;
      if (state.siteSort.key === key) state.siteSort.dir *= -1;
      else state.siteSort = { key, dir: key === 'lastLaunchAt' ? -1 : 1 };
      persistUiRestore();
      renderSitesTable();
    });
  });
  tbody.querySelectorAll('tr[data-id]').forEach((tr) => {
    tr.addEventListener('click', (e) => {
      if (e.target.closest('button.sites-open-map, a, input.sites-check')) return;
      state.selectedSiteId = tr.dataset.id;
      renderSitesTable();
      renderSitesDetail();
    });
  });
  tbody.querySelectorAll('input.sites-check').forEach((cb) => {
    const applySitesShiftRange = (e) => {
      const id = cb.dataset.id;
      return applyShiftRangeCheckboxClick(e, {
        visibleKeys: rows.map((s) => s.id),
        clickedKey: id,
        anchorKey: state.siteCheckAnchor,
        setAnchor: (key) => {
          state.siteCheckAnchor = key;
        },
        setSelected: (key, on) => {
          if (on) state.selectedSiteIds.add(key);
          else state.selectedSiteIds.delete(key);
        },
      });
    };
    cb.addEventListener('pointerdown', (e) => {
      e.stopPropagation();
      if (!e.shiftKey || state.siteCheckAnchor == null) return;
      blockShiftRangePointerDown(e, state.siteCheckAnchor);
      if (applySitesShiftRange(e)) renderSitesTable();
    });
    cb.addEventListener('click', (e) => {
      e.stopPropagation();
      if (applySitesShiftRange(e)) renderSitesTable();
    });
    cb.addEventListener('change', (e) => {
      e.stopPropagation();
      const id = cb.dataset.id;
      if (consumeShiftRangeChange(cb, id)) {
        cb.checked = state.selectedSiteIds.has(id);
        return;
      }
      state.siteCheckAnchor = id;
      if (cb.checked) state.selectedSiteIds.add(id);
      else state.selectedSiteIds.delete(id);
      afterSitesCheckboxSelection(rows);
    });
  });
  tbody.querySelectorAll('button.sites-open-map').forEach((btn) => {
    btn.addEventListener('click', async (e) => {
      e.stopPropagation();
      const city = btn.dataset.city || '';
      const st = btn.dataset.state || '';
      setView('map');
      try {
        await openResearchMap({ city, state: st }, { api, esc, showModal });
      } catch (error) {
        await showModal({
          title: 'Map failed',
          confirmLabel: 'OK',
          hideCancel: true,
          bodyHtml: `<p>${esc(error.message)}</p>`,
        });
      }
    });
  });
  enableTableColumnResize(table);
}

function selectedSite() {
  return state.sites.find((s) => s.id === state.selectedSiteId) || null;
}

/** Portfolio or hydrate flags: already shipped / live enough for Push (not first Launch). */
function sitePortfolioIsLive(s) {
  if (!s) return false;
  if (['live', 'listed', 'rented'].includes(String(s.status || ''))) return true;
  return Boolean(s.lastShipAt || s.lastLaunchAt || s.cloudflarePagesDone);
}

/**
 * Sites: Prepare-equivalent (Stage → Assemble with ship) + Push when already live.
 * Does not Run launch (domain/email) — hand off to Website tab for first go-live.
 */
async function publishSitePhoneFromSites(s) {
  const id = s?.candidateId;
  if (!id) return;

  const statusEl = document.getElementById('sites-phone-publish-status');
  const provisionBtn = document.getElementById('sites-provision-twilio');
  const updateBtn = document.getElementById('sites-update-site-phone');
  const setStatus = (text) => {
    if (!statusEl) return;
    if (!text) {
      statusEl.hidden = true;
      statusEl.textContent = '';
      return;
    }
    statusEl.hidden = false;
    statusEl.textContent = text;
  };
  const setBusy = (busy) => {
    if (updateBtn) updateBtn.disabled = busy;
    if (provisionBtn) {
      // Stay disabled while busy or when already provisioned
      provisionBtn.disabled =
        busy || Boolean(s.phoneTracking?.provider === 'twilio' && s.phoneTracking?.twilioSid);
    }
  };

  const alreadyLive = sitePortfolioIsLive(s);
  setBusy(true);
  setStatus('Staging full launch package…');

  try {
    await api(`/api/candidates/${encodeURIComponent(id)}/staging`, {
      method: 'POST',
      body: JSON.stringify({ mode: 'full', openPreview: false }),
    });

    setStatus('Assembling (npm install + build; auto-ship if credentials set)…');
    const assembled = await api(`/api/candidates/${encodeURIComponent(id)}/assemble`, {
      method: 'POST',
      body: JSON.stringify({ force: true, build: true, ship: true }),
    });

    const buildOk = assembled.build?.ok !== false;
    let ship = assembled.ship || null;
    const shipNeedsPush =
      alreadyLive &&
      (!ship?.ok || ship?.skipped || ship?.error);

    if (shipNeedsPush) {
      setStatus('Pushing updates to GitHub + Cloudflare…');
      try {
        const pushed = await api(`/api/candidates/${encodeURIComponent(id)}/ship`, {
          method: 'POST',
          body: JSON.stringify({}),
        });
        ship = {
          ok: Boolean(pushed.ok),
          ...(pushed.ok ? {} : { error: pushed.error || 'Push incomplete' }),
          pushed: true,
          human: pushed.human,
        };
      } catch (error) {
        ship = { ok: false, error: error.message, pushed: true };
      }
    }

    await loadSites();
    renderSitesTable();
    renderSitesDetail();

    if (!alreadyLive) {
      const goWebsite = await showModal({
        title: 'Package prepared',
        confirmLabel: 'Open Website tab',
        cancelLabel: 'Stay on Launched',
        bodyHtml: `<p>Stage → Assemble finished${
          buildOk ? '' : ' (build reported a problem — check Website)'
        }. Assembled site-config includes the new phone.</p>
          <p>This listing is <strong>not live yet</strong>. Finish first go-live with <strong>Website → Run launch</strong> (domain / email). Launch is not run from Launched.</p>`,
      });
      if (goWebsite) {
        setView('website-builder');
        await selectCandidate(id);
        state.tab = 'website';
        if (typeof advancePanelStep === 'function') {
          try {
            advancePanelStep('website', 'launch');
          } catch {
            /* ignore */
          }
        }
        renderDetail();
      }
      return;
    }

    const shipLine = ship?.ok
      ? ship.pushed
        ? 'Push updates ok'
        : 'Auto-ship ok'
      : ship?.skipped
        ? `Ship skipped — ${ship.reason || 'credentials missing'}`
        : ship?.error
          ? `Ship issue: ${ship.error}`
          : 'Ship status unknown';

    await showModal({
      title: ship?.ok ? 'Live phone updated' : 'Prepared (check ship)',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>Stage → Assemble complete for <code>${esc(id)}</code>.</p>
        <p>${esc(shipLine)}</p>
        <p class="muted small">Live CTAs should show <code>${esc(formatDisplayPhone(s.phoneTracking?.e164 || s.phone || ''))}</code> after Cloudflare finishes the deploy.</p>`,
    });
  } catch (error) {
    await showModal({
      title: 'Update site phone failed',
      confirmLabel: 'OK',
      bodyHtml: `<p>${esc(error.message)}</p>`,
    });
    setStatus('');
    renderSitesDetail();
  }
}

function renderSitesDetail() {
  const empty = document.getElementById('sites-empty-detail');
  const body = document.getElementById('sites-detail-body');
  if (!empty || !body) return;
  syncSitesDetailVisibility();
  const s = selectedSite();
  if (!s) {
    empty.classList.remove('hidden');
    body.classList.add('hidden');
    body.innerHTML = '';
    return;
  }
  empty.classList.add('hidden');
  body.classList.remove('hidden');
  const r = s.renter || {};
  const statusOpts = (state.siteStatuses.length ? state.siteStatuses : ['building', 'live', 'listed', 'rented', 'paused', 'retired'])
    .map((v) => `<option value="${esc(v)}" ${s.status === v ? 'selected' : ''}>${esc(v)}</option>`)
    .join('');
  const payOpts =
    `<option value="">—</option>` +
    (state.sitePaymentMethods.length
      ? state.sitePaymentMethods
      : ['ach', 'card', 'check', 'wire', 'cash', 'other']
    )
      .map((v) => `<option value="${esc(v)}" ${s.paymentMethod === v ? 'selected' : ''}>${esc(v)}</option>`)
      .join('');
  const billingOpts = (state.siteBillingCycles.length
    ? state.siteBillingCycles
    : ['monthly', 'annual', 'one_time', 'other']
  )
    .map((v) => `<option value="${esc(v)}" ${s.billingCycle === v ? 'selected' : ''}>${esc(v)}</option>`)
    .join('');

  body.innerHTML = `
    <div class="sites-detail-head">
      <div class="sites-detail-head-main">
        <h2>${esc(s.businessName || s.niche || s.domain || 'Site')}</h2>
        <p class="muted"${
          s.candidateId ? ` data-tip="Candidate ${esc(s.candidateId)}"` : ''
        }>${esc([s.city, s.state].filter(Boolean).join(', ') || '—')}</p>
      </div>
      ${
        s.candidateId
          ? `<button type="button" class="btn primary btn-sm" id="sites-visual-edit" data-tip="Edit the site. Visitors never see this screen.">Edit site</button>
             <button type="button" class="btn btn-sm" id="sites-shotgun-metro" data-tip="Make this city the hub and pick nearby cities.">Cluster this metro</button>
             ${s.shotgunClusterId ? `<button type="button" class="btn btn-sm zone-map-open" data-zone-id="${esc(s.shotgunClusterId)}">Zone map</button>` : ''}`
          : ''
      }
    </div>
    ${zoneGuideNoteHtml(s)}
    <div class="sites-detail-links muted small">
      ${s.liveUrl ? `<a href="${esc(s.liveUrl)}" target="_blank" rel="noopener">Live</a>` : ''}
      ${s.cloudflareDashboardUrl ? `<a href="${esc(s.cloudflareDashboardUrl)}" target="_blank" rel="noopener">Cloudflare</a>` : ''}
      ${s.githubRepoUrl ? `<a href="${esc(s.githubRepoUrl)}" target="_blank" rel="noopener">GitHub</a>` : ''}
      ${
        s.gscPropertyUrl
          ? `<a href="https://search.google.com/search-console" target="_blank" rel="noopener">GSC</a>`
          : ''
      }
    </div>
    ${
      s.web3FormsRecipient
        ? `<p class="muted small sites-w3-recipient"><code id="sites-w3-recipient">${esc(s.web3FormsRecipient)}</code>
           <button type="button" class="btn btn-sm" id="sites-w3-copy">Copy</button>
           <button type="button" class="tip-info" data-tip="The public leads address. Mail is forwarded from here." aria-label="About leads address">i</button></p>`
        : ''
    }
    ${
      s.candidateId && (s.status === 'paused' || s.status === 'retired')
        ? `<p class="muted small sites-detail-status-note">Site is ${esc(s.status)} — visual edits still go to candidate source, then Publish to ship.</p>`
        : !s.candidateId
          ? `<p class="muted small sites-detail-status-note">No candidate id — cannot visual-edit this row.</p>`
          : ''
    }
    <div class="sites-metrics-block">
      <h3>Search metrics</h3>
      <p class="muted small sites-metrics-summary">
        28d: ${esc(formatSiteMetricNum(s.clicks28d))} clicks ·
        ${esc(formatSiteMetricNum(s.impressions28d))} impr ·
        CTR ${esc(s.ctr28d == null ? '—' : `${(Number(s.ctr28d) * 100).toFixed(1)}%`)} ·
        avg pos ${esc(formatSiteMetricNum(s.avgPosition28d, 1))}
        ${s.gscSyncError ? `<br/><span class="sites-metric-err">GSC: ${esc(s.gscSyncError)}</span>` : ''}
      </p>
      <p class="muted small sites-metrics-summary">
        ${esc(formatSiteInventoryLine(s))}
        ${s.inspectError ? `<br/><span class="sites-metric-err">Index: ${esc(s.inspectError)}</span>` : ''}
      </p>
      <p class="muted small sites-metrics-summary">
        Primary rank: pos ${esc(s.primaryPosition == null ? '—' : s.primaryPosition)} ·
        page ${esc(s.primaryPage == null ? '—' : s.primaryPage)}
        ${s.rankSyncError ? `<br/><span class="sites-metric-err">Ranks: ${esc(s.rankSyncError)}</span>` : ''}
      </p>
      <div class="sites-detail-charts">
        <div class="sites-chart-card">
          <h3>Traffic</h3>
          <div id="sites-detail-chart-traffic" class="sites-chart"></div>
        </div>
        <div class="sites-chart-card">
          <h3>Keyword position</h3>
          <div id="sites-detail-chart-ranks" class="sites-chart"></div>
        </div>
      </div>
      ${renderGscQueriesTableHtml(s)}
      <h3 class="sites-kw-heading">Tracked keywords (≤5)</h3>
      <div id="sites-kw-list"></div>
      <div class="sites-kw-actions">
        <button type="button" class="btn primary btn-sm" id="sites-kw-save">Save keywords</button>
        <button type="button" class="btn btn-sm" id="sites-kw-add">Add keyword</button>
        <button type="button" class="btn btn-sm" id="sites-rank-check-one">Check ranks</button>
        <button type="button" class="btn btn-sm" id="sites-index-check-one"${gscSignedIn() && !state.sitesMetricsBusy ? '' : ' disabled'}>Check index</button>
        <button type="button" class="btn btn-sm" id="sites-gsc-sync-one"${gscSignedIn() && !state.sitesMetricsBusy ? '' : ' disabled'}>Sync GSC</button>
      </div>
    </div>
    <form id="sites-edit-form" class="sites-edit-form">
      <h3>Portfolio</h3>
      <div class="sites-field-row">
        <label>Status <select name="status">${statusOpts}</select></label>
        <label>Billing cycle <select name="billingCycle">${billingOpts}</select></label>
      </div>
      <div class="sites-field-row">
        <label>Target rent ($/mo) <input name="targetRentUsd" type="number" step="1" min="0" value="${esc(s.targetRentUsd ?? '')}" /></label>
        <label>Actual rent ($/mo) <input name="actualRentUsd" type="number" step="1" min="0" value="${esc(s.actualRentUsd ?? '')}" /></label>
      </div>
      <div class="sites-field-row">
        <label>Payment method <select name="paymentMethod">${payOpts}</select></label>
        <label>Payment notes <input name="paymentMethodNotes" type="text" value="${esc(s.paymentMethodNotes || '')}" /></label>
      </div>
      <div class="sites-field-row">
        <label>Contract start <input name="contractStart" type="date" value="${esc((s.contractStart || '').slice(0, 10))}" /></label>
        <label>Contract end <input name="contractEnd" type="date" value="${esc((s.contractEnd || '').slice(0, 10))}" /></label>
      </div>
      <label class="sites-field-span">Next invoice <input name="nextInvoiceAt" type="date" value="${esc((s.nextInvoiceAt || '').slice(0, 10))}" /></label>
      <h3>Renter</h3>
      <div class="sites-field-row">
        <label>Business <input name="renterBusinessName" type="text" value="${esc(r.businessName || '')}" /></label>
        <label>Contact <input name="renterContactName" type="text" value="${esc(r.contactName || '')}" /></label>
      </div>
      <div class="sites-field-row">
        <label>Email <input name="renterEmail" type="email" value="${esc(r.email || '')}" /></label>
        <label>Phone <input name="renterPhone" type="text" value="${esc(formatDisplayPhone(r.phone || ''))}" /></label>
      </div>
      <label class="sites-field-span">Renter notes <textarea name="renterNotes" rows="2">${esc(r.notes || '')}</textarea></label>
      <label class="sites-field-span">Site notes <textarea name="notes" rows="2">${esc(s.notes || '')}</textarea></label>
      <div class="sites-form-actions">
        <button type="submit" class="btn primary">Save</button>
      </div>
    </form>
    <p class="muted small sites-nap-line"${
      s.launchCostUsd != null ? ` data-tip="Launch costs ~${esc(formatMoney(s.launchCostUsd))}"` : ''
    }>Site NAP: ${esc(formatDisplayPhone(s.phone || '—'))} · ${esc(s.email || '—')}</p>
    <div class="sites-phone-tracking">
      <h3>Phone tracking</h3>
      ${
        s.phoneTracking?.provider === 'twilio' && s.phoneTracking?.e164
          ? `<p class="muted small">${esc(formatDisplayPhone(s.phoneTracking.e164))}${
              s.phoneTracking.phase ? ` · ${esc(s.phoneTracking.phase)}` : ''
            } · ${
              s.phoneTracking.forwardTo
                ? esc(formatDisplayPhone(s.phoneTracking.forwardTo))
                : 'voicemail'
            }</p>`
          : `<p class="muted small">No number yet</p>`
      }
      <div class="sites-phone-actions">
        <label class="sites-phone-area muted small">
          Area
          <input id="sites-twilio-area" type="text" inputmode="numeric" maxlength="3" placeholder="auto" />
        </label>
        <button type="button" class="btn primary btn-sm" id="sites-provision-twilio" ${
          !s.candidateId || (s.phoneTracking?.provider === 'twilio' && s.phoneTracking?.twilioSid)
            ? 'disabled'
            : ''
        } data-tip="Buys a local number, about $1.15 a month. Calls go to voicemail and text you.">Provision</button>
        <button type="button" class="btn btn-sm" id="sites-update-site-phone" ${
          s.candidateId && s.phoneTracking?.provider === 'twilio' && s.phoneTracking?.twilioSid
            ? ''
            : 'disabled'
        } data-tip="Rebuild the site so buttons show the new phone and address.">Update site phone</button>
        <button type="button" class="btn btn-sm" id="sites-forward-renter" ${
          s.phoneTracking?.provider === 'twilio' &&
          s.phoneTracking?.twilioSid &&
          String(s.renter?.phone || '').trim()
            ? ''
            : 'disabled'
        } data-tip="Keep this number and ring the renter instead of voicemail.">Forward to renter</button>
        <button type="button" class="btn btn-sm" id="sites-view-calls" ${
          s.phoneTracking?.provider === 'twilio' && s.phoneTracking?.e164 ? '' : 'disabled'
        }>View calls →</button>
      </div>
      <p class="muted small" id="sites-phone-publish-status" hidden></p>
      ${
        !s.candidateId
          ? `<p class="muted small">Link a candidate first (accepted site-config required).</p>`
          : ''
      }
    </div>
    <div class="sites-danger-zone">
      <h3>Remove</h3>
      <button type="button" class="btn danger solid" id="sites-delete-btn" data-tip="Removes this row only. The live site stays.">Remove from Sites</button>
    </div>
  `;

  // Per-site charts
  const daily = s.metrics?.gsc?.daily || [];
  renderSvgLineChart(
    document.getElementById('sites-detail-chart-traffic'),
    [
      { label: 'Clicks', color: '#2a9d8f', points: daily.map((r) => ({ y: r.clicks })) },
      { label: 'Impressions', color: '#e9c46a', points: daily.map((r) => ({ y: r.impressions })) },
    ],
    { yLabel: 'Site traffic', yFormat: 'number', minPoints: 2 },
  );
  const kwSeries = (s.rankKeywords || []).slice(0, 5).map((kw, idx) => {
    const hist = s.metrics?.ranks?.byKeyword?.[kw.keyword]?.history || [];
    const colors = ['#457b9d', '#2a9d8f', '#e9c46a', '#e76f51', '#9b5de5'];
    return {
      label: kw.isPrimary ? `${kw.keyword} (primary)` : kw.keyword,
      color: colors[idx % colors.length],
      points: hist
        .filter((p) => p.position != null && Number.isFinite(Number(p.position)))
        .map((p) => ({ y: Number(p.position) })),
    };
  });
  renderSvgLineChart(document.getElementById('sites-detail-chart-ranks'), kwSeries, {
    yLabel: 'Keyword position',
    yFormat: 'number',
    invertY: true,
    minPoints: 2,
  });

  const kwList = document.getElementById('sites-kw-list');
  const renderKwRows = (keywords) => {
    if (!kwList) return;
    const rows = keywords.length
      ? keywords
      : [{ keyword: '', isPrimary: true, source: 'manual' }];
    kwList.innerHTML = rows
      .map(
        (kw, i) => `<div class="sites-kw-row" data-idx="${i}">
        <label class="muted small" style="display:inline-flex;align-items:center;gap:0.25rem;white-space:nowrap">
          <input type="radio" name="sites-kw-primary" ${kw.isPrimary ? 'checked' : ''} /> Primary
        </label>
        <input type="text" class="sites-kw-input" value="${esc(kw.keyword || '')}" placeholder="keyword + city" maxlength="120" />
        <button type="button" class="btn sites-kw-remove" data-tip="Remove" aria-label="Remove">×</button>
      </div>`,
      )
      .join('');
    kwList.querySelectorAll('.sites-kw-remove').forEach((btn) => {
      btn.addEventListener('click', () => {
        const row = btn.closest('.sites-kw-row');
        row?.remove();
        if (!kwList.querySelector('.sites-kw-row')) renderKwRows([]);
      });
    });
  };
  renderKwRows(s.rankKeywords || []);

  document.getElementById('sites-kw-add')?.addEventListener('click', () => {
    const current = [...(kwList?.querySelectorAll('.sites-kw-row') || [])].map((row) => ({
      keyword: row.querySelector('.sites-kw-input')?.value || '',
      isPrimary: Boolean(row.querySelector('input[type=radio]')?.checked),
      source: 'manual',
    }));
    if (current.length >= 5) return;
    current.push({ keyword: '', isPrimary: false, source: 'manual' });
    renderKwRows(current);
  });

  document.getElementById('sites-kw-save')?.addEventListener('click', async () => {
    const keywords = [...(kwList?.querySelectorAll('.sites-kw-row') || [])].map((row) => ({
      keyword: row.querySelector('.sites-kw-input')?.value || '',
      isPrimary: Boolean(row.querySelector('input[type=radio]')?.checked),
      source: 'manual',
    }));
    try {
      await api(`/api/sites/${encodeURIComponent(s.id)}/rank-keywords`, {
        method: 'POST',
        body: JSON.stringify({ keywords }),
      });
      await loadSites();
    } catch (error) {
      await showModal({
        title: 'Save keywords failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });

  document.getElementById('sites-rank-check-one')?.addEventListener('click', async () => {
    if (state.sitesMetricsBusy) return;
    let result = null;
    try {
      await withSitesMetricsBusy(
        {
          label: 'Checking ranks (Standard queue)…',
          detail: siteMetricsDomainLabel(s),
          pct: null,
        },
        async ({ setProgress }) => {
          setProgress({
            label: 'Checking ranks (Standard queue)…',
            detail: `1/1 · ${siteMetricsDomainLabel(s)}`,
            pct: 50,
          });
          if (state.sitesMetricsStop) return;
          result = await api(`/api/sites/${encodeURIComponent(s.id)}/rank-check`, {
            method: 'POST',
            body: JSON.stringify({}),
          });
          setProgress({
            label: 'Checking ranks (Standard queue)…',
            detail: `1/1 · ${siteMetricsDomainLabel(s)}`,
            pct: 100,
          });
          await loadSites();
        },
      );
      if (result) {
        await showModal({
          title: result.ok ? 'Rank check done' : 'Rank check finished with errors',
          confirmLabel: 'OK',
          hideCancel: true,
          bodyHtml: `<p>Cost ~$${esc(Number(result.costUsd || 0).toFixed(4))}</p>
            ${
              result.stopped
                ? '<p>Stopped. Keywords not posted were left alone. Keywords already ready were saved.</p>'
                : ''
            }
            <pre class="muted small" style="white-space:pre-wrap">${esc(
              JSON.stringify(result.keywords || [], null, 2),
            )}</pre>`,
        });
      }
    } catch (error) {
      await showModal({
        title: 'Rank check failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });

  document.getElementById('sites-index-check-one')?.addEventListener('click', async () => {
    if (state.sitesMetricsBusy) return;
    let result = null;
    try {
      await withSitesMetricsBusy(
        {
          label: 'Checking index…',
          detail: siteMetricsDomainLabel(s),
          pct: null,
        },
        async ({ setProgress }) => {
          setProgress({
            label: 'Checking index…',
            detail: `1/1 · ${siteMetricsDomainLabel(s)}`,
            pct: 50,
          });
          if (state.sitesMetricsStop) return;
          result = await api(`/api/sites/${encodeURIComponent(s.id)}/index-check`, {
            method: 'POST',
            body: JSON.stringify({}),
          });
          setProgress({
            label: 'Checking index…',
            detail: `1/1 · ${siteMetricsDomainLabel(s)}`,
            pct: 100,
          });
          await loadSites();
        },
      );
      if (result) {
        await showModal({
          title: result.ok ? 'Index check done' : 'Index check finished with errors',
          confirmLabel: 'OK',
          hideCancel: true,
          bodyHtml: `<p>Indexed ${esc(result.inspectIndexed ?? '—')} / ${esc(
            result.inspectSubmitted ?? '—',
          )} sitemap URLs · inspected ${esc(result.inspectFetched ?? 0)} · skipped ${esc(
            result.inspectCached ?? 0,
          )} cached${result.stopped ? '<br/>Stopped. Remaining sitemap URLs were left alone.' : ''}${
            result.error ? `<br/>${esc(result.error)}` : ''
          }</p>
            <p class="muted small">URL Inspection of the sitemap (includes /privacy). Not the GSC Pages report.</p>`,
        });
      }
    } catch (error) {
      if (isGscAuthRevokedError(error)) {
        await showGscReconnectModal(error);
        return;
      }
      await showModal({
        title: 'Index check failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });

  document.getElementById('sites-gsc-sync-one')?.addEventListener('click', async () => {
    if (state.sitesMetricsBusy) return;
    let result = null;
    try {
      await withSitesMetricsBusy(
        {
          label: 'Syncing GSC…',
          detail: siteMetricsDomainLabel(s),
          pct: null,
        },
        async ({ setProgress }) => {
          setProgress({
            label: 'Syncing GSC…',
            detail: `1/1 · ${siteMetricsDomainLabel(s)}`,
            pct: 50,
          });
          if (state.sitesMetricsStop) return;
          result = await api('/api/gsc/sync', {
            method: 'POST',
            body: JSON.stringify({ siteId: s.id }),
          });
          setProgress({
            label: 'Syncing GSC…',
            detail: `1/1 · ${siteMetricsDomainLabel(s)}`,
            pct: 100,
          });
          await loadSites();
        },
      );
      if (result && !result.ok) {
        await showModal({
          title: 'GSC sync issue',
          confirmLabel: 'OK',
          hideCancel: true,
          bodyHtml: `<p>${esc(result.error || 'Unknown error')}</p>`,
        });
      }
    } catch (error) {
      if (isGscAuthRevokedError(error)) {
        await showGscReconnectModal(error);
        return;
      }
      await showModal({
        title: 'GSC sync failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });

  if (state.sitesMetricsBusy) setSitesMetricsButtonsDisabled(true);

  document.getElementById('sites-shotgun-metro')?.addEventListener('click', () => {
    if (s.candidateId) void shotgunThisMetro(s.candidateId);
  });

  document.getElementById('sites-w3-copy')?.addEventListener('click', async () => {
    const text = String(s.web3FormsRecipient || '').trim();
    if (!text) return;
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      /* ignore */
    }
  });

  document.getElementById('sites-visual-edit')?.addEventListener('click', async () => {
    if (!s.candidateId) return;
    if (s.status === 'paused' || s.status === 'retired') {
      const go = await showModal({
        title: `Site is ${s.status}`,
        confirmLabel: 'Edit anyway',
        bodyHtml: `<p>This listing is <strong>${esc(s.status)}</strong>. Visual edits still write candidate source, then Publish ships if credentials are set.</p>`,
      });
      if (!go) return;
    }
    await openVisualEditor(s.candidateId, { api, esc, showModal, formatDisplayPhone, phoneToE164 });
  });

  document.getElementById('sites-provision-twilio')?.addEventListener('click', async () => {
    if (!s.candidateId) return;
    const areaEl = document.getElementById('sites-twilio-area');
    const areaCode = String(areaEl?.value || '')
      .replace(/\D/g, '')
      .slice(0, 3);
    const ok = await showModal({
      title: 'Provision Twilio ranking number?',
      confirmLabel: 'Buy number',
      bodyHtml: `<p>Buys one US local number (~$1.15/mo + per-minute usage), sets site NAP, and takes a voicemail while ranking (texts <code>TWILIO_FORWARD_TO</code>). Rented sites still dial the renter.</p>
        <p class="muted small">${esc([s.city, s.state].filter(Boolean).join(', ') || 'geo from site-config')}${
          areaCode ? ` · area ${esc(areaCode)}` : ' · locality search'
        }</p>`,
    });
    if (!ok) return;
    try {
      const result = await api(`/api/sites/${encodeURIComponent(s.id)}/phone/provision-twilio`, {
        method: 'POST',
        body: JSON.stringify({
          confirm: true,
          ...(areaCode.length === 3 ? { areaCode } : {}),
        }),
      });
      const idx = state.sites.findIndex((x) => x.id === s.id);
      if (idx >= 0) state.sites[idx] = result.site;
      else await loadSites();
      renderSitesTable();
      renderSitesDetail();
      await showModal({
        title: 'Number provisioned',
        confirmLabel: 'OK',
        bodyHtml: `<p><strong>${esc(formatDisplayPhone(result.provisioned?.phone || result.provisioned?.e164 || ''))}</strong> written to site-config.</p>
          <p class="muted small">Next: click <strong>Update site phone number</strong> to Stage → Assemble (and Push if already live).</p>`,
      });
    } catch (error) {
      await showModal({
        title: 'Provision failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>${
          error.twilioSid
            ? `<p class="muted small">Twilio SID: <code>${esc(error.twilioSid)}</code>${
                error.e164 ? ` · ${esc(formatDisplayPhone(error.e164))}` : ''
              }. Do not buy again until this SID is resolved in Twilio Console.</p>`
            : ''
        }`,
      });
    }
  });

  document.getElementById('sites-update-site-phone')?.addEventListener('click', async () => {
    if (!s.candidateId || !(s.phoneTracking?.provider === 'twilio' && s.phoneTracking?.twilioSid)) return;
    const alreadyLive = sitePortfolioIsLive(s);
    const ok = await showModal({
      title: 'Update site phone number?',
      confirmLabel: alreadyLive ? 'Prepare + Push' : 'Prepare package',
      bodyHtml: alreadyLive
        ? `<p>Runs Stage → Assemble (with ship when credentials allow) and <strong>Push updates</strong> if ship did not finish — so live CTAs show <code>${esc(formatDisplayPhone(s.phoneTracking.e164 || s.phone || ''))}</code>.</p>
           <p class="muted small">Can take several minutes.</p>`
        : `<p>Runs Stage → Assemble so the assembled package has the new phone.</p>
           <p class="muted small">This site is not live yet — after Prepare you still need <strong>Website → Run launch</strong> for first go-live (domain / email). Launch is not run from here.</p>`,
    });
    if (!ok) return;
    await publishSitePhoneFromSites(s);
  });

  document.getElementById('sites-forward-renter')?.addEventListener('click', async () => {
    if (!(s.phoneTracking?.provider === 'twilio' && s.phoneTracking?.twilioSid)) return;
    if (!String(s.renter?.phone || '').trim()) return;
    const ok = await showModal({
      title: 'Forward to renter?',
      confirmLabel: 'Update Twilio',
      bodyHtml: `<p>Keeps the same tracking DID <code>${esc(formatDisplayPhone(s.phoneTracking.e164 || ''))}</code> and dials <code>${esc(formatDisplayPhone(s.renter.phone))}</code> instead of your ranking forward.</p>
        <p class="muted small">Sets phone phase to <strong>rented</strong>. Whisper still plays to whoever answers.</p>`,
    });
    if (!ok) return;
    try {
      const result = await api(`/api/sites/${encodeURIComponent(s.id)}/phone/forward-renter`, {
        method: 'POST',
        body: JSON.stringify({ confirm: true }),
      });
      const idx = state.sites.findIndex((x) => x.id === s.id);
      if (idx >= 0) state.sites[idx] = result.site;
      else await loadSites();
      renderSitesTable();
      renderSitesDetail();
      await showModal({
        title: 'Forward updated',
        confirmLabel: 'OK',
        bodyHtml: `<p>Now forwarding to <code>${esc(formatDisplayPhone(result.forward?.forwardTo || s.renter.phone))}</code>.</p>`,
      });
    } catch (error) {
      await showModal({
        title: 'Forward failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });

  document.getElementById('sites-view-calls')?.addEventListener('click', () => {
    if (!(s.phoneTracking?.provider === 'twilio' && s.phoneTracking?.e164)) return;
    state.phone.selectedSiteId = s.id;
    state.phone.selectedCallId = null;
    setView('phone');
  });

  document.getElementById('sites-edit-form')?.addEventListener('submit', async (e) => {
    e.preventDefault();
    const fd = new FormData(e.target);
    const patch = {
      status: fd.get('status'),
      targetRentUsd: fd.get('targetRentUsd'),
      actualRentUsd: fd.get('actualRentUsd'),
      paymentMethod: fd.get('paymentMethod') || null,
      paymentMethodNotes: fd.get('paymentMethodNotes'),
      billingCycle: fd.get('billingCycle'),
      contractStart: fd.get('contractStart') || null,
      contractEnd: fd.get('contractEnd') || null,
      nextInvoiceAt: fd.get('nextInvoiceAt') || null,
      notes: fd.get('notes'),
      renter: {
        businessName: fd.get('renterBusinessName'),
        contactName: fd.get('renterContactName'),
        email: fd.get('renterEmail'),
        phone: phoneToE164(fd.get('renterPhone')),
        notes: fd.get('renterNotes'),
      },
    };
    try {
      const result = await api(`/api/sites/${encodeURIComponent(s.id)}`, {
        method: 'PATCH',
        body: JSON.stringify(patch),
      });
      const idx = state.sites.findIndex((x) => x.id === s.id);
      if (idx >= 0) state.sites[idx] = result.site;
      else await loadSites();
      renderSitesTable();
      renderSitesDetail();
    } catch (error) {
      await showModal({
        title: 'Save failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });

  document.getElementById('sites-delete-btn')?.addEventListener('click', async () => {
    const label = s.domain || s.candidateId || s.id;
    const hasTwilio = Boolean(
      s.phoneTracking?.provider === 'twilio' && (s.phoneTracking?.e164 || s.phoneTracking?.twilioSid),
    );
    const layer1 = await showModal({
      title: 'Remove from Launched?',
      confirmLabel: 'Continue',
      danger: true,
      bodyHtml: `<p>You are about to remove <strong>${esc(label)}</strong> from the Launched table.</p>
        <ul>
          <li>Removes this listing from the Sites registry only.</li>
          <li>Does <strong>not</strong> delete the Research candidate, site-config, or the live website.</li>
          <li>Metrics history for this site id may remain on disk (orphaned).</li>
          ${
            hasTwilio
              ? `<li>Twilio DID <code>${esc(formatDisplayPhone(s.phoneTracking.e164 || s.phoneTracking.twilioSid))}</code> is <strong>not</strong> released by this action.</li>`
              : ''
          }
        </ul>
        <p class="muted small">Next step asks you to type <code>REMOVE</code> to confirm.</p>`,
    });
    if (!layer1) return;

    const layer2 = await showModal({
      title: 'Type to confirm removal',
      confirmLabel: 'Remove permanently',
      danger: true,
      requireTypedConfirm: 'REMOVE',
      bodyHtml: `<p>Confirm removal of <strong>${esc(label)}</strong> from Launched.</p>
        <p class="muted small">This cannot be undone from the UI (you can re-add the candidate later).</p>`,
    });
    if (!layer2) return;

    try {
      await api(`/api/sites/${encodeURIComponent(s.id)}`, { method: 'DELETE' });
      state.selectedSiteId = null;
      await loadSites();
    } catch (error) {
      await showModal({
        title: 'Remove failed',
        confirmLabel: 'OK',
        hideCancel: true,
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });
  applyGscMetricsButtonState();
}

function phoneDigits(value) {
  return String(value || '').replace(/\D/g, '');
}

function formatDisplayPhone(value) {
  const trimmed = String(value ?? '').trim();
  if (!trimmed || trimmed === '—' || /X/i.test(trimmed)) return trimmed;
  const digits = phoneDigits(trimmed);
  let national = '';
  if (digits.length === 11 && digits.startsWith('1')) national = digits.slice(1);
  else if (digits.length === 10) national = digits;
  else return trimmed;
  return `+1 ${national.slice(0, 3)}-${national.slice(3, 6)}-${national.slice(6)}`;
}

function formatNationalPhoneInput(value) {
  const digits = phoneDigits(value);
  const national = digits.length === 11 && digits.startsWith('1') ? digits.slice(1, 11) : digits.slice(0, 10);
  if (national.length <= 3) return national;
  if (national.length <= 6) return `${national.slice(0, 3)}-${national.slice(3)}`;
  return `${national.slice(0, 3)}-${national.slice(3, 6)}-${national.slice(6, 10)}`;
}

function phoneToE164(value) {
  const raw = String(value ?? '').trim();
  if (!raw || /X/i.test(raw)) return raw;
  const digits = phoneDigits(raw);
  if (digits.length === 11 && digits.startsWith('1')) return `+${digits}`;
  if (digits.length === 10) return `+1${digits}`;
  if (/^\+[1-9]\d{7,14}$/.test(raw)) return raw;
  return raw;
}

function formatPhonesInText(value) {
  return String(value ?? '').replace(/\+1\d{10}/g, (match) => formatDisplayPhone(match));
}

function formatPhoneDuration(sec) {
  const n = Math.max(0, Number(sec) || 0);
  const m = Math.floor(n / 60);
  const s = n % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}

function formatPhoneWhen(iso) {
  if (!iso) return '—';
  try {
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return String(iso).slice(0, 16);
    return d.toLocaleString(undefined, {
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
    });
  } catch {
    return String(iso).slice(0, 16);
  }
}

function phoneVoicemailSummaryIsEmpty(summary) {
  return /^no message was left\.?$/i.test(String(summary || '').trim());
}

function phoneAnsweredLabel(call) {
  if (call?.kind === 'voicemail') {
    const summary = String(call.summary || '').trim();
    if (!summary) return { text: 'Voicemail', cls: 'voicemail' };
    if (phoneVoicemailSummaryIsEmpty(summary)) return { text: 'Empty', cls: 'voicemail-empty' };
    return { text: 'Message', cls: 'voicemail-message' };
  }
  if (call?.answered === true) return { text: 'Answered', cls: 'answered' };
  if (call?.answered === false) return { text: 'Missed', cls: 'missed' };
  const st = String(call?.status || '').toLowerCase();
  if (['completed', 'answered', 'in-progress'].includes(st)) {
    return { text: 'Answered', cls: 'answered' };
  }
  if (['no-answer', 'busy', 'failed', 'canceled', 'cancelled'].includes(st)) {
    return { text: 'Missed', cls: 'missed' };
  }
  return { text: st || 'Unknown', cls: '' };
}

function photoLibStoredNiche() {
  try {
    return String(localStorage.getItem('ops.photoNiche') || '').trim();
  } catch {
    return '';
  }
}

function photoLibStoreNiche(niche) {
  try {
    if (niche) localStorage.setItem('ops.photoNiche', niche);
  } catch {
    /* ignore */
  }
}

function photoLibCurrent() {
  return state.photoLib || {};
}

function photoLibFileDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ''));
    reader.onerror = () => reject(new Error('Could not read file'));
    reader.readAsDataURL(file);
  });
}

function photoLibMasterLabel(g) {
  if (!g) return 'Niche master';
  if (g.kind === 'master') return g.name || `${g.niche || 'Niche'} master`;
  return g.name || g.id;
}

