function discoverySourceDot(sourceId) {
  const src = DISCOVERY_SOURCES[sourceId];
  if (!src) return '';
  return `<span class="src-dot src-${esc(src.id)}" data-tip="${esc(src.tip)}" aria-label="${esc(
    src.label,
  )}"></span>`;
}

function renderSourceLegend(elId, { exclude = [] } = {}) {
  const el = document.getElementById(elId);
  if (!el) return;
  const skip = new Set(exclude);
  el.innerHTML = Object.values(DISCOVERY_SOURCES)
    .filter((s) => !skip.has(s.id))
    .map(
      (s) =>
        `<span class="src-legend-item" data-tip="${esc(s.tip)}"><span class="src-dot src-${esc(
          s.id,
        )}"></span>${esc(s.label)}</span>`,
    )
    .join('');
}

function renderDiscoverySourceLegend() {
  renderSourceLegend('discovery-source-legend');
  renderSourceLegend('candidate-source-legend');
}

function normalizeMapPackFilterValue(raw) {
  const s = String(raw ?? '').trim().toLowerCase();
  if (!s) return '';
  if (['yes', 'y', 'true', '1'].includes(s)) return 'yes';
  if (['no', 'n', 'false', '0'].includes(s)) return 'no';
  return s;
}

function discoveryRowMatchesFilters(row) {
  const f = state.discoveryFilters;
  const text = String(f.text || '').trim().toLowerCase();
  if (text) {
    const hay = `${row.Niche || ''} ${row.City || ''} ${row.State || ''}`.toLowerCase();
    if (!hay.includes(text)) return false;
  }
  if (f.human === '__empty') {
    if (String(row.human_decision || '').trim()) return false;
  } else if (f.human && String(row.human_decision || '') !== f.human) {
    return false;
  }
  if (f.rec && String(row.recommended_decision || '') !== f.rec) return false;
  if (f.mapPack === '__empty') {
    if (String(row['Map Pack'] || '').trim()) return false;
  } else if (f.mapPack) {
    const want = normalizeMapPackFilterValue(f.mapPack);
    const got = normalizeMapPackFilterValue(row['Map Pack']);
    if (want !== got) return false;
  }
  if (f.role) {
    const want = String(f.role).toLowerCase();
    const got = String(row.shotgun_role || '').toLowerCase();
    const aliases = {
      hub: ['hub', 'main'],
      member: ['member', 'city', 'wave1', 'wave2', 'wave3', 'wave4', 'wave5', 'wave6', 'wave7', 'wave8', 'wave9', 'wave10'],
      city: ['member', 'city', 'wave1', 'wave2', 'wave3', 'wave4', 'wave5', 'wave6', 'wave7', 'wave8', 'wave9', 'wave10'],
    };
    const ok = aliases[want] ? aliases[want].includes(got) : got === want;
    if (!ok) return false;
  }
  return true;
}

function parseSuggestedSuburbsList(raw) {
  return String(raw || '')
    .split(/;/)
    .map((s) => s.trim())
    .filter(Boolean);
}

function parseDiscoverySortValue(row, key) {
  if (key === 'Population') {
    const n = Number(String(row.Population || '').replace(/,/g, ''));
    return Number.isFinite(n) ? n : -1;
  }
  if (key === 'Organic Home Page') {
    const n = Number(String(row['Organic Home Page'] || '').replace(/[^0-9.-]/g, ''));
    return Number.isFinite(n) ? n : -1;
  }
  if (key === 'Organic Sub Page') {
    const n = Number(String(row['Organic Sub Page'] || '').replace(/[^0-9.-]/g, ''));
    return Number.isFinite(n) ? n : -1;
  }
  if (key === 'suggested_suburbs') {
    const raw = row.suggested_suburbs;
    if (raw == null || String(raw).trim() === '') return -1;
    return parseSuggestedSuburbsList(raw).length;
  }
  return String(row[key] ?? '').toLowerCase();
}

function getDiscoveryViewRows() {
  const indexed = state.discoveryRows.map((row, index) => ({ row, index }));
  let list = indexed.filter(({ row }) => discoveryRowMatchesFilters(row));
  const { key, dir } = state.discoverySort;
  if (key) {
    list = [...list].sort((a, b) => {
      const av = parseDiscoverySortValue(a.row, key);
      const bv = parseDiscoverySortValue(b.row, key);
      if (av < bv) return -1 * dir;
      if (av > bv) return 1 * dir;
      return 0;
    });
  }
  return list;
}

function syncDiscoveryFilterInputs() {
  const bar = document.getElementById('discovery-table-filters');
  if (!bar) return;
  if (!state.discoveryRows.length || (discoveryBatchIsShotgun() && shotgunSurfaceIsHub())) {
    bar.classList.add('hidden');
    return;
  }
  bar.classList.remove('hidden');
  const count = document.getElementById('discovery-filter-count');
  if (count) {
    const n = getDiscoveryViewRows().length;
    const selected = state.discoverySelected?.size || 0;
    count.textContent =
      selected > 0
        ? `Showing ${n} / ${state.discoveryRows.length} · ${selected} selected`
        : `Showing ${n} / ${state.discoveryRows.length}`;
  }
  syncDiscoveryBulkHumanUi();
}

/** Show bulk Human select only when 2+ Discovery rows are selected. */
function syncDiscoveryBulkHumanUi() {
  const wrap = document.getElementById('discovery-bulk-human-wrap');
  if (!wrap) return;
  const show = (state.discoverySelected?.size || 0) > 1;
  wrap.classList.toggle('hidden', !show);
  wrap.hidden = !show;
  if (!show) {
    const sel = document.getElementById('discovery-bulk-human');
    if (sel) sel.value = '';
  }
}

async function persistDiscoveryDecisions(updates) {
  if (!state.discoveryBatchId || !updates.length) return null;
  const result = await api(
    `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/decisions`,
    { method: 'POST', body: JSON.stringify({ updates }) },
  );
  state.discoveryRows = result.rows;
  notifyCandidatesChanged({ type: 'discovery', batchId: state.discoveryBatchId });
  return result;
}

function discoveryDecisionUpdateFromDom(idx) {
  const row = state.discoveryRows[idx];
  if (!row) return null;
  const decisionEl = document.querySelector(
    `select[data-idx="${idx}"][data-field="human_decision"]`,
  );
  const notesEl = document.querySelector(
    `input[data-idx="${idx}"][data-field="decision_notes"]`,
  );
  return {
    index: idx,
    human_decision: decisionEl ? decisionEl.value : row.human_decision || '',
    decision_notes: notesEl ? notesEl.value : row.decision_notes || '',
  };
}

async function persistDiscoveryRowFromDom(idx) {
  const update = discoveryDecisionUpdateFromDom(idx);
  if (!update || !state.discoveryBatchId) return null;
  try {
    const result = await persistDiscoveryDecisions([update]);
    updateDiscoveryStepChecks(
      state.discoveryBatches.find((b) => b.id === state.discoveryBatchId) || {
        id: state.discoveryBatchId,
      },
      state.discoveryRows,
    );
    updateDiscoveryProcessControls();
    return result;
  } catch (error) {
    await showModal({
      title: 'Save failed',
      confirmLabel: 'OK',
      bodyHtml: `<p>${esc(error.message)}</p>`,
    });
    return null;
  }
}

const discoveryNotesSaveTimers = new Map();

function scheduleDiscoveryNotesAutosave(idx) {
  const prev = discoveryNotesSaveTimers.get(idx);
  if (prev) clearTimeout(prev);
  discoveryNotesSaveTimers.set(
    idx,
    setTimeout(() => {
      discoveryNotesSaveTimers.delete(idx);
      void persistDiscoveryRowFromDom(idx);
    }, 400),
  );
}

function flushDiscoveryNotesAutosave(idx) {
  const prev = discoveryNotesSaveTimers.get(idx);
  if (prev) {
    clearTimeout(prev);
    discoveryNotesSaveTimers.delete(idx);
  }
  return persistDiscoveryRowFromDom(idx);
}

async function reopenDiscoveryIndices(indices) {
  if (!state.discoveryBatchId || !indices?.length) return;
  try {
    const result = await api(
      `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/reopen`,
      {
        method: 'POST',
        body: JSON.stringify({ indices }),
      },
    );
    state.discoveryRows = result.rows;
    await loadDiscoveryBatches();
    renderDiscoveryTable();
    updateDiscoveryStepChecks(
      state.discoveryBatches.find((b) => b.id === state.discoveryBatchId) || {
        id: state.discoveryBatchId,
      },
      state.discoveryRows,
    );
    showToast(
      `Reopened ${result.reopened?.length || 0} row(s). Change Decision if needed, then Process batch.`,
    );
  } catch (error) {
    await showModal({
      title: 'Reopen failed',
      confirmLabel: 'OK',
      bodyHtml: `<p>${esc(error.message)}</p>`,
    });
  }
}

async function acceptDiscoveryIndices(indices) {
  const updates = [];
  for (const idx of indices) {
    const row = state.discoveryRows[idx];
    if (!row?.recommended_decision) continue;
    if (isDiscoveryRowProcessed(row)) continue;
    updates.push({
      index: idx,
      human_decision: row.recommended_decision,
      decision_notes: row.decision_notes || row.recommended_reason || '',
    });
  }
  if (!updates.length) {
    await showModal({
      title: 'Nothing to accept',
      confirmLabel: 'OK',
      bodyHtml: '<p>No recommended decisions on the selected rows.</p>',
    });
    return;
  }
  await persistDiscoveryDecisions(updates);
  renderDiscoveryTable();
  updateDiscoveryStepChecks(
    { id: state.discoveryBatchId, ...(state.discoveryBatches.find((b) => b.id === state.discoveryBatchId) || {}) },
    state.discoveryRows,
  );
}

function discoveryKnownRowKey(row) {
  return [row?.niche, row?.city, row?.state]
    .map((v) => String(v || '').trim().toLowerCase())
    .join('|');
}

function syncDiscoveryKnownChrome() {
  const known = Boolean(state.discoveryKnownMode);
  document.getElementById('discovery-known-chrome')?.classList.toggle('hidden', !known);
  document.getElementById('discovery-batch-chrome')?.classList.toggle('hidden', known);
  const mapHost = document.getElementById('discovery-map-canvas');
  if (known && mapHost) mapHost.classList.add('hidden');
  const removeBtn = document.getElementById('discovery-known-remove');
  if (removeBtn) removeBtn.disabled = state.discoveryKnownSelected.size === 0;
}

async function loadDiscoveryKnownList() {
  const data = await api('/api/discovery/known');
  state.discoveryKnownRows = Array.isArray(data.rows) ? data.rows : [];
  state.discoveryKnownPrunePreview = data.prunePreview || null;
  state.discoveryKnownSelected = new Set();
  state.discoveryKnownCheckAnchor = null;
  const sub = document.getElementById('discovery-known-sub');
  if (sub) {
    const n = state.discoveryKnownRows.length;
    const cand = state.discoveryKnownRows.filter((r) => r.source === 'candidate').length;
    const tracked = n - cand;
    sub.textContent = `${n} pairs · ${cand} Candidate · ${tracked} Tracked`;
  }
}

async function enterDiscoveryKnownMode() {
  state.discoveryKnownMode = true;
  syncDiscoveryKnownChrome();
  await loadDiscoveryKnownList();
  renderDiscoveryTable();
}

function exitDiscoveryKnownMode() {
  state.discoveryKnownMode = false;
  state.discoveryKnownSelected = new Set();
  state.discoveryKnownCheckAnchor = null;
  syncDiscoveryKnownChrome();
  renderDiscoveryTable();
}

function renderDiscoveryKnownTable() {
  const thead = document.querySelector('#discovery-table thead');
  const tbody = document.querySelector('#discovery-table tbody');
  if (!thead || !tbody) return;
  syncDiscoveryKnownChrome();
  thead.innerHTML = `<tr>
    <th data-tip="Select"><input type="checkbox" id="discovery-known-select-all" /></th>
    <th>Niche</th>
    <th>City</th>
    <th>State</th>
    <th>Decision</th>
    <th>Source</th>
  </tr>`;
  const legend = document.getElementById('discovery-source-legend');
  if (legend) legend.innerHTML = '';

  const rows = state.discoveryKnownRows || [];
  if (!rows.length) {
    tbody.innerHTML =
      '<tr><td colspan="6" class="muted">No do-not-repropose pairs — Generate Pack will allow any market that fits filters.</td></tr>';
    syncHeaderSelectAll(document.getElementById('discovery-known-select-all'), {
      selectedCount: 0,
      totalCount: 0,
    });
    const removeBtn = document.getElementById('discovery-known-remove');
    if (removeBtn) removeBtn.disabled = true;
    return;
  }

  tbody.innerHTML = rows
    .map((row) => {
      const key = discoveryKnownRowKey(row);
      const checked = state.discoveryKnownSelected.has(key) ? 'checked' : '';
      const sourceLabel = row.source === 'tracked' ? 'Tracked' : 'Candidate';
      return `<tr data-known-key="${esc(key)}">
        <td><input type="checkbox" class="disc-known-check" data-known-key="${esc(key)}" ${checked} /></td>
        <td>${esc(row.niche || '')}</td>
        <td>${esc(row.city || '')}</td>
        <td>${esc(row.state || '')}</td>
        <td>${esc(row.decision || '—')}</td>
        <td class="muted">${esc(sourceLabel)}${
          row.candidateId ? ` · <span class="cell-text">${esc(row.candidateId)}</span>` : ''
        }</td>
      </tr>`;
    })
    .join('');

  syncHeaderSelectAll(document.getElementById('discovery-known-select-all'), {
    selectedCount: rows.filter((r) => state.discoveryKnownSelected.has(discoveryKnownRowKey(r)))
      .length,
    totalCount: rows.length,
  });
  const removeBtn = document.getElementById('discovery-known-remove');
  if (removeBtn) removeBtn.disabled = state.discoveryKnownSelected.size === 0;

  document.getElementById('discovery-known-select-all')?.addEventListener('change', (e) => {
    const on = e.target.checked;
    state.discoveryKnownSelected = new Set();
    if (on) {
      for (const r of rows) state.discoveryKnownSelected.add(discoveryKnownRowKey(r));
    }
    tbody.querySelectorAll('.disc-known-check').forEach((box) => {
      box.checked = on;
    });
    if (removeBtn) removeBtn.disabled = state.discoveryKnownSelected.size === 0;
  });

  tbody.querySelectorAll('.disc-known-check').forEach((cb) => {
    const applyKnownShiftRange = (event) => {
      const key = cb.dataset.knownKey;
      const ranged = applyShiftRangeCheckboxClick(event, {
        visibleKeys: rows.map((r) => discoveryKnownRowKey(r)),
        clickedKey: key,
        anchorKey: state.discoveryKnownCheckAnchor,
        setAnchor: (k) => {
          state.discoveryKnownCheckAnchor = k;
        },
        setSelected: (k, on) => {
          if (on) state.discoveryKnownSelected.add(k);
          else state.discoveryKnownSelected.delete(k);
        },
      });
      if (!ranged) return false;
      tbody.querySelectorAll('.disc-known-check').forEach((box) => {
        box.checked = state.discoveryKnownSelected.has(box.dataset.knownKey);
      });
      queueMicrotask(() => {
        cb.checked = state.discoveryKnownSelected.has(key);
      });
      syncHeaderSelectAll(document.getElementById('discovery-known-select-all'), {
        selectedCount: state.discoveryKnownSelected.size,
        totalCount: rows.length,
      });
      if (removeBtn) removeBtn.disabled = state.discoveryKnownSelected.size === 0;
      return true;
    };
    cb.addEventListener('pointerdown', (event) => {
      if (!event.shiftKey || state.discoveryKnownCheckAnchor == null) return;
      blockShiftRangePointerDown(event, state.discoveryKnownCheckAnchor);
      applyKnownShiftRange(event);
    });
    cb.addEventListener('click', (event) => {
      const key = cb.dataset.knownKey;
      if (applyKnownShiftRange(event)) return;
      if (consumeShiftRangeChange(cb, key)) {
        cb.checked = state.discoveryKnownSelected.has(key);
        return;
      }
      state.discoveryKnownCheckAnchor = key;
      if (cb.checked) state.discoveryKnownSelected.add(key);
      else state.discoveryKnownSelected.delete(key);
      syncHeaderSelectAll(document.getElementById('discovery-known-select-all'), {
        selectedCount: state.discoveryKnownSelected.size,
        totalCount: rows.length,
      });
      if (removeBtn) removeBtn.disabled = state.discoveryKnownSelected.size === 0;
    });
  });
}

function renderDiscoveryTable() {
  if (state.discoveryKnownMode) {
    renderDiscoveryKnownTable();
    return;
  }
  syncDiscoveryKnownChrome();
  const thead = document.querySelector('#discovery-table thead');
  const tbody = document.querySelector('#discovery-table tbody');
  const sort = state.discoverySort;
  const cols = DISCOVERY_TABLE_COLS;
  thead.innerHTML = `<tr>${cols.map((c) => {
    const tip = c.tip || c.label || '';
    if (c.key === '_select') {
      return `<th data-tip="${esc(tip)}"><input type="checkbox" id="discovery-select-all" data-tip="${esc(tip)}" /></th>`;
    }
    const mark =
      sort.key === c.key ? (sort.dir === 1 ? ' ▲' : ' ▼') : '';
    const cls = [c.sortable ? 'sortable' : '', c.cellClass || ''].filter(Boolean).join(' ');
    const label = c.label || (c.key === '_accept' ? 'Accept' : '');
    const srcTip = c.source && DISCOVERY_SOURCES[c.source] ? DISCOVERY_SOURCES[c.source].tip : '';
    const fullTip = [tip, srcTip].filter(Boolean).join(' · ');
    return `<th class="${cls}" data-sort="${esc(c.key)}" data-tip="${esc(fullTip)}"><span class="th-label">${discoverySourceDot(
      c.source,
    )}${esc(label)}</span>${mark}</th>`;
  }).join('')}</tr>`;
  renderDiscoverySourceLegend();

  const acceptSel = document.getElementById('discovery-accept-selected');
  const acceptAll = document.getElementById('discovery-accept-all');

  if (!state.discoveryRows.length) {
    tbody.innerHTML = `<tr><td colspan="${cols.length}" class="muted">Import a filled CSV or select a batch.</td></tr>`;
    updateDiscoveryProcessControls();
    syncHeaderSelectAll(document.getElementById('discovery-select-all'), {
      selectedCount: 0,
      totalCount: 0,
    });
    if (acceptSel) acceptSel.disabled = true;
    if (acceptAll) acceptAll.disabled = true;
    syncDiscoveryFilterInputs();
    return;
  }

  const view = getDiscoveryViewRows();
  tbody.innerHTML = view
    .map(({ row, index: idx }) => {
      const checked = state.discoverySelected.has(idx) ? 'checked' : '';
      const processStatus = discoveryRowProcessStatus(row);
      const processed = Boolean(processStatus);
      const tracked = processStatus === 'tracked';
      const ignored = processStatus === 'ignored';
      const cells = cols.map((col) => {
        const tdClass = col.cellClass ? ` class="${esc(col.cellClass)}"` : '';
        if (col.key === '_select') {
          return `<td${tdClass}><input type="checkbox" data-disc-idx="${idx}" class="disc-row-check" ${checked} /></td>`;
        }
        if (col.key === '_accept') {
          if (tracked || ignored) {
            return `<td${tdClass}><button type="button" class="btn btn-sm" data-reopen-idx="${idx}" data-tip="${
              ignored
                ? 'Unlock this row so you can decide again.'
                : 'Unlock this row so you can decide again.'
            }">Reopen</button></td>`;
          }
          if (processed) {
            return `<td${tdClass}><span class="metric metric-good" data-tip="In Candidates as ${esc(
              row.candidateId || '',
            )}">✓ Candidates</span></td>`;
          }
          const disabled = !row.recommended_decision ? 'disabled' : '';
          return `<td${tdClass}><button type="button" class="btn btn-accept" data-accept-idx="${idx}" data-tip="Use the suggestion as the decision." ${disabled}>Accept</button></td>`;
        }
        if (col.key === 'recommended_decision') {
          const rec = row.recommended_decision || '—';
          const reason = row.recommended_reason || '';
          const cls = [col.cellClass, 'rec-cell'].filter(Boolean).join(' ');
          return `<td class="${esc(cls)}" data-tip="${esc(reason)}"><strong>${esc(rec)}</strong></td>`;
        }
        if (col.key === 'human_decision') {
          const v = row.human_decision || '';
          if (tracked) {
            return `<td${tdClass}><span class="metric disc-tracked-mark" data-tip="Saved as tracked, not a candidate. Reopen to change.">○ Tracked · ${esc(v || '—')}</span></td>`;
          }
          if (ignored) {
            return `<td${tdClass}><span class="metric disc-ignored-mark" data-tip="Skipped for this batch. Reopen to change.">○ Ignored · ${esc(
              v || 'ignore',
            )}</span></td>`;
          }
          if (processed) {
            return `<td${tdClass}><span class="metric metric-good" data-tip="In Candidates as ${esc(
              row.candidateId || '',
            )}">✓ ${esc(v || '—')}</span></td>`;
          }
          return `<td${tdClass}><select data-idx="${idx}" data-field="human_decision">${DISCOVERY_DECISION_OPTS.map(
            (o) => `<option value="${o}" ${v === o ? 'selected' : ''}>${o || '—'}</option>`,
          ).join('')}</select></td>`;
        }
        if (col.key === 'decision_notes') {
          const notes = row.decision_notes || '';
          if (processed) {
            return `<td${tdClass}><span class="cell-text muted">${esc(
              notes || '—',
            )}</span></td>`;
          }
          return `<td${tdClass}><input data-idx="${idx}" data-field="decision_notes" value="${esc(
            notes,
          )}" /></td>`;
        }
        if (col.key === 'candidateId') {
          if (tracked) {
            return `<td${tdClass} data-tip="Tracked, not a candidate."><span class="cell-text muted">tracked</span></td>`;
          }
          if (ignored) {
            return `<td${tdClass} data-tip="Skipped for this batch."><span class="cell-text muted">ignored</span></td>`;
          }
          const val = row.candidateId || '';
          return `<td${tdClass}><span class="cell-text">${esc(val || '—')}</span></td>`;
        }
        if (col.key === 'shotgun_role') {
          const role = String(row.shotgun_role || '').toLowerCase();
          const label = shotgunRoleLabel(role) || '—';
          return `<td${tdClass}><span class="sg-role-${esc(role || 'none')}">${esc(label)}</span></td>`;
        }
        if (col.key === 'suggested_suburbs') {
          const raw = row.suggested_suburbs;
          if (raw == null || String(raw).trim() === '') {
            return `<td${tdClass}><span class="cell-text muted">—</span></td>`;
          }
          const cities = parseSuggestedSuburbsList(raw);
          const tip = cities.length ? cities.join('\n') : '';
          return `<td${tdClass}${tip ? ` data-tip="${esc(tip)}"` : ''}><span class="cell-text">${esc(
            String(cities.length),
          )}</span></td>`;
        }
        const val = row[col.key] ?? '';
        return `<td${tdClass}><span class="cell-text">${esc(val)}</span></td>`;
      });
      const rowClass = [
        processed ? 'disc-row-processed' : '',
        tracked ? 'disc-row-tracked' : '',
        ignored ? 'disc-row-ignored' : '',
      ]
        .filter(Boolean)
        .join(' ');
      return `<tr data-row-idx="${idx}" class="${rowClass}">${cells.join('')}</tr>`;
    })
    .join('');

  updateDiscoveryProcessControls();
  const reopenSel = document.getElementById('discovery-reopen-selected');
  if (reopenSel) {
    const canReopen = [...state.discoverySelected].some((idx) =>
      isDiscoveryRowProcessed(state.discoveryRows[idx]),
    );
    reopenSel.disabled = !canReopen;
  }
  if (acceptSel) acceptSel.disabled = state.discoverySelected.size === 0;
  if (acceptAll) {
    acceptAll.disabled = !view.some(
      ({ row }) => row.recommended_decision && !isDiscoveryRowProcessed(row),
    );
  }
  syncDiscoveryFilterInputs();

  const discSelectAll = document.getElementById('discovery-select-all');
  const discSelectedVisible = view.filter(({ index }) =>
    state.discoverySelected.has(index),
  ).length;
  syncHeaderSelectAll(discSelectAll, {
    selectedCount: discSelectedVisible,
    totalCount: view.length,
  });

  discSelectAll?.addEventListener('change', (e) => {
    const on = e.target.checked;
    for (const { index } of view) {
      if (on) state.discoverySelected.add(index);
      else state.discoverySelected.delete(index);
    }
    renderDiscoveryTable();
  });
  thead.querySelectorAll('th.sortable').forEach((th) => {
    th.addEventListener('click', () => {
      const key = th.dataset.sort;
      if (state.discoverySort.key === key) state.discoverySort.dir *= -1;
      else state.discoverySort = { key, dir: 1 };
      persistUiRestore();
      renderDiscoveryTable();
    });
  });
  tbody.querySelectorAll('.disc-row-check').forEach((cb) => {
    const syncDiscSelectionUi = () => {
      syncHeaderSelectAll(document.getElementById('discovery-select-all'), {
        selectedCount: view.filter(({ index }) => state.discoverySelected.has(index))
          .length,
        totalCount: view.length,
      });
      if (acceptSel) acceptSel.disabled = state.discoverySelected.size === 0;
      const reopenBtn = document.getElementById('discovery-reopen-selected');
      if (reopenBtn) {
        reopenBtn.disabled = ![...state.discoverySelected].some((i) =>
          isDiscoveryRowProcessed(state.discoveryRows[i]),
        );
      }
      syncDiscoveryFilterInputs();
    };
    const applyDiscShiftRange = (e) => {
      const idx = Number(cb.dataset.discIdx);
      const ranged = applyShiftRangeCheckboxClick(e, {
        visibleKeys: view.map(({ index }) => index),
        clickedKey: idx,
        anchorKey: state.discoveryCheckAnchor,
        setAnchor: (key) => {
          state.discoveryCheckAnchor = key;
        },
        setSelected: (key, on) => {
          if (on) state.discoverySelected.add(key);
          else state.discoverySelected.delete(key);
        },
      });
      if (!ranged) return false;
      tbody.querySelectorAll('.disc-row-check').forEach((box) => {
        const i = Number(box.dataset.discIdx);
        box.checked = state.discoverySelected.has(i);
      });
      syncDiscSelectionUi();
      return true;
    };
    cb.addEventListener('pointerdown', (e) => {
      if (!e.shiftKey || state.discoveryCheckAnchor == null) return;
      blockShiftRangePointerDown(e, state.discoveryCheckAnchor);
      applyDiscShiftRange(e);
    });
    cb.addEventListener('click', (e) => {
      applyDiscShiftRange(e);
    });
    cb.addEventListener('change', (e) => {
      const idx = Number(cb.dataset.discIdx);
      if (consumeShiftRangeChange(cb, idx)) {
        cb.checked = state.discoverySelected.has(idx);
        return;
      }
      state.discoveryCheckAnchor = idx;
      if (cb.checked) state.discoverySelected.add(idx);
      else state.discoverySelected.delete(idx);
      syncDiscSelectionUi();
    });
  });
  tbody.querySelectorAll('[data-accept-idx]').forEach((btn) => {
    btn.addEventListener('click', async () => {
      await acceptDiscoveryIndices([Number(btn.dataset.acceptIdx)]);
    });
  });
  tbody.querySelectorAll('[data-reopen-idx]').forEach((btn) => {
    btn.addEventListener('click', async () => {
      await reopenDiscoveryIndices([Number(btn.dataset.reopenIdx)]);
    });
  });
  enableTableColumnResize(document.getElementById('discovery-table'), {
    freezeCols: 4,
  });
}

async function selectDiscoveryBatch(id) {
  const data = await api(`/api/discovery/batches/${encodeURIComponent(id)}`);
  state.discoveryBatchId = data.batch.id;
  state.discoveryRows = data.rows || [];
  state.discoverySelected = new Set();
  state.discoveryCheckAnchor = null;
  document.getElementById('discovery-batch-title').textContent = data.batch.id;
  const stage = shortDiscoveryStage(data.batch.stage);
  const serp = data.batch.lastSerpProbe;
  document.getElementById('discovery-batch-sub').textContent = [
    stage,
    `${data.rows?.length || 0} rows`,
    Array.isArray(data.batch.filters?.states) && data.batch.filters.states.length
      ? data.batch.filters.states.join(', ')
      : data.batch.filters?.state || null,
    serp
      ? `SERP $${serp.costUsd ?? '?'} · MP ${serp.mapPackYes ?? '?'}/${serp.mapPackNo ?? '?'}`
      : null,
    data.batch.lastProcess
      ? `process ${data.batch.lastProcess.promoted?.length || 0} new, ${
          data.batch.lastProcess.tracked?.length || 0
        } tracked, ${data.batch.lastProcess.ignored?.length || 0} ignored, ${
          data.batch.lastProcess.skipped?.length || 0
        } skipped`
      : null,
  ]
    .filter(Boolean)
    .join(' · ');
  const batchSel = document.getElementById('discovery-batch-select');
  if (batchSel && batchSel.value !== data.batch.id) {
    batchSel.value = data.batch.id;
  }
  persistUiRestore();
  const logEl = document.getElementById('discovery-process-log');
  if (logEl) {
    const lp = data.batch.lastProcess;
    if (lp) {
      logEl.classList.remove('hidden');
      const linked = (lp.promoted || []).filter((p) => p.linkedExisting).length;
      logEl.innerHTML = `<p class="muted">Last process: ${esc(
        String(lp.promoted?.length || 0),
      )} new candidates${linked ? ` (${esc(String(linked))} already existed)` : ''}. ${esc(
        String(lp.tracked?.length || 0),
      )} tracked. ${esc(String(lp.ignored?.length || 0))} ignored. ${esc(
        String(lp.skipped?.length || 0),
      )} skipped.${
        (lp.pursueQueued?.length || 0) > 0
          ? ` Search volumes queued for ${esc(String(lp.pursueQueued.length))} pursue.`
          : ''
      }</p>`;
    } else {
      logEl.classList.add('hidden');
      logEl.innerHTML = '';
    }
  }
  if (
    state.discoveryRows.length &&
    state.discoveryRows.some((r) => !r.recommended_decision)
  ) {
    try {
      const rec = await api(
        `/api/discovery/batches/${encodeURIComponent(id)}/recommend`,
        { method: 'POST', body: '{}' },
      );
      state.discoveryRows = rec.rows;
    } catch {
      /* ignore */
    }
  }
  renderDiscoveryTable();
  updateDiscoveryStepChecks(data.batch, state.discoveryRows);
  if (data.batch?.filters?.packType && isClusterPackType(data.batch.filters.packType)) {
    state.discoveryPackType = 'cluster';
    syncDiscoveryPackTypeUi();
    const hasRows = (state.discoveryRows || []).length > 0;
    applyShotgunSurface(hasRows ? 'table' : 'hub');
    await loadShotgunWorkspace(data.batch.id);
    if (effectiveClaudeUiMode() === 'api') renderShotgunApiButtons();
    else renderShotgunPasteSteps();
    showDiscoverySidebarStep(hasRows ? 'enrich' : 'pack');
  } else {
    state.discoveryPackType = 'single';
    syncDiscoveryPackTypeUi();
    state.shotgunWorkspace = null;
    await renderShotgunWorkspace();
  }
  if (effectiveClaudeUiMode() === 'api') {
    syncDiscoveryApiRerunButton();
    syncGeneratePackOverlay(state.lightJobsSnap);
  }
  await loadDiscoveryBatches();
}

function discoveryBatchIsShotgun(batch = null) {
  const b =
    batch ||
    state.discoveryBatches.find((x) => x.id === state.discoveryBatchId) ||
    state.lastDiscoveryPack?.batch;
  return isClusterPackType(b?.filters?.packType || state.discoveryPackType);
}

function shotgunHasPackCities(ws = state.shotgunWorkspace) {
  return (ws?.draft?.members || []).some((m) => {
    const r = String(m.role || '').toLowerCase();
    if (r === 'hub' || r === 'main') return false;
    return shotgunIsCityRole(m.role, m) || memberClusterKey(m);
  });
}

function shotgunNewCityCount(ws = state.shotgunWorkspace) {
  const n = Number(ws?.summary?.newCount);
  if (Number.isFinite(n) && n >= 0) return n;
  return (ws?.draft?.members || []).filter((m) => {
    const r = String(m.role || '').toLowerCase();
    const member =
      r === 'hub' ||
      r === 'main' ||
      shotgunIsCityRole(m.role, m) ||
      memberClusterKey(m);
    return member && !m.candidateId;
  }).length;
}

function shotgunPackReady(ws = state.shotgunWorkspace) {
  if (!ws?.draft?.hub) return { ok: false, tip: 'Pick a hub first.' };
  if (!shotgunHasPackCities(ws)) return { ok: false, tip: 'Assign cities on the map first.' };
  if (shotgunNewCityCount(ws) < 1) {
    return { ok: false, tip: 'These cities are already in the list.' };
  }
  return { ok: true, tip: '' };
}

function discoveryLightSerpBusy() {
  const progress = document.getElementById('discovery-probe-progress');
  return Boolean(progress && !progress.classList.contains('hidden'));
}

function syncDiscoveryLightSerpButton() {
  const btn = document.getElementById('discovery-enrich-pack-btn');
  if (!btn) return;
  const hasRows = (state.discoveryRows || []).length > 0;
  btn.disabled = !hasRows || discoveryLightSerpBusy();
  setElementTip(
    btn,
    !hasRows
      ? discoveryBatchIsShotgun()
        ? 'Generate a pack from the selected hub first.'
        : 'Import a sheet or generate a pack first.'
      : 'Checks the selected rows, or the whole batch if none are selected.',
  );
}

async function startShotgunGeneratePackFromUi() {
  const ready = shotgunPackReady();
  if (!ready.ok) {
    await showModal({
      title: 'Cannot generate pack yet',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>${esc(ready.tip)}</p>`,
    });
    return;
  }
  if (effectiveClaudeUiMode() === 'api') {
    await startShotgunApiStep('shotgun-generate-pack');
    return;
  }
  renderShotgunPasteSteps();
  showDiscoverySidebarStep('claude');
  showToast('Copy the Generate pack prompt, then import Claude’s CSV.');
}

function syncReuseZoneFields() {
  const shotgun = isClusterPackType(state.discoveryPackType);
  const reuse = shotgun && Boolean(document.getElementById('discovery-reuse-zone')?.value);
  document.querySelectorAll('.discovery-zone-new-only').forEach((el) => {
    if (el.classList.contains('discovery-shotgun-only')) {
      el.classList.toggle('hidden', !shotgun || reuse);
    } else {
      el.classList.toggle('hidden', reuse);
    }
  });
  if (reuse) document.getElementById('discovery-map-controls')?.classList.add('hidden');
}

async function loadReuseZoneOptions() {
  const select = document.getElementById('discovery-reuse-zone');
  if (!select) return;
  const current = select.value;
  let clusters = [];
  try {
    const data = await api('/api/shotgun-clusters');
    clusters = Array.isArray(data?.clusters) ? data.clusters : [];
  } catch {
    clusters = [];
  }
  const rows = clusters
    .filter((c) => c?.id && c.hub?.city && c.hub?.state)
    .sort(
      (a, b) =>
        Number(a.sgNumber) - Number(b.sgNumber) ||
        String(a.niche || '').localeCompare(String(b.niche || '')),
    );
  const html = ['<option value="">New zone</option>'];
  for (const c of rows) {
    const label = [formatZnDisplay(c.sgNumber), c.hub.state, c.hub.city, c.niche]
      .filter(Boolean)
      .join(' · ');
    html.push(`<option value="${esc(c.id)}">${esc(label)}</option>`);
  }
  select.innerHTML = html.join('');
  if (current && rows.some((c) => c.id === current)) select.value = current;
  syncReuseZoneFields();
}

function setDiscoveryPackType(type) {
  state.discoveryPackType = isClusterPackType(type) ? 'cluster' : 'single';
  syncDiscoveryPackTypeUi();
  if (state.discoveryPackType === 'cluster') {
    loadReuseZoneOptions().catch(() => {});
  }
}

function syncDiscoveryPackTypeUi() {
  const shotgun = isClusterPackType(state.discoveryPackType);
  document.getElementById('discovery-pack-scout')?.classList.toggle('active', !shotgun);
  document.getElementById('discovery-pack-shotgun')?.classList.toggle('active', shotgun);
  document.querySelectorAll('.discovery-shotgun-only').forEach((el) => {
    el.classList.toggle('hidden', !shotgun);
  });
  document.querySelectorAll('.discovery-scout-only').forEach((el) => {
    el.classList.toggle('hidden', shotgun);
  });
  document.querySelectorAll('.discovery-pack-cities').forEach((input) => {
    input.placeholder = shotgun
      ? input.dataset.shotgunPlaceholder || 'Hub city (optional)'
      : input.dataset.scoutPlaceholder || 'Louisville, Lexington';
  });
  const roleFilter = document.getElementById('discovery-filter-role');
  if (roleFilter) roleFilter.classList.toggle('hidden', !shotgun && !discoveryBatchIsShotgun());
  const submit = document.querySelector('#discovery-form button[type="submit"]');
  if (submit) submit.textContent = shotgun ? 'Create Cluster pack' : 'Generate Discovery pack';
  syncReuseZoneFields();
}

async function loadShotgunWorkspace(batchId = state.discoveryBatchId) {
  if (!batchId || !discoveryBatchIsShotgun()) {
    state.shotgunWorkspace = null;
    await renderShotgunWorkspace();
    return null;
  }
  try {
    state.shotgunWorkspace = await api(`/api/discovery/batches/${encodeURIComponent(batchId)}/shotgun`);
  } catch {
    state.shotgunWorkspace = null;
  }
  await renderShotgunWorkspace();
  return state.shotgunWorkspace;
}

function shotgunPickerHubs(draft = {}, workspace = null) {
  if (Array.isArray(workspace?.claudeHubs) && workspace.claudeHubs.length) {
    return workspace.claudeHubs;
  }
  if ((draft.hubs || []).length) return draft.hubs;
  return [];
}

function shotgunCensusExtras(draft = {}, workspace = null) {
  if (Array.isArray(workspace?.censusExtras)) return workspace.censusExtras;
  const extras = [...(draft.viableHubs || [])];
  const seen = new Set(extras.map((h) => shotgunHubKey(h.city, h.state)));
  for (const h of draft.rejectedHubs || []) {
    if (!h?.hubInBand) continue;
    const k = shotgunHubKey(h.city, h.state);
    if (seen.has(k)) continue;
    seen.add(k);
    extras.push(h);
  }
  return extras;
}

function shotgunHubKey(city, state) {
  return `${String(city || '').trim().toLowerCase()}|${String(state || '').trim().toUpperCase()}`;
}

function formatShotgunPop(n) {
  const v = Number(n);
  if (!Number.isFinite(v) || v <= 0) return '—';
  return Math.round(v).toLocaleString();
}

function formatShotgunMiles(n) {
  const v = Number(n);
  if (!Number.isFinite(v)) return '—';
  return `${v} mi`;
}

function placeDiscoveryMapCanvas(target) {
  const canvas = document.getElementById('discovery-map-canvas');
  if (!canvas || !target) return canvas;
  if (canvas.parentElement !== target) target.appendChild(canvas);
  return canvas;
}

function resumeShotgunMapAfterView() {
  if (!shotgunMapMount || !shotgunSurfaceIsHub()) return;
  const slot = document.getElementById('discovery-shotgun-map-slot');
  if (slot) placeDiscoveryMapCanvas(slot);
  const canvas = document.getElementById('discovery-map-canvas');
  canvas?.classList.remove('hidden', 'shotgun-map-off');
  slot?.classList.remove('shotgun-map-off');
  requestAnimationFrame(() => {
    shotgunMapMount?.invalidateSize?.();
    setTimeout(() => shotgunMapMount?.invalidateSize?.(), 200);
  });
}

function shotgunMapExpandInnerHtml(expanded) {
  return expanded
    ? '<svg class="shotgun-map-expand-icon" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M8 3v3a2 2 0 0 1-2 2H3"/><path d="M21 8h-3a2 2 0 0 1-2-2V3"/><path d="M3 16h3a2 2 0 0 1 2 2v3"/><path d="M16 21v-3a2 2 0 0 1 2-2h3"/></svg>'
    : '<svg class="shotgun-map-expand-icon" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M8 3H5a2 2 0 0 0-2 2v3"/><path d="M16 3h3a2 2 0 0 1 2 2v3"/><path d="M8 21H5a2 2 0 0 1-2-2v-3"/><path d="M16 21h3a2 2 0 0 0 2-2v-3"/></svg>';
}

function discoverySidebarToggleInnerHtml(collapsed) {
  return collapsed
    ? '<svg class="discovery-sidebar-toggle-icon" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m9 18 6-6-6-6"/></svg>'
    : '<svg class="discovery-sidebar-toggle-icon" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m15 18-6-6 6-6"/></svg>';
}

function applyDiscoverySidebarCollapsed() {
  const on = Boolean(discoverySidebarCollapsed);
  document.getElementById('view-discovery')?.classList.toggle('discovery-sidebar-collapsed', on);
  const btn = document.getElementById('discovery-sidebar-toggle');
  if (btn) {
    btn.setAttribute('aria-expanded', on ? 'false' : 'true');
    btn.setAttribute('aria-label', on ? 'Expand sidebar' : 'Collapse sidebar');
    btn.innerHTML = discoverySidebarToggleInnerHtml(on);
    setElementTip(btn, on ? 'Expand sidebar' : 'Collapse sidebar');
  }
  requestAnimationFrame(() => {
    shotgunMapMount?.invalidateSize?.();
    setTimeout(() => shotgunMapMount?.invalidateSize?.(), 200);
  });
}

function applyShotgunMapExpanded() {
  const panel = document.querySelector('.discovery-table-panel');
  const hasHub = Boolean(panel?.classList.contains('shotgun-hub-on'));
  const on = Boolean(shotgunMapExpanded && hasHub);
  document.getElementById('view-discovery')?.classList.toggle('shotgun-map-expanded', on);
  const btn = document.getElementById('sg-map-expand');
  if (btn) {
    btn.setAttribute('aria-expanded', on ? 'true' : 'false');
    btn.setAttribute('aria-label', on ? 'Collapse map' : 'Expand map');
    btn.innerHTML = shotgunMapExpandInnerHtml(on);
    setElementTip(btn, on ? 'Collapse map' : 'Expand map');
  }
  requestAnimationFrame(() => {
    shotgunMapMount?.invalidateSize?.();
    setTimeout(() => shotgunMapMount?.invalidateSize?.(), 200);
  });
}

function shotgunSurfaceIsHub() {
  if (!discoveryBatchIsShotgun()) return false;
  if (!(state.discoveryRows || []).length) return true;
  return state.shotgunSurface !== 'table';
}

function applyShotgunSurface(surface) {
  const hasRows = (state.discoveryRows || []).length > 0;
  state.shotgunSurface = surface === 'table' && hasRows ? 'table' : 'hub';
}

function syncDiscoverySurfaceToggle() {
  const btn = document.getElementById('discovery-surface-toggle');
  if (!btn) return;
  const show = discoveryBatchIsShotgun() && (state.discoveryRows || []).length > 0;
  const onMap = shotgunSurfaceIsHub();
  btn.classList.toggle('hidden', !show);
  btn.hidden = !show;
  btn.textContent = onMap ? 'Table' : 'Map';
  setElementTip(
    btn,
    onMap ? 'Show the decision table' : 'Show the cluster map',
  );
}

function syncShotgunDiscoverySurfaces({ hasHub, hasPackRows }) {
  const wrap = document.querySelector('.discovery-table-wrap');
  const canvas = document.getElementById('discovery-map-canvas');
  const mapSlot = document.getElementById('discovery-shotgun-map-slot');
  const filters = document.getElementById('discovery-table-filters');
  const panel = document.querySelector('.discovery-table-panel');
  const shotgunPanel = document.getElementById('discovery-shotgun-panel');
  const shotgun = discoveryBatchIsShotgun();
  const showHub = shotgun && shotgunSurfaceIsHub();
  const showTable = Boolean(hasPackRows && (!shotgun || !showHub));
  const showHubMap = Boolean(showHub && hasHub);
  if (shotgunPanel) shotgunPanel.classList.toggle('hidden', !showHub);
  if (wrap) wrap.classList.toggle('hidden', !showTable);
  if (filters) filters.classList.toggle('hidden', !showTable);
  if (showHubMap && mapSlot) placeDiscoveryMapCanvas(mapSlot);
  else if (showHubMap && shotgunPanel) placeDiscoveryMapCanvas(shotgunPanel);
  if (canvas) {
    canvas.classList.toggle('shotgun-map-off', !showHubMap);
    canvas.classList.toggle('hidden', !showHubMap);
  }
  mapSlot?.classList.toggle('shotgun-map-off', !showHubMap);
  panel?.classList.toggle('shotgun-map-mode', showHubMap);
  panel?.classList.toggle('shotgun-hub-on', showHubMap);
  panel?.classList.remove('disc-map-mode');
  applyShotgunMapExpanded();
  renderDiscoveryUpNext();
  syncDiscoverySurfaceToggle();
  if (showHubMap) {
    requestAnimationFrame(() => {
      shotgunMapMount?.invalidateSize?.();
      setTimeout(() => shotgunMapMount?.invalidateSize?.(), 200);
    });
  }
}

function shotgunPreferredKeys(h) {
  const keys = new Set();
  const preferred = h.citiesPreferred?.length
    ? h.citiesPreferred
    : [...(h.wave1Preferred || []), ...(h.wave2Preferred || [])];
  for (const c of preferred) keys.add(shotgunHubKey(c.city, c.state));
  return keys;
}

function shotgunCityFocusHtml(city, state, canFocus, { clusterKey = 0, hub = false } = {}) {
  const label = `${esc(cityMapLabel(city, clusterKey, { hub }))}, ${esc(state)}`;
  if (!canFocus) return label;
  return `<button type="button" class="sg-focus-city" data-city="${esc(city)}" data-state="${esc(state)}">${label}</button>`;
}

function shotgunPackMembers(draft, hub) {
  const hubKey = hub?.city ? shotgunHubKey(hub.city, hub.state) : '';
  const list = [];
  for (const m of draft?.members || []) {
    const k = shotgunHubKey(m.city, m.state);
    if (hubKey && k === hubKey) continue;
    const role = String(m.role || '').toLowerCase();
    if (role === 'hub' || role === 'main') continue;
    if (!(shotgunIsCityRole(m.role, m) || memberClusterKey(m))) continue;
    list.push(m);
  }
  list.sort((a, b) => {
    const ac = memberClusterKey(a) || 0;
    const bc = memberClusterKey(b) || 0;
    const aRank = ac || 99;
    const bRank = bc || 99;
    if (aRank !== bRank) return aRank - bRank;
    const am = Number(a.miles);
    const bm = Number(b.miles);
    const aOk = Number.isFinite(am);
    const bOk = Number.isFinite(bm);
    if (aOk && bOk && am !== bm) return am - bm;
    if (aOk !== bOk) return aOk ? -1 : 1;
    return `${a.city || ''}`.localeCompare(`${b.city || ''}`);
  });
  return list;
}

function shotgunPreferredMembers(h) {
  if (h.citiesPreferred?.length) return h.citiesPreferred;
  return [...(h.wave1Preferred || []), ...(h.wave2Preferred || [])];
}

function renderShotgunMemberRows(cities, { canFocus = false, muted = false, showWhy = false } = {}) {
  const whyCell = showWhy ? '<td></td>' : '';
  return (cities || [])
    .map((c) => {
      const ck = memberClusterKey(c);
      const fill = muted ? '' : clusterColor(ck);
      const cityStyle = fill ? ` style="color:${fill};font-weight:700"` : '';
      return `<tr class="sg-member-row sg-wave-row${muted ? ' muted' : ''}">
        <td></td>
        <td colspan="2"${cityStyle}>${shotgunCityFocusHtml(c.city, c.state, canFocus, { clusterKey: ck })}</td>
        <td>${esc(formatShotgunPop(c.population))}</td>
        <td>${esc(formatShotgunMiles(c.miles))}</td>
        ${whyCell}
        <td></td>
      </tr>`;
    })
    .join('');
}

function renderShotgunHubRowsHtml(hubs, draft, { selectedKey = '', showWhy = false } = {}) {
  const colSpan = showWhy ? 7 : 6;
  return (hubs || [])
    .map((h) => {
      const key = shotgunHubKey(h.city, h.state);
      const selected = selectedKey && key === selectedKey;
      const expanded = shotgunExpandedHubs.has(key);
      const assignedCities = selected ? shotgunPackMembers(draft, h) : shotgunPreferredMembers(h);
      const hideKeys = new Set(
        selected
          ? assignedCities.map((c) => shotgunHubKey(c.city, c.state)).concat([key])
          : [...shotgunPreferredKeys(h)],
      );
      const leftover1 = (h.innerCities || h.wave1 || []).filter((c) => !hideKeys.has(shotgunHubKey(c.city, c.state)));
      const leftover2 = (h.outerCities || h.wave2 || []).filter((c) => !hideKeys.has(shotgunHubKey(c.city, c.state)));
      const leftoverCities = [...leftover1, ...leftover2];
      const clusterCities = assignedCities;
      const clusterPop =
        (Number(h.population) || 0) +
        clusterCities.reduce((sum, c) => sum + (Number(c.population) || 0), 0);
      const waveN = selected
        ? assignedCities.length
        : assignedCities.length || (Number(h.innerCount) || 0) + (Number(h.outerCount) || 0);
      const thinMark = h.thinWarning
        ? ` <span class="muted small" title="${esc(h.thinWarning)}">thin</span>`
        : '';
      const whyCell = showWhy ? `<td class="muted small">${esc(h.why || '')}</td>` : '';
      const action = selected
        ? `<span class="muted small">Selected</span>`
        : `<button type="button" class="btn btn-sm sg-pick-hub" data-city="${esc(h.city)}" data-state="${esc(h.state)}">Use hub</button>`;
      const warn = h.thinWarning
        ? `<tr class="sg-wave-row"><td></td><td colspan="${colSpan}" class="muted small">${esc(h.thinWarning)}</td></tr>`
        : '';
      const unmatched = (h.unmatched || []).length
        ? `<tr class="sg-wave-row"><td></td><td colspan="${colSpan}" class="muted small">Census unmatched: ${(h.unmatched || [])
            .map((u) => `${esc(u.city)}${u.state ? `, ${esc(u.state)}` : ''} (${esc(u.reason || '')})`)
            .join('; ')}</td></tr>`
        : '';
      const assignedRows = renderShotgunMemberRows(assignedCities, {
        canFocus: selected,
        muted: !selected,
        showWhy,
      });
      const leftoverHead = leftoverCities.length
        ? `<tr class="sg-wave-row muted"><td></td><td colspan="${colSpan}" class="muted small">Census leftover</td></tr>`
        : '';
      const leftoverRows = renderShotgunMemberRows(leftoverCities, {
        canFocus: selected,
        muted: true,
        showWhy,
      });
      const childRows = expanded
        ? `${assignedRows}${leftoverHead}${leftoverRows}${warn}${unmatched}`
        : '';
      return `<tr class="sg-hub-row${selected ? ' active' : ''}" data-key="${esc(key)}">
          <td><button type="button" class="btn btn-sm sg-expand-hub" data-key="${esc(key)}" aria-expanded="${expanded ? 'true' : 'false'}">${expanded ? '−' : '+'}</button></td>
          <td>${shotgunCityFocusHtml(h.city, h.state, selected)}${thinMark}</td>
          <td>${esc(formatShotgunPop(h.population))}</td>
          <td>${esc(formatShotgunPop(clusterPop))}</td>
          <td>${esc(String(Number(waveN) || '—'))}</td>
          ${whyCell}
          <td>${action}</td>
        </tr>${childRows}`;
    })
    .join('');
}

function renderShotgunClusterTableHtml(
  hubs,
  draft,
  { selectedKey = '', showWhy = false, caption = '', censusExtras = [] } = {},
) {
  if (!hubs.length && !censusExtras.length) return '';
  const claudeRows = renderShotgunHubRowsHtml(hubs, draft, { selectedKey, showWhy });
  const extraRows = renderShotgunHubRowsHtml(censusExtras, draft, { selectedKey, showWhy });
  const colSpan = showWhy ? 7 : 6;
  const groupRow = censusExtras.length
    ? `<tr class="sg-group-row"><td colspan="${colSpan}" class="muted small">Also in Census (${censusExtras.length})</td></tr>`
    : '';
  return `
      ${caption ? `<p class="muted small">${caption}</p>` : ''}
      <table class="discovery-shotgun-hubs-table discovery-shotgun-cluster-table">
        <thead><tr>
          <th></th>
          <th>Hub</th>
          <th>Hub pop</th>
          <th>Cluster pop</th>
          <th>Cluster Cities</th>
          ${showWhy ? '<th>Why</th>' : ''}
          <th></th>
        </tr></thead>
        <tbody>${claudeRows}${groupRow}${extraRows}</tbody>
      </table>
    `;
}

function wireShotgunClusterTable(hubsEl) {
  hubsEl.querySelectorAll('.sg-pick-hub').forEach((btn) => {
    btn.addEventListener('click', () => pickShotgunHub(btn.dataset.city, btn.dataset.state));
  });
  hubsEl.querySelectorAll('.sg-expand-hub').forEach((btn) => {
    btn.addEventListener('click', () => {
      const key = btn.dataset.key;
      if (shotgunExpandedHubs.has(key)) shotgunExpandedHubs.delete(key);
      else shotgunExpandedHubs.add(key);
      void renderShotgunWorkspace();
    });
  });
  hubsEl.querySelectorAll('.sg-focus-city').forEach((btn) => {
    btn.addEventListener('click', () => {
      shotgunMapMount?.focusCity?.(btn.dataset.city, btn.dataset.state);
    });
  });
}

function shotgunStatesLabel(draft, batch) {
  const fromScan = (draft?.hubScan?.states || []).filter(Boolean);
  if (fromScan.length) return fromScan.join(', ');
  const fromFilters = batch?.filters?.states || [];
  if (fromFilters.length) return fromFilters.join(', ');
  return batch?.filters?.state || '';
}

function renderShotgunEmptyHubsHtml(draft, batch) {
  const scan = draft.hubScan || {};
  const states = shotgunStatesLabel(draft, batch) || 'these states';
  const n = Number(scan.scanned) || 0;
  const rejected = draft.rejectedHubs || [];
  const r = rejected.length;
  const hubMin = Number(scan.hubMin ?? 60000).toLocaleString();
  const hubMax = scan.hubMax == null || scan.hubMax === '' ? '∞' : Number(scan.hubMax).toLocaleString();
  const censusNote = scan.error ? `<p class="warn-text">${esc(scan.error)}</p>` : '';
  const rows = rejected.length
    ? `<div class="discovery-shotgun-rejected-wrap"><table class="discovery-shotgun-hubs-table">
        <thead><tr><th>City</th><th>ST</th><th>Why</th></tr></thead>
        <tbody>${rejected
          .map(
            (row) => `<tr>
              <td>${esc(row.city || '')}</td>
              <td>${esc(row.state || '')}</td>
              <td>${esc(row.rejectReason || row.why || '')}</td>
            </tr>`,
          )
          .join('')}</tbody>
      </table></div>`
    : '<p class="muted small">No rejected-city detail stored on this pack.</p>';
  return `
    <div class="callout warn discovery-shotgun-empty">
      <p><strong>No cluster hubs in ${esc(states)}</strong></p>
      <p>Claude returned no Census-matchable hubs, and there are no Hub-band Census places to fall back on.</p>
      <p><strong>What we tried:</strong> ${esc(String(n))} cities in the Hub band (${esc(hubMin)}–${esc(String(hubMax))}). ${esc(String(r))} failed Census neighbor checks.</p>
      <p><strong>What to change:</strong> Widen <strong>Miles from Hub</strong>, lower <strong>Cluster Cities min pop</strong>, or raise <strong>Hub max pop</strong> if the metros you want are bigger cores. Then Create pack again.</p>
      ${censusNote}
      <p class="muted small"><strong>Detail</strong></p>
      ${rows}
    </div>
  `;
}

function shotgunMembersSig(draft = {}) {
  return (draft.members || [])
    .map((m) => `${shotgunHubKey(m.city, m.state)}:${m.role}:${m.wave || ''}:${m.clusterKey || ''}`)
    .sort()
    .join(';');
}

async function renderShotgunWorkspace() {
  const panel = document.getElementById('discovery-shotgun-panel');
  const headEl = document.getElementById('discovery-shotgun-head');
  const hubsEl = document.getElementById('discovery-shotgun-hubs');
  const legend = document.getElementById('discovery-shotgun-legend');
  const mapHost = document.getElementById('discovery-map-canvas');
  const ws = state.shotgunWorkspace;
  const shotgun = discoveryBatchIsShotgun() && ws;
  syncDiscoveryZoneGuide();
  const draftEarly = ws?.draft || {};
  const nextHubKey = draftEarly.hub?.city
    ? shotgunHubKey(draftEarly.hub.city, draftEarly.hub.state)
    : '';
  const keepMap = Boolean(
    shotgun &&
      nextHubKey &&
      nextHubKey === shotgunMountedHubKey,
  );
  if (!keepMap) {
    if (shotgunMapMount) {
      try {
        shotgunMapMount.destroy();
      } catch {
        /* ignore */
      }
    }
    shotgunMapMount = null;
    shotgunMountedHubKey = '';
    shotgunMountedMembersSig = '';
  }
  if (!panel || !hubsEl) return;
  if (!shotgun) {
    panel.classList.add('hidden');
    legend?.classList.add('hidden');
    if (headEl) headEl.innerHTML = '';
    const tablePanel = document.querySelector('.discovery-table-panel');
    tablePanel?.classList.remove('shotgun-map-mode', 'shotgun-hub-on');
    placeDiscoveryMapCanvas(tablePanel);
    const canvas = document.getElementById('discovery-map-canvas');
    canvas?.classList.add('hidden', 'shotgun-map-off');
    document.getElementById('discovery-shotgun-map-slot')?.classList.add('shotgun-map-off');
    const wrap = document.querySelector('.discovery-table-wrap');
    const filters = document.getElementById('discovery-table-filters');
    const hasRows = (state.discoveryRows || []).length > 0;
    wrap?.classList.toggle('hidden', !hasRows);
    filters?.classList.toggle('hidden', !hasRows);
    applyShotgunMapExpanded();
    syncDiscoverySurfaceToggle();
    return;
  }
  const draft = ws.draft || {};
  const hasPackRows = (state.discoveryRows || []).length > 0;
  if (!shotgunSurfaceIsHub()) {
    syncShotgunDiscoverySurfaces({ hasHub: Boolean(draft.hub), hasPackRows });
    return;
  }
  panel.classList.remove('hidden');
  const hubs = shotgunPickerHubs(draft, ws);
  const censusExtras = shotgunCensusExtras(draft, ws).filter((h) => {
    const k = shotgunHubKey(h.city, h.state);
    return !hubs.some((c) => shotgunHubKey(c.city, c.state) === k);
  });
  const selectedKey = draft.hub?.city
    ? shotgunHubKey(draft.hub.city, draft.hub.state)
    : '';
  const showWhy = hubs.some((h) => h.why);
  const finding =
    !draft.hub &&
    !hubs.length &&
    !draft.claudeClustersRan &&
    (shotgunJobRunning() ||
      Boolean(state._shotgunJobTrack) ||
      Boolean(state._shotgunAwaitingClusters));
  if (finding) {
    if (headEl) headEl.innerHTML = '';
    hubsEl.innerHTML = `<p class="muted">Finding clusters…</p>`;
    legend?.classList.add('hidden');
    syncShotgunDiscoverySurfaces({ hasHub: false, hasPackRows });
    return;
  }
  if (
    !draft.hub &&
    !hubs.length &&
    draft.claudeClustersRan &&
    !censusExtras.length
  ) {
    if (headEl) headEl.innerHTML = '';
    hubsEl.innerHTML = renderShotgunEmptyHubsHtml(draft, ws.batch);
    legend?.classList.add('hidden');
    syncShotgunDiscoverySurfaces({ hasHub: false, hasPackRows });
    return;
  }
  const members = draft.members || [];
  const sum = ws.summary || {};
  const newCount = shotgunNewCityCount(ws);
  const packReady = shotgunPackReady(ws);
  const packBtnLabel = hasPackRows
    ? `Re-run Generate pack from ${esc(draft.hub?.city || 'hub')} (${newCount} cities)`
    : `Generate pack from ${esc(draft.hub?.city || 'hub')} (${newCount} cities)`;
  const zoneLabel = formatZnDisplay(draft.sgNumber);
  const selectedLine = draft.hub
    ? `<div class="sg-hub-lock">
        <p><strong>${zoneLabel ? `${esc(zoneLabel)} · ` : ''}${esc(draft.hub.city)}, ${esc(draft.hub.state)}</strong> · Hub
        · ${members.filter((m) => {
          const r = String(m.role || '').toLowerCase();
          return r !== 'hub' && r !== 'main' && (shotgunIsCityRole(m.role, m) || memberClusterKey(m));
        }).length} Cluster Cities
        ${sum.existingCount ? ` · ${sum.existingCount} already in pipeline` : ''}
        ${newCount ? ` · ${newCount} new` : ''}
        <button type="button" class="btn btn-sm" id="sg-change-hub">Change hub</button>
        <button type="button" class="btn btn-sm primary" id="sg-generate-pack" ${
          packReady.ok && !generatePackJobRunning() ? '' : 'disabled'
        }>${packBtnLabel}</button>
        </p>
        <p class="muted small sg-hub-lock-note">Pack includes only this hub’s cities (Hub + Cluster Cities). Other hubs in the list are not included.</p>
      </div>`
    : '';
  const waitingCopy =
    !draft.claudeClustersRan && !hubs.length
      ? `<p class="muted small">Pick a hub. Then set the cluster cities on the map and Generate pack. Find hubs with Claude is optional.</p>`
      : '';
  const clusterTable = renderShotgunClusterTableHtml(hubs, draft, {
    selectedKey,
    showWhy,
    censusExtras,
    caption: draft.hub
      ? 'Selected hub Cluster Cities update as you assign on the map. Generate pack uses this hub only — other hubs are not packed.'
      : hubs.length
        ? 'Claude clusters — Cluster Cities are Claude’s picks.'
        : '',
  });
  if (headEl) headEl.innerHTML = selectedLine;
  hubsEl.innerHTML = `${waitingCopy}${clusterTable}`;
  wireShotgunClusterTable(hubsEl);
  document.getElementById('sg-change-hub')?.addEventListener('click', () => clearShotgunHubUi());
  const packBtn = document.getElementById('sg-generate-pack');
  if (packBtn) {
    setElementTip(
      packBtn,
      packReady.ok
        ? 'Create rows for this hub only.'
        : packReady.tip,
    );
    packBtn.addEventListener('click', () => void startShotgunGeneratePackFromUi());
  }
  syncDiscoveryLightSerpButton();
  syncDiscoveryApiRerunButton();
  if (!draft.hub) {
    legend?.classList.add('hidden');
    syncShotgunDiscoverySurfaces({ hasHub: false, hasPackRows });
    return;
  }
  legend?.classList.remove('hidden');
  teardownDiscoveryCitiesMapMount();
  syncShotgunDiscoverySurfaces({ hasHub: true, hasPackRows });
  if (keepMap) {
    shotgunMapMount?.setMembers?.(ws);
    requestAnimationFrame(() => shotgunMapMount?.invalidateSize?.());
    return;
  }
  const host = document.getElementById('discovery-map-canvas') || mapHost;
  if (host) {
    const gen = ++shotgunRenderGen;
    shotgunMountedHubKey = selectedKey;
    shotgunMountedMembersSig = shotgunMembersSig(draft);
    try {
      const mounted = await mountShotgunMap({
        mapHost: host,
        slot: document.getElementById('discovery-shotgun-map-slot'),
        api,
        workspace: ws,
        undoScope: `discovery:${state.discoveryBatchId || ''}`,
        onHandle: (h) => {
          shotgunMapMount = h;
        },
        onPaint: async (city, st, payload) => {
          try {
            const result = await api(
              `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/shotgun/paint`,
              {
                method: 'POST',
                body: JSON.stringify({
                  city,
                  state: st,
                  tool: payload?.tool,
                  slot: payload?.slot,
                  minPop: payload?.minPop,
                  maxPop: payload?.maxPop,
                  radiusMiles: payload?.radiusMiles,
                }),
              },
            );
            state.shotgunWorkspace = result.workspace || result;
            await renderShotgunWorkspace();
          } catch (error) {
            showToast(error.message || 'Could not update city', { tone: 'warn' });
            throw error;
          }
        },
        onPaintMany: async (cities, payload) => {
          try {
            const result = await api(
              `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/shotgun/paint-many`,
              {
                method: 'POST',
                body: JSON.stringify({
                  cities,
                  slot: payload?.slot,
                  radiusMiles: payload?.radiusMiles,
                }),
              },
            );
            state.shotgunWorkspace = result.workspace || result;
            await renderShotgunWorkspace();
          } catch (error) {
            showToast(error.message || 'Could not update cities', { tone: 'warn' });
            throw error;
          }
        },
        onZoneMilesChange: async (miles, range) => {
          if (!state.discoveryBatchId) return;
          try {
            const result = await api(
              `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/shotgun/radius`,
              {
                method: 'POST',
                body: JSON.stringify({
                  miles,
                  minPop: range?.minPop,
                  maxPop: range?.maxPop,
                }),
              },
            );
            state.shotgunWorkspace = result.workspace || result;
            shotgunMapMount?.setMembers?.(state.shotgunWorkspace);
          } catch (error) {
            showToast(error.message || 'Could not save Zone radius', { tone: 'warn' });
          }
        },
      });
      if (gen !== shotgunRenderGen) {
        try {
          mounted?.destroy?.();
        } catch {
          /* stale */
        }
        if (shotgunMapMount === mounted) shotgunMapMount = null;
        return;
      }
      shotgunMapMount = mounted;
      requestAnimationFrame(() => shotgunMapMount?.invalidateSize?.());
      setTimeout(() => shotgunMapMount?.invalidateSize?.(), 200);
    } catch (error) {
      if (gen === shotgunRenderGen) {
        showToast(error.message || 'Cluster map failed', { tone: 'warn' });
      }
    }
  }
}

async function pickShotgunHub(city, st) {
  try {
    const result = await api(
      `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/shotgun/select-hub`,
      { method: 'POST', body: JSON.stringify({ city, state: st }) },
    );
    state.shotgunWorkspace = result.workspace;
    shotgunExpandedHubs.add(shotgunHubKey(city, st));
    await renderShotgunWorkspace();
    renderShotgunPasteSteps();
    if (effectiveClaudeUiMode() === 'api') renderShotgunApiButtons();
  } catch (error) {
    await showModal({
      title: 'Hub not viable',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>${esc(error.message)}</p>`,
    });
  }
}

async function clearShotgunHubUi() {
  try {
    const result = await api(
      `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/shotgun/select-hub`,
      { method: 'POST', body: JSON.stringify({ city: '', state: '' }) },
    );
    state.shotgunWorkspace = result.workspace;
    await renderShotgunWorkspace();
    renderShotgunPasteSteps();
    if (effectiveClaudeUiMode() === 'api') renderShotgunApiButtons();
  } catch (error) {
    showToast(error.message || 'Could not change hub', { tone: 'warn' });
  }
}

function renderShotgunPasteSteps() {
  const box = document.getElementById('discovery-pack-result');
  const empty = document.getElementById('discovery-pack-empty');
  if (!box) return;
  if (effectiveClaudeUiMode() === 'api' || !discoveryBatchIsShotgun()) return;
  const ws = state.shotgunWorkspace;
  const step = ws?.draft?.step || 'hub';
  empty?.classList.add('hidden');
  box.classList.remove('hidden');
  if (step === 'hub' || !ws?.draft?.hub) {
    box.innerHTML = `
      <ol class="discovery-pack-next">
        <li><button type="button" class="btn primary" id="sg-copy-find-hubs">Copy Find clusters prompt</button></li>
        <li>Optional — Claude names hub + Cluster Cities. Paste JSON, then Import.</li>
      </ol>
      <textarea id="sg-import-text" class="narrative-paste-input" rows="3" placeholder="Paste Find clusters JSON…"></textarea>
      <button type="button" class="btn primary" id="sg-import-find">Import JSON</button>
    `;
    document.getElementById('sg-copy-find-hubs')?.addEventListener('click', async () => {
      const data = await api(
        `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/shotgun/prompt?step=hub`,
      );
      await navigator.clipboard.writeText(data.prompt || '');
      showToast('Find clusters prompt copied.');
    });
    document.getElementById('sg-import-find')?.addEventListener('click', () =>
      importShotgunStep('hub', document.getElementById('sg-import-text')?.value || ''),
    );
    return;
  }
  if (step === 'assign' || !(ws.draft.members || []).some((m) => shotgunIsCityRole(m.role))) {
    box.innerHTML = `
      <ol class="discovery-pack-next">
        <li><button type="button" class="btn primary" id="sg-copy-assign">Copy Assign cluster cities prompt</button></li>
        <li>Paste in Claude, then Import JSON. You can still click the map.</li>
      </ol>
      <textarea id="sg-import-text" class="narrative-paste-input" rows="3" placeholder="Paste Assign cluster cities JSON…"></textarea>
      <button type="button" class="btn primary" id="sg-import-assign">Import JSON</button>
    `;
    document.getElementById('sg-copy-assign')?.addEventListener('click', async () => {
      const data = await api(
        `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/shotgun/prompt?step=assign`,
      );
      await navigator.clipboard.writeText(data.prompt || '');
      showToast('Assign cluster cities prompt copied.');
    });
    document.getElementById('sg-import-assign')?.addEventListener('click', () =>
      importShotgunStep('assign', document.getElementById('sg-import-text')?.value || ''),
    );
    return;
  }
  box.innerHTML = `
    <ol class="discovery-pack-next">
      <li><button type="button" class="btn primary" id="sg-copy-pack">Copy Generate pack prompt</button></li>
      <li>Claude fills pinned cities only. Then paste CSV.</li>
    </ol>
    <textarea id="sg-import-text" class="narrative-paste-input" rows="3" placeholder="Paste Generate pack CSV…"></textarea>
    <button type="button" class="btn primary" id="sg-import-pack">Import CSV</button>
  `;
  document.getElementById('sg-copy-pack')?.addEventListener('click', async () => {
    const data = await api(
      `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/shotgun/prompt?step=pack`,
    );
    await navigator.clipboard.writeText(data.prompt || '');
    showToast('Generate pack prompt copied.');
  });
  document.getElementById('sg-import-pack')?.addEventListener('click', () =>
    importShotgunStep('pack', document.getElementById('sg-import-text')?.value || ''),
  );
}

async function importShotgunStep(step, text) {
  if (!String(text || '').trim()) {
    await showModal({
      title: 'Nothing to import',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: '<p>Paste Claude’s result first.</p>',
    });
    return;
  }
  try {
    const result = await api(
      `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/shotgun/import`,
      { method: 'POST', body: JSON.stringify({ step, text }) },
    );
    if (result.workspace) state.shotgunWorkspace = result.workspace;
    else if (result.draft) await loadShotgunWorkspace();
    else if (result.shotgun) state.shotgunWorkspace = result.shotgun;
    if (result.rows) state.discoveryRows = result.rows;
    else if (result.batch) await selectDiscoveryBatch(state.discoveryBatchId);
    await renderShotgunWorkspace();
    renderShotgunPasteSteps();
    renderDiscoveryTable();
    showToast(step === 'pack' ? 'Cluster pack imported.' : 'Imported.');
  } catch (error) {
    await showModal({
      title: 'Import failed',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>${esc(error.message)}</p>`,
    });
  }
}

async function confirmShotgunCost(batchId, act) {
  const preview = await api(
    `/api/discovery/batches/${encodeURIComponent(batchId)}/cost-preview?act=${encodeURIComponent(act)}`,
  );
  if (preview.error) {
    await showModal({
      title: preview.title || 'Cannot run',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>${esc(preview.error)}</p>`,
    });
    return false;
  }
  const sum = state.shotgunWorkspace?.summary;
  const mergeNote =
    act === 'shotgun-generate-pack' && sum
      ? `<p><strong>${esc(String(sum.newCount))} new</strong> · ${esc(String(sum.existingCount))} already in pipeline (merged, not duplicated).</p>`
      : '';
  return showModal({
    title: preview.title,
    confirmLabel: preview.confirmLabel || 'Run',
    bodyHtml: `
      <p>${esc(preview.whatItDoes)}</p>
      ${mergeNote}
      <p><strong>Estimated cost:</strong> ${esc(preview.estimateLabel)}</p>
      <p class="muted">${esc(preview.estimateDetail || '')}</p>
      ${preview.freeFallback ? `<p class="muted">${esc(preview.freeFallback)}</p>` : ''}
    `,
  });
}

async function startShotgunApiStep(act) {
  const id = state.discoveryBatchId;
  if (!id) return;
  if (!(await confirmShotgunCost(id, act))) {
    if (act === 'shotgun-find-hubs') {
      state._shotgunAwaitingClusters = false;
      void renderShotgunWorkspace();
    }
    return;
  }
  const path =
    act === 'shotgun-assign-cities' || act === 'shotgun-assign-waves'
      ? 'assign-cities'
      : act === 'shotgun-generate-pack'
        ? 'generate-pack'
        : 'find-hubs';
  try {
    const accepted = await api(`/api/discovery/batches/${encodeURIComponent(id)}/shotgun/${path}`, {
      method: 'POST',
      body: '{}',
    });
    if (act === 'shotgun-generate-pack') {
      state._generatePackHandledJobId = null;
      state._generatePackTrack = { batchId: id, jobId: accepted.jobId };
      if (accepted?.jobId) play('job');
      syncGeneratePackOverlay(snapWithOptimisticGeneratePack(accepted.jobId, id));
    } else {
      state._shotgunJobTrack = { batchId: id, jobId: accepted.jobId, act };
      if (act === 'shotgun-find-hubs') state._shotgunAwaitingClusters = true;
      syncShotgunJobOverlay(state.lightJobsSnap);
    }
  } catch (error) {
    if (act === 'shotgun-find-hubs') {
      state._shotgunAwaitingClusters = false;
      void renderShotgunWorkspace();
    }
    if (act === 'shotgun-generate-pack' && error.code === 'GENERATE_PACK_RUNNING' && error.jobId) {
      state._generatePackTrack = { batchId: id, jobId: error.jobId };
      syncGeneratePackOverlay(snapWithOptimisticGeneratePack(error.jobId, id));
      return;
    }
    if (error.code === 'GENERATE_PACK_BUSY') {
      await explainConcurrencyLimit({
        key: 'generatePack',
        running: error.running,
        limit: error.limit ?? state.concurrency?.generatePack ?? 5,
      });
      return;
    }
    await showModal({
      title: 'Could not start',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>${esc(error.message)}</p>`,
    });
  }
}

function shotgunJobRunning() {
  const jobs = state.lightJobsSnap?.jobs || [];
  return jobs.some(
    (j) =>
      (j.phase === 'shotgun-find-hubs' ||
        j.phase === 'shotgun-assign-cities' ||
        j.phase === 'shotgun-assign-waves') &&
      (j.status === 'running' || j.status === 'queued'),
  );
}

function syncShotgunJobOverlay(snap) {
  const overlay = document.getElementById('discovery-generate-pack-overlay');
  const title = document.getElementById('gp-overlay-title');
  const jobs = snap?.jobs || [];
  const job = jobs.find(
    (j) =>
      (j.phase === 'shotgun-find-hubs' ||
        j.phase === 'shotgun-assign-cities' ||
        j.phase === 'shotgun-assign-waves') &&
      (j.status === 'running' || j.status === 'queued') &&
      String(j.batchId || '') === String(state.discoveryBatchId || ''),
  );
  if (job && overlay) {
    if (title) title.textContent = job.label || 'Cluster';
    overlay.dataset.jobId = job.id;
    const showShotgun = state.view === 'discovery';
    setGeneratePackOverlayVisible(showShotgun);
    noteTabWorking('overlay:shotgun', showShotgun);
    const detailEl = document.getElementById('gp-overlay-detail');
    if (detailEl) detailEl.textContent = job.detail || 'Working…';
    return;
  }
  const track = state._shotgunJobTrack;
  if (!track) {
    noteTabWorking('overlay:shotgun', false);
    return;
  }
  const finished = jobs.find((j) => String(j.id) === String(track.jobId));
  if (finished && (finished.status === 'running' || finished.status === 'queued')) return;
  noteTabWorking('overlay:shotgun', false);
  state._shotgunJobTrack = null;
  if (title) title.textContent = 'Generate pack';
  setGeneratePackOverlayVisible(false);
  if (finished?.status === 'done') {
    if (track.act === 'shotgun-find-hubs') state._shotgunAwaitingClusters = false;
    void loadShotgunWorkspace().then(() => {
      renderShotgunPasteSteps();
      if (effectiveClaudeUiMode() === 'api') renderShotgunApiButtons();
      const draft = state.shotgunWorkspace?.draft || {};
      const picker = shotgunPickerHubs(draft, state.shotgunWorkspace);
      const extras = shotgunCensusExtras(draft, state.shotgunWorkspace);
      if (track.act === 'shotgun-find-hubs' && !draft.hub && !picker.length && !extras.length) {
        showToast('No cluster hubs — Claude had no matchable hubs');
      } else {
        announceStepComplete(
          track.act === 'shotgun-assign-cities' || track.act === 'shotgun-assign-waves'
            ? 'Assign cluster cities'
            : 'Find hubs',
        );
      }
      if (track.act === 'shotgun-find-hubs') void loadDiscoveryBatches();
    });
  } else if (finished?.status === 'error') {
    if (track.act === 'shotgun-find-hubs') state._shotgunAwaitingClusters = false;
    void renderShotgunWorkspace();
    void showModal({
      title: 'Cluster step failed',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>${esc(finished.error || 'Failed')}</p>`,
    });
  }
}

function renderShotgunApiButtons() {
  const box = document.getElementById('discovery-pack-result');
  const empty = document.getElementById('discovery-pack-empty');
  if (!box || effectiveClaudeUiMode() !== 'api' || !discoveryBatchIsShotgun()) return;
  empty?.classList.add('hidden');
  box.classList.remove('hidden');
  const ws = state.shotgunWorkspace;
  const hasHub = Boolean(ws?.draft?.hub);
  const hasPackCities = (ws?.draft?.members || []).some((m) => shotgunIsCityRole(m.role, m));
  box.innerHTML = `
    <ol class="discovery-pack-next">
      ${
        !hasHub
          ? `<li><button type="button" class="btn primary" id="sg-api-find">Find hubs with Claude</button></li>`
          : ''
      }
      ${
        hasHub
          ? `<li><button type="button" class="btn" id="sg-api-assign">Reshuffle cluster cities with Claude</button></li>`
          : ''
      }
      ${
        hasPackCities
          ? `<li><button type="button" class="btn primary" id="sg-api-pack">Generate cluster pack</button></li>`
          : ''
      }
    </ol>
  `;
  document.getElementById('sg-api-find')?.addEventListener('click', () =>
    startShotgunApiStep('shotgun-find-hubs'),
  );
  document.getElementById('sg-api-assign')?.addEventListener('click', () =>
    startShotgunApiStep('shotgun-assign-cities'),
  );
  document.getElementById('sg-api-pack')?.addEventListener('click', () =>
    startShotgunApiStep('shotgun-generate-pack'),
  );
}

const zoneGuideLoaded = new WeakMap();
let zoneMapGuideOpen = false;

function zoneGuideNoteHtml(row) {
  const zoneId = row?.shotgunClusterId;
  if (!zoneId) return '';
  const at = row?.planningGuideUpdatedAt;
  if (!at) {
    return `<p class="muted small zone-guide-note"><button type="button" class="btn btn-sm zone-guide-open" data-zone-id="${esc(zoneId)}">Zone guide</button></p>`;
  }
  const configAt = row.lastSiteConfigAt || row.meta?.lastSiteConfigAt || row.siteConfig?._ops?.acceptedAt || '';
  const writeAt = row.contentAcceptedAt || row.content?._ops?.acceptedAt || '';
  const guideMs = Date.parse(at);
  const stale =
    (configAt && Date.parse(configAt) < guideMs) || (writeAt && Date.parse(writeAt) < guideMs);
  const text = stale
    ? 'Zone guide changed. Re-run Site config and Write to apply.'
    : 'Uses this zone’s guide.';
  return `<p class="muted small zone-guide-note">${esc(text)} <button type="button" class="btn btn-sm zone-guide-open" data-zone-id="${esc(zoneId)}">Guide</button></p>`;
}

function zoneGuideShellHtml() {
  return `<details class="zone-guide">
    <summary><span>Zone guide</span> <span class="muted small" data-zg="status">Loading…</span></summary>
    <div class="zone-guide-panes">
      <p class="muted small">Saving the source does not change prompts. Distill writes a proposal. Use this brief is what city picking, service pages, and writing read. If Find hubs already ran, run it again after accepting.</p>
      <label>Source
        <textarea data-zg="source" rows="8" placeholder="Paste a guide. Markdown or plain text."></textarea>
      </label>
      <div class="zone-guide-actions">
        <button type="button" class="btn btn-sm" data-zg="save-source">Save source</button>
        <button type="button" class="btn btn-sm" data-zg="upload">Upload</button>
        <input data-zg="file" type="file" accept=".md,.txt,text/plain,text/markdown" hidden />
        <button type="button" class="btn btn-sm" data-zg="distill">Distill</button>
        <button type="button" class="btn btn-sm" data-zg="copy-prompt">Copy distill prompt</button>
      </div>
      <label>Brief <span data-zg="brief-label"></span>
        <textarea data-zg="brief" rows="10" placeholder="Paste a headed brief, or distill the source. Prompts ignore this until you use it."></textarea>
      </label>
      <div class="zone-guide-actions">
        <button type="button" class="btn btn-sm primary" data-zg="accept">Use this brief</button>
      </div>
    </div>
  </details>`;
}

function paintZoneGuideStatus(host, data) {
  const status = host.querySelector('[data-zg="status"]');
  const label = host.querySelector('[data-zg="brief-label"]');
  const stateName = data?.briefState || 'empty';
  const text =
    stateName === 'accepted'
      ? 'Accepted — live'
      : stateName === 'proposed'
        ? 'Proposed — not live'
        : 'No accepted brief';
  if (status) status.textContent = text;
  if (label) label.textContent = stateName === 'proposed' ? 'Proposed' : stateName === 'accepted' ? 'Accepted' : '';
}

function zoneGuideBusy(host, busy) {
  host.querySelectorAll('button').forEach((btn) => {
    btn.disabled = busy;
  });
}

function rememberZoneGuideFields(host) {
  const source = host.querySelector('[data-zg="source"]');
  const brief = host.querySelector('[data-zg="brief"]');
  zoneGuideLoaded.set(host, { source: source?.value || '', brief: brief?.value || '' });
}

async function loadZoneGuide(host, scope) {
  const data = await api(`/api/zone-guides/${scope.kind}/${encodeURIComponent(scope.id)}`);
  const source = host.querySelector('[data-zg="source"]');
  const brief = host.querySelector('[data-zg="brief"]');
  if (source) source.value = data.source || '';
  if (brief) brief.value = data.brief || '';
  rememberZoneGuideFields(host);
  paintZoneGuideStatus(host, data);
  return data;
}

function ensureZoneGuide(host, scope) {
  if (!host || !scope?.id) return;
  const key = `${scope.kind}:${scope.id}`;
  if (host.dataset.zgScope === key && host.querySelector('[data-zg="source"]')) return;
  host.dataset.zgScope = key;
  host.innerHTML = zoneGuideShellHtml();
  wireZoneGuide(host, scope);
  void loadZoneGuide(host, scope).catch((error) => {
    showToast(error.message || 'Could not load zone guide', { tone: 'warn' });
  });
}

function wireZoneGuide(host, scope) {
  const path = `/api/zone-guides/${scope.kind}/${encodeURIComponent(scope.id)}`;
  host.querySelector('[data-zg="save-source"]')?.addEventListener('click', async () => {
    zoneGuideBusy(host, true);
    try {
      const data = await api(`${path}/source`, {
        method: 'POST',
        body: JSON.stringify({ text: host.querySelector('[data-zg="source"]')?.value || '' }),
      });
      rememberZoneGuideFields(host);
      paintZoneGuideStatus(host, data);
      showToast('Source saved');
    } catch (error) {
      showToast(error.message || 'Could not save source', { tone: 'warn' });
    } finally {
      zoneGuideBusy(host, false);
    }
  });
  host.querySelector('[data-zg="upload"]')?.addEventListener('click', () => {
    host.querySelector('[data-zg="file"]')?.click();
  });
  host.querySelector('[data-zg="file"]')?.addEventListener('change', async (event) => {
    const file = event.target?.files?.[0];
    event.target.value = '';
    if (!file) return;
    const text = await file.text();
    const source = host.querySelector('[data-zg="source"]');
    if (source) source.value = text;
    host.querySelector('[data-zg="save-source"]')?.click();
  });
  host.querySelector('[data-zg="copy-prompt"]')?.addEventListener('click', async () => {
    zoneGuideBusy(host, true);
    try {
      const source = host.querySelector('[data-zg="source"]');
      const loaded = zoneGuideLoaded.get(host);
      if (source && source.value !== (loaded?.source || '')) {
        await api(`${path}/source`, {
          method: 'POST',
          body: JSON.stringify({ text: source.value }),
        });
        rememberZoneGuideFields(host);
      }
      const data = await api(`${path}/distill-prompt`);
      await navigator.clipboard.writeText(data.prompt || '');
      showToast('Distill prompt copied');
    } catch (error) {
      showToast(error.message || 'Could not copy distill prompt', { tone: 'warn' });
    } finally {
      zoneGuideBusy(host, false);
    }
  });
  host.querySelector('[data-zg="distill"]')?.addEventListener('click', async () => {
    const brief = host.querySelector('[data-zg="brief"]');
    const loaded = zoneGuideLoaded.get(host);
    if (brief && brief.value !== (loaded?.brief || '')) {
      const ok = await showModal({
        title: 'Replace the brief pane?',
        confirmLabel: 'Distill',
        bodyHtml: '<p>Distill replaces the text in the brief pane with a new proposal. The accepted brief stays live until you click Use this brief.</p>',
      });
      if (!ok) return;
    } else {
      const ok = await showModal({
        title: 'Distill zone guide?',
        confirmLabel: 'Distill',
        bodyHtml: '<p>Distill calls Claude and writes a proposed brief. The accepted brief stays live until you click Use this brief.</p>',
      });
      if (!ok) return;
    }
    zoneGuideBusy(host, true);
    try {
      const source = host.querySelector('[data-zg="source"]');
      if (source && source.value !== (zoneGuideLoaded.get(host)?.source || '')) {
        await api(`${path}/source`, {
          method: 'POST',
          body: JSON.stringify({ text: source.value }),
        });
      }
      const started = await api(`${path}/distill`, { method: 'POST', body: '{}' });
      await waitForLightJobResult(started.jobId);
      const data = await loadZoneGuide(host, scope);
      host.querySelector('details.zone-guide')?.setAttribute('open', '');
      paintZoneGuideStatus(host, data);
      showToast('Proposed brief ready');
    } catch (error) {
      showToast(error.message || 'Distill failed', { tone: 'warn' });
    } finally {
      zoneGuideBusy(host, false);
    }
  });
  host.querySelector('[data-zg="accept"]')?.addEventListener('click', async () => {
    zoneGuideBusy(host, true);
    try {
      const data = await api(`${path}/accept`, {
        method: 'POST',
        body: JSON.stringify({ text: host.querySelector('[data-zg="brief"]')?.value || '' }),
      });
      const brief = host.querySelector('[data-zg="brief"]');
      if (brief) brief.value = data.accepted || data.brief || brief.value;
      rememberZoneGuideFields(host);
      paintZoneGuideStatus(host, data);
      showToast('Zone brief is live');
      if (state.selectedId) void loadSelectedCandidateDetail(state.selectedId);
      if (state.view === 'launched-sites') void loadSites();
    } catch (error) {
      showToast(error.message || 'Could not accept brief', { tone: 'warn' });
    } finally {
      zoneGuideBusy(host, false);
    }
  });
}

function syncDiscoveryZoneGuide() {
  const host = document.getElementById('discovery-zone-guide');
  if (!host) return;
  const id = state.discoveryBatchId;
  if (!discoveryBatchIsShotgun() || !id) {
    host.classList.add('hidden');
    return;
  }
  host.classList.remove('hidden');
  ensureZoneGuide(host, { kind: 'batch', id });
}

function openZoneGuidePanel(zoneId) {
  const host = document.getElementById('zone-map-guide');
  const id = String(zoneId || zoneMapId || '').trim();
  if (!host || !id) return;
  host.classList.remove('hidden');
  zoneMapGuideOpen = true;
  ensureZoneGuide(host, { kind: 'zone', id });
  host.querySelector('details.zone-guide')?.setAttribute('open', '');
}

function closeZoneMapModal({ prompt = false } = {}) {
  const guideHost = document.getElementById('zone-map-guide');
  zoneMapGuideOpen = Boolean(guideHost && !guideHost.classList.contains('hidden'));
  guideHost?.classList.add('hidden');
  const session = prompt ? zoneMapPrompt : null;
  const members = prompt ? zoneMapLatestMembers : null;
  hideOpsTooltip();
  const modal = document.getElementById('zone-map-modal');
  if (modal) {
    modal.classList.add('hidden');
    modal.hidden = true;
  }
  if (zoneMapMount) {
    try {
      zoneMapMount.destroy();
    } catch {
      /* ignore */
    }
  }
  zoneMapMount = null;
  zoneMapId = '';
  if (!prompt) return;
  zoneMapPrompt = null;
  zoneMapLatestMembers = null;
  if (
    session &&
    (session.fromView === 'research' || session.fromView === 'website-builder')
  ) {
    void maybeConfirmZonePaint(session, members);
  }
}

function zonePromoteDismissKey(zoneId, city) {
  return `${zoneId}|${String(city.city || '').trim().toLowerCase()}|${city.state}|${city.clusterKey}`;
}

function revealPromotedZoneCities(promoted) {
  const rows = promoted || [];
  if (!rows.length) return;
  const clusterFilter = String(state.candidateClusterFilter || '');
  if (clusterFilter && rows.some((row) => String(row.clusterKey) !== clusterFilter)) {
    state.candidateClusterFilter = '';
  }
  if (state.candidateDecisionFilter && state.candidateDecisionFilter !== 'pursue') {
    state.candidateDecisionFilter = 'pursue';
  }
  const text = String(state.candidateTextFilter || '').trim().toLowerCase();
  if (
    text &&
    rows.every((row) => !`${row.city} ${row.state} ${row.candidateId || ''}`.toLowerCase().includes(text))
  ) {
    state.candidateTextFilter = '';
  }
  syncUiRestoreControls();
  persistUiRestore();
}

async function revertZonePaintCity(zoneId, city) {
  if (!city?.paintedThisOpen) return;
  const slot = city.previousClusterKey >= 1 ? city.previousClusterKey : 0;
  await api(`/api/shotgun-clusters/${encodeURIComponent(zoneId)}/paint`, {
    method: 'POST',
    body: JSON.stringify({
      city: city.city,
      state: city.state,
      tool: 'cluster',
      slot,
    }),
  });
}

function zonePromoteJobText(batch) {
  const running = (batch?.children || []).find((child) => child.status === 'running' && child.step);
  if (running?.step === 'narrative') return 'Narrative…';
  if (running?.step === 'research') return 'SERP seeds…';
  if (running?.step) return `${jobActLabel(running.step)}…`;
  const total = batch?.children?.length || 0;
  const done = (batch?.done || 0) + (batch?.failed || 0);
  if (total) return `Working ${done}/${total}…`;
  return 'Working…';
}

async function waitForZonePromoteJob(batchJobId) {
  const detail = document.getElementById('zone-promote-overlay-detail');
  const bar = document.getElementById('zone-promote-overlay-bar');
  for (;;) {
    const batch = await api(`/api/jobs/batches/${encodeURIComponent(batchJobId)}`);
    const total = batch.children?.length || 0;
    const done = (batch.done || 0) + (batch.failed || 0);
    setDeterminateProgress(bar, { done, total });
    if (detail) detail.textContent = zonePromoteJobText(batch);
    if (batch.status !== 'running') return batch;
    await new Promise((resolve) => setTimeout(resolve, 800));
  }
}

async function maybeConfirmZonePaint(session, members) {
  const zoneId = session?.zoneId;
  if (!zoneId) return;
  const cities = zoneCitiesAwaitingCandidate(session.beforeMembers || [], members || []).filter(
    (city) => city.paintedThisOpen || !zonePromoteDismissed.has(zonePromoteDismissKey(zoneId, city)),
  );
  if (!cities.length) return;
  const boxes = cities
    .map(
      (city, index) =>
        `<label><input type="checkbox" data-zone-promote="${index}" checked /> ${esc(city.city)}, ${esc(
          city.state,
        )} → Cluster ${esc(String(city.clusterKey))}</label>`,
    )
    .join('');
  const ok = await showModal({
    title: 'Add these cities?',
    confirmLabel: 'Add and process',
    cancelLabel: "Don't add",
    bodyHtml: `<p>Rover will set Decision to <strong>pursue</strong>, create the candidate, then run <strong>Run all required</strong> (SERP seeds, then Narrative). Ads volumes, Enrich, and Prospects stay skipped. Narrative Accept stays a separate review.</p>
      <div class="zone-promote-list">${boxes}</div>`,
  });
  const checked = cities.map((_, index) => {
    const box = document.querySelector(`#modal-body [data-zone-promote="${index}"]`);
    return Boolean(box?.checked);
  });
  const process = ok && checked.some(Boolean) ? cities.filter((_, index) => checked[index]) : [];
  const revert = cities.filter((city, index) => city.paintedThisOpen && !process.includes(city));
  for (const city of cities) {
    if (process.includes(city) || city.paintedThisOpen) continue;
    zonePromoteDismissed.add(zonePromoteDismissKey(zoneId, city));
  }
  if (!process.length && !revert.length) {
    if (state.selectedId) void loadSelectedCandidateDetail(state.selectedId);
    return;
  }
  const detail = document.getElementById('zone-promote-overlay-detail');
  const bar = document.getElementById('zone-promote-overlay-bar');
  if (detail) detail.textContent = 'Creating candidates…';
  setDeterminateProgress(bar, {});
  setRoverJobOverlayVisible('zone-promote-overlay', true);
  let promoted = [];
  let job = null;
  let failed = null;
  try {
    for (const city of revert) {
      if (detail) detail.textContent = `Removing ${city.city}…`;
      await revertZonePaintCity(zoneId, city);
    }
    if (process.length) {
      if (detail) detail.textContent = 'Creating candidates…';
      const result = await api(`/api/shotgun-clusters/${encodeURIComponent(zoneId)}/promote-members`, {
        method: 'POST',
        body: JSON.stringify({
          cities: process.map((city) => ({ city: city.city, state: city.state })),
        }),
      });
      promoted = result.promoted || [];
      for (const city of process) zonePromoteDismissed.delete(zonePromoteDismissKey(zoneId, city));
      if (result.batchError) failed = new Error(result.batchError);
      if (result.batchJob?.id) job = await waitForZonePromoteJob(result.batchJob.id);
      const realFails = (job?.children || []).filter(
        (child) => child.status === 'error' && !/needs review/i.test(child.error || ''),
      );
      if (realFails.length) {
        failed = new Error(realFails.map((child) => `${child.candidateId}: ${child.error}`).join('; '));
      }
      if (detail) detail.textContent = 'Updating the table…';
      for (const row of promoted) {
        if (!row.candidateId) continue;
        await api(`/api/candidates/${encodeURIComponent(row.candidateId)}/decision`, {
          method: 'POST',
          body: JSON.stringify({ decision: 'pursue', notes: 'Added from zone map' }),
        });
      }
    }
  } catch (error) {
    failed = error;
  } finally {
    setRoverJobOverlayVisible('zone-promote-overlay', false);
    setDeterminateProgress(bar, {});
  }
  if (promoted.length) revealPromotedZoneCities(promoted);
  try {
    await loadCandidates();
    if (state.selectedId) await loadSelectedCandidateDetail(state.selectedId);
  } catch {
    /* table refresh is best-effort after the job */
  }
  if (failed) {
    await showModal({
      title: 'Could not finish adding cities',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>${esc(failed.message || 'Required research failed')}</p>`,
    });
    return;
  }
  if (!promoted.length) return;
  const names = promoted.map((row) => row.city).join(', ');
  const needsReview = (job?.children || []).some((child) =>
    /needs review/i.test(child.error || ''),
  );
  showToast(
    needsReview
      ? `${names} added. Narrative draft is ready to Accept.`
      : `${names} added.`,
  );
}

async function openZoneMapModal(zoneId, { focusCity, focusState, keepSession = false, guide = false } = {}) {
  const id = String(zoneId || '').trim();
  if (!id) return;
  const modal = document.getElementById('zone-map-modal');
  const slot = document.getElementById('zone-map-slot');
  const host = document.getElementById('zone-map-canvas');
  const title = document.getElementById('zone-map-modal-title');
  if (!modal || !host || !slot) return;
  const keep = keepSession && zoneMapPrompt?.zoneId === id;
  closeZoneMapModal({ prompt: false });
  const restoreGuide = guide || (keep && zoneMapGuideOpen);
  if (!keep) {
    zoneMapPrompt = null;
    zoneMapLatestMembers = null;
  }
  hideOpsTooltip();
  zoneMapId = id;
  modal.classList.remove('hidden');
  modal.hidden = false;
  if (restoreGuide) openZoneGuidePanel(id);
  try {
    const ws = await api(`/api/shotgun-clusters/${encodeURIComponent(id)}/workspace`);
    zoneMapLatestMembers = ws?.draft?.members || [];
    if (!keep) {
      zoneMapPrompt = {
        zoneId: id,
        fromView: state.view,
        beforeMembers: zoneMapLatestMembers.map((m) => ({ ...m })),
        sgNumber: ws?.draft?.sgNumber ?? null,
      };
    }
    if (title) {
      title.textContent = ws?.draft?.name || ws?.draft?.hub?.city ? `Zone · ${ws.draft.hub.city}` : 'Zone map';
    }
    const mounted = await mountShotgunMap({
      mapHost: host,
      slot,
      api,
      workspace: ws,
      undoScope: `zone:${id}`,
      onHandle: (h) => {
        zoneMapMount = h;
      },
      onPaint: async (city, st, payload) => {
        const prevHubKey = ws?.draft?.hub?.city
          ? shotgunHubKey(ws.draft.hub.city, ws.draft.hub.state)
          : '';
        const result = await api(`/api/shotgun-clusters/${encodeURIComponent(id)}/paint`, {
          method: 'POST',
          body: JSON.stringify({
            city,
            state: st,
            tool: payload?.tool,
            slot: payload?.slot,
            minPop: payload?.minPop,
            maxPop: payload?.maxPop,
            radiusMiles: payload?.radiusMiles,
          }),
        });
        const next = result.workspace || (await api(`/api/shotgun-clusters/${encodeURIComponent(id)}/workspace`));
        zoneMapLatestMembers = next?.draft?.members || zoneMapLatestMembers;
        const nextHubKey = next?.draft?.hub?.city
          ? shotgunHubKey(next.draft.hub.city, next.draft.hub.state)
          : '';
        if (state.shotgunWorkspace?.clusterId === id || state.shotgunWorkspace?.draft?.clusterId === id) {
          state.shotgunWorkspace = { ...state.shotgunWorkspace, ...next, draft: next.draft };
          void renderShotgunWorkspace();
        }
        if (state.selectedId) void loadSelectedCandidateDetail(state.selectedId);
        void loadCandidates();
        if (payload?.tool === 'hub' && nextHubKey && nextHubKey !== prevHubKey) {
          await openZoneMapModal(id, { keepSession: true });
          return;
        }
        zoneMapMount?.setMembers?.(next);
      },
      onPaintMany: async (cities, payload) => {
        const result = await api(`/api/shotgun-clusters/${encodeURIComponent(id)}/paint-many`, {
          method: 'POST',
          body: JSON.stringify({
            cities,
            slot: payload?.slot,
            radiusMiles: payload?.radiusMiles,
          }),
        });
        const next = result.workspace || (await api(`/api/shotgun-clusters/${encodeURIComponent(id)}/workspace`));
        zoneMapLatestMembers = next?.draft?.members || zoneMapLatestMembers;
        if (state.shotgunWorkspace?.clusterId === id || state.shotgunWorkspace?.draft?.clusterId === id) {
          state.shotgunWorkspace = { ...state.shotgunWorkspace, ...next, draft: next.draft };
          void renderShotgunWorkspace();
        }
        if (state.selectedId) void loadSelectedCandidateDetail(state.selectedId);
        void loadCandidates();
        zoneMapMount?.setMembers?.(next);
      },
      onZoneMilesChange: async (miles) => {
        const result = await api(`/api/shotgun-clusters/${encodeURIComponent(id)}/zone-miles`, {
          method: 'POST',
          body: JSON.stringify({ miles }),
        });
        zoneMapMount?.setMembers?.(result.workspace || result);
      },
    });
    zoneMapMount = mounted;
    requestAnimationFrame(() => {
      zoneMapMount?.invalidateSize?.();
      requestAnimationFrame(() => {
        zoneMapMount?.invalidateSize?.();
        if (focusCity) zoneMapMount?.focusCity?.(focusCity, focusState);
      });
    });
  } catch (error) {
    showToast(error.message || 'Zone map failed', { tone: 'warn' });
    zoneMapPrompt = null;
    zoneMapLatestMembers = null;
    closeZoneMapModal({ prompt: false });
  }
}

async function shotgunThisMetro(candidateId) {
  try {
    const result = await api(`/api/candidates/${encodeURIComponent(candidateId)}/shotgun-this-metro`, {
      method: 'POST',
      body: '{}',
    });
    if (result.existing) {
      const gid = result.cluster?.groupId;
      if (gid) {
        state.candidateGroupFilter = gid;
        document.getElementById('candidate-group-filter').value = gid;
        renderList();
      }
      showToast(
        result.cluster?.name
          ? `Already in ${result.cluster.name}`
          : 'Already in a cluster for this niche',
      );
      if (result.batchId) {
        setView('discovery');
        await selectDiscoveryBatch(result.batchId);
      }
      return;
    }
    setDiscoveryPackType('cluster');
    setView('discovery');
    await selectDiscoveryBatch(result.batchId || result.pack?.batch?.id);
    showToast('Cluster pack created — review the map, then Generate pack.');
  } catch (error) {
    await showModal({
      title: 'Cluster this metro',
      confirmLabel: 'OK',
      hideCancel: true,
      bodyHtml: `<p>${esc(error.message)}</p>`,
    });
  }
}

function updateDiscoveryStepChecks(batch, rows) {
  const hasRows = (rows?.length || 0) > 0;
  const serpDone =
    Boolean(batch?.lastSerpProbe) ||
    (hasRows && rows.some((r) => String(r.serp_source || '').includes('dataforseo')));
  const steps = {
    claude: hasRows || Boolean(batch?.files?.lastImport) || Boolean(batch?.rowCount),
    enrich: serpDone,
    decisions: hasRows && rows.some((r) => String(r.human_decision || '').trim() !== ''),
    processed:
      batch?.stage === 'discovery_processed' ||
      Boolean(batch?.lastProcess) ||
      (hasRows && rows.some((r) => isDiscoveryRowProcessed(r))),
  };
  const rail = document.getElementById('discovery-steps');
  rail?.querySelectorAll('.disc-step').forEach((el) => {
    const key = el.dataset.step;
    el.classList.toggle('done', Boolean(steps[key]));
  });

  const packDone =
    Boolean(state.lastDiscoveryPack) ||
    Boolean(batch?.id) ||
    Boolean(state.discoveryBatchId);
  const flowDone = {
    pack: packDone,
    claude: Boolean(state.discoveryClaudeSent) || steps.claude,
    import: steps.claude,
    enrich: serpDone,
  };
  document.querySelectorAll('.discovery-flow-step[data-flow-step]').forEach((el) => {
    const key = el.dataset.flowStep;
    el.classList.toggle('done', Boolean(flowDone[key]));
  });
}

function showDiscoverySidebarStep(step) {
  if (effectiveClaudeUiMode() === 'api' && (step === 'import' || step === 'claude')) {
    step = step === 'claude' ? 'pack' : 'enrich';
  }
  const sections = {
    pack: document.getElementById('discovery-new-pack-section'),
    claude: document.getElementById('discovery-claude-pack-section'),
    import: document.getElementById('discovery-import-section'),
    enrich: document.getElementById('discovery-enrich-section'),
  };
  const nested = shotgunSidebarSurfaceLock;
  shotgunSidebarSurfaceLock = true;
  try {
    for (const [key, el] of Object.entries(sections)) {
      if (!el) continue;
      const isCurrent = key === step;
      el.open = isCurrent;
      el.classList.toggle('current', isCurrent);
    }
    if (nested || !discoveryBatchIsShotgun()) return;
    if (step === 'pack') applyShotgunSurface('hub');
    else if (step === 'enrich') applyShotgunSurface('table');
    else return;
    void renderShotgunWorkspace();
  } finally {
    if (!nested) shotgunSidebarSurfaceLock = false;
  }
}

function wireDiscoveryUi() {
  document.getElementById('sg-map-expand')?.addEventListener('click', () => {
    shotgunMapExpanded = !shotgunMapExpanded;
    applyShotgunMapExpanded();
  });
  document.getElementById('discovery-surface-toggle')?.addEventListener('click', () => {
    if (!discoveryBatchIsShotgun()) return;
    applyShotgunSurface(shotgunSurfaceIsHub() ? 'table' : 'hub');
    void renderShotgunWorkspace();
  });
  document.getElementById('discovery-sidebar-toggle')?.addEventListener('click', () => {
    discoverySidebarCollapsed = !discoverySidebarCollapsed;
    applyDiscoverySidebarCollapsed();
  });
  document.querySelectorAll('.nav-btn').forEach((btn) => {
    btn.addEventListener('click', () => {
      const next = btn.dataset.view;
      if (next && next !== state.view) play('tab');
      setView(next);
      if (btn.dataset.view === 'discovery') {
        loadDiscoveryBatches().catch(() => {});
      }
      if (btn.dataset.view === 'phone') {
        loadPhoneView().catch(() => {});
      }
      if (btn.dataset.view === 'photo') {
        loadPhotoView().catch(() => {});
      }
    });
  });

  showDiscoverySidebarStep('pack');
  syncDiscoveryClaudeModeUi();
  setDiscoveryPackType(state.discoveryPackType);
  renderDiscoveryUpNext();
  document.getElementById('discovery-new-pack-section')?.addEventListener('toggle', () => {
    if (!discoveryBatchIsShotgun()) return;
    const el = document.getElementById('discovery-new-pack-section');
    if (el?.open) showDiscoverySidebarStep('pack');
  });
  document.getElementById('discovery-enrich-section')?.addEventListener('toggle', () => {
    if (!discoveryBatchIsShotgun()) return;
    const el = document.getElementById('discovery-enrich-section');
    if (el?.open) showDiscoverySidebarStep('enrich');
  });
  document.getElementById('discovery-new-pack-section')?.addEventListener('click', (event) => {
    if (event.target.closest('#discovery-generate-pack')) {
      void startGeneratePackFromUi(state.discoveryBatchId);
    }
  });
  document.getElementById('gp-overlay-stop')?.addEventListener('click', async () => {
    const overlay = document.getElementById('discovery-generate-pack-overlay');
    const jobId =
      overlay?.dataset.jobId || state._generatePackTrack?.jobId || state._shotgunJobTrack?.jobId;
    if (!jobId) return;
    const btn = document.getElementById('gp-overlay-stop');
    if (btn) btn.disabled = true;
    const detailEl = document.getElementById('gp-overlay-detail');
    if (detailEl) detailEl.textContent = 'Stopping…';
    try {
      await api(`/api/light-jobs/${encodeURIComponent(jobId)}/cancel`, { method: 'POST' });
    } catch (error) {
      if (btn) btn.disabled = false;
      await showModal({
        title: 'Could not stop',
        confirmLabel: 'OK',
        hideCancel: true,
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });
  wireSitesUi();
  wirePhoneUi();
  wirePhotoUi();
  wireImageZoom();

  document.getElementById('discovery-batch-select')?.addEventListener('change', (event) => {
    const id = event.target.value;
    if (id) selectDiscoveryBatch(id).catch(() => {});
    else clearDiscoveryBatch();
  });

  document.getElementById('discovery-pack-scout')?.addEventListener('click', () => {
    setDiscoveryPackType('single');
  });
  document.getElementById('discovery-pack-shotgun')?.addEventListener('click', () => {
    setDiscoveryPackType('cluster');
  });
  document.getElementById('discovery-reuse-zone')?.addEventListener('change', () => {
    syncReuseZoneFields();
  });
  document.getElementById('discovery-form').addEventListener('submit', async (event) => {
    event.preventDefault();
    const fd = new FormData(event.target);
    const niches = [
      ...event.target.querySelectorAll('input[name="niche"]:checked'),
    ].map((el) => el.value);
    for (const n of parseDiscoveryNicheList(fd.get('suggestedNiches'))) {
      if (!niches.some((x) => String(x).toLowerCase() === n.toLowerCase())) niches.push(n);
    }
    const requiredNiches = parseDiscoveryNicheList(fd.get('requiredNiches'));
    if (isClusterPackType(state.discoveryPackType)) {
      const niche = String(fd.get('shotgunNiche') || '').trim();
      if (!niche) {
        await showModal({
          title: 'Cluster niche required',
          confirmLabel: 'OK',
          hideCancel: true,
          bodyHtml: '<p>Cluster Cities is one niche × one metro. Enter the niche first.</p>',
        });
        return;
      }
      requiredNiches.length = 0;
      requiredNiches.push(niche);
      niches.length = 0;
    }
    const regions = collectDiscoveryPackRegions();
    const cities = regions.flatMap((r) => r.cities);
    const reuseZoneId = isClusterPackType(state.discoveryPackType)
      ? String(fd.get('reuseZoneId') || '').trim()
      : '';
    try {
      const pack = await api('/api/discovery/pack', {
        method: 'POST',
        body: JSON.stringify({
          state: reuseZoneId ? '' : regions[0]?.state || '',
          regions: reuseZoneId ? [] : regions,
          niches,
          requiredNiches,
          cities: reuseZoneId ? [] : cities,
          reuseZoneId,
          categories: [...event.target.querySelectorAll('input[name="category"]:checked')].map(
            (el) => el.value,
          ),
          minPopulation: Number(fd.get('minPopulation')) || 70000,
          maxPopulation: Number(fd.get('maxPopulation')) || 200000,
          maxRows: Number(fd.get('maxRows')) || 40,
          seasonality: String(fd.get('seasonality') || 'year_round'),
          tiers: [...event.target.querySelectorAll('input[name="tier"]:checked')].map(
            (el) => el.value,
          ),
          minJobCost: fd.get('minJobCost') ? Number(fd.get('minJobCost')) : null,
          mapPackPreference: String(fd.get('mapPackPreference') || 'prefer_absent'),
          packType: state.discoveryPackType,
          shotgunNiche: String(fd.get('shotgunNiche') || requiredNiches[0] || '').trim(),
          clusterMiles: Number(fd.get('clusterMiles')) || 30,
          innerMiles: Number(fd.get('clusterMiles')) || 30,
          outerMiles: Number(fd.get('clusterMiles')) || 30,
          shotgunBands: {
            hub: {
              min: Number(fd.get('hubMinPop')) || 60000,
              max: Number(fd.get('hubMaxPop')) || 200000,
            },
            cities: {
              min: Number(fd.get('citiesMinPop')) || 2000,
              max: Number(fd.get('citiesMaxPop')) || 60000,
            },
          },
        }),
      });
      state.lastDiscoveryPack = pack;
      state.discoveryBatchId = pack.batch.id;
      if (pack.existing) {
        const zn = formatZnDisplay(pack.cluster?.sgNumber);
        showToast(
          zn
            ? `${zn} already covers this niche on this hub`
            : 'This niche already has a zone on this hub',
        );
      }
      state.discoveryClaudeSent = false;
      updateDiscoveryStepChecks(pack.batch, state.discoveryRows);
      await loadDiscoveryBatches();
      await selectDiscoveryBatch(pack.batch.id);
      if (isClusterPackType(state.discoveryPackType)) {
        if (effectiveClaudeUiMode() === 'api') {
          renderShotgunApiButtons();
        } else {
          renderShotgunPasteSteps();
          showDiscoverySidebarStep('claude');
        }
      } else if (effectiveClaudeUiMode() === 'api') {
        syncDiscoveryApiRerunButton();
        await startGeneratePackFromUi(pack.batch.id);
      } else {
        const box = document.getElementById('discovery-pack-result');
        const empty = document.getElementById('discovery-pack-empty');
        if (empty) empty.classList.add('hidden');
        box.classList.remove('hidden');
        box.innerHTML = `
        <ol class="discovery-pack-next">
          <li><button type="button" class="btn primary" id="dl-discovery-csv">Download Discovery Pack Template</button></li>
          <li><button type="button" class="btn" id="copy-discovery-claude">Copy Claude Prompt</button></li>
          <li>Paste both in <a href="https://claude.ai" target="_blank" rel="noopener noreferrer">Claude.ai</a></li>
        </ol>
      `;
        document.getElementById('dl-discovery-csv').onclick = () =>
          downloadText(pack.csvName || 'discovery.csv', pack.csv, 'text/csv');
        const markClaudeSent = () => {
          state.discoveryClaudeSent = true;
          updateDiscoveryStepChecks(pack.batch, state.discoveryRows);
          showDiscoverySidebarStep('import');
        };
        document.getElementById('copy-discovery-claude').onclick = async () => {
          await navigator.clipboard.writeText(pack.claudePrompt);
          showToast('Claude prompt copied to clipboard.');
        };
        box.querySelector('a[href="https://claude.ai"]')?.addEventListener('click', () => {
          markClaudeSent();
        });
        showDiscoverySidebarStep('claude');
      }
    } catch (error) {
      await showModal({
        title: 'Discovery pack failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });

  document.getElementById('discovery-upload-file').addEventListener('change', async (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const text = await file.text();
    document.getElementById('discovery-upload-text').value = text;
  });

  document.getElementById('discovery-import-btn').addEventListener('click', async () => {
    const csv = document.getElementById('discovery-upload-text').value;
    if (!csv.trim()) {
      await showModal({
        title: 'Nothing to import',
        confirmLabel: 'OK',
        bodyHtml: '<p>Paste or choose a Claude CSV file first.</p>',
      });
      return;
    }
    try {
      const result = await api('/api/discovery/import', {
        method: 'POST',
        body: JSON.stringify({
          csv,
          batchId: state.discoveryBatchId || null,
          role: 'claude',
        }),
      });
      state.lastDiscoveryPack = {
        ...(state.lastDiscoveryPack || {}),
        batch: result.batch,
      };
      await loadDiscoveryBatches();
      await selectDiscoveryBatch(result.batch.id);
      showDiscoverySidebarStep('enrich');
      const warns = result.batch.popBandWarnings || [];
      const warnHtml = warns.length
        ? `<p class="muted">${esc(String(warns.length))} row(s) outside preferred pop band.</p>`
        : '';
      await showModal({
        title: 'Claude CSV imported',
        confirmLabel: 'OK',
        bodyHtml: `<p>Loaded <strong>${esc(String(result.rows.length))}</strong> rows. Next: set a decision on each row, then <strong>Process batch</strong>. Light SERP is optional.</p>${warnHtml}`,
      });
    } catch (error) {
      await showModal({
        title: 'Import failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });

  document.getElementById('discovery-enrich-pack-btn')?.addEventListener('click', () =>
    runDiscoverySerpProbeUi(),
  );

  async function runDiscoverySerpProbeUi() {
    if (!state.discoveryBatchId) {
      await showModal({
        title: 'No batch',
        confirmLabel: 'OK',
        bodyHtml: discoveryBatchIsShotgun()
          ? '<p>Create a Cluster pack, select a hub, then Generate pack.</p>'
          : '<p>Select a batch and import Claude CSV first.</p>',
      });
      return;
    }
    if (!(state.discoveryRows || []).length) {
      await showModal({
        title: 'No rows yet',
        confirmLabel: 'OK',
        bodyHtml: discoveryBatchIsShotgun()
          ? '<p>Generate a pack from the selected hub first. That creates the rows for the search check.</p>'
          : '<p>Import a sheet, or generate a pack, first.</p>',
      });
      return;
    }
    const progress = document.getElementById('discovery-probe-progress');
    const bar = document.getElementById('discovery-probe-bar');
    const labelEl = document.getElementById('discovery-probe-label');
    const detailEl = document.getElementById('discovery-probe-detail');
    const indices = [...(state.discoverySelected || [])]
      .map((n) => Number(n))
      .filter((n) => Number.isFinite(n));
    const scopedIndices = indices.length ? indices : null;
    showDiscoverySidebarStep('enrich');
    try {
      const previewQs = scopedIndices
        ? `?indices=${scopedIndices.map((n) => encodeURIComponent(String(n))).join(',')}`
        : '';
      const preview = await api(
        `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/serp-probe/preview${previewQs}`,
      );
      if (!preview.hasDataForSeo) {
        await showModal({
          title: 'DataForSEO required',
          confirmLabel: 'OK',
          bodyHtml:
            '<p>Add <code>DATAFORSEO_LOGIN</code> / <code>DATAFORSEO_PASSWORD</code> to <code>.env</code> to run Discovery Light SERP.</p>',
        });
        return;
      }
      const bal =
        state.dfsBalance?.ok && state.dfsBalance.balance != null
          ? `<p class="muted">DFS balance: ${esc(formatMoney(state.dfsBalance.balance))}</p>`
          : '';
      const ok = await showModal({
        title: 'Run Discovery Light SERP?',
        confirmLabel: preview.confirmLabel || 'Probe',
        bodyHtml: `
          <p>${esc(preview.estimateLabel || '')}</p>
          <p class="muted">${esc(preview.estimateDetail || '')}</p>
          ${bal}
          <p class="muted">Overwrites Map Pack + organic/directory counts, then re-runs Recommend.</p>
        `,
      });
      if (!ok) return;
      const enrichBtn = document.getElementById('discovery-enrich-pack-btn');
      if (enrichBtn) enrichBtn.disabled = true;
      if (progress) progress.classList.remove('hidden');
      setDeterminateProgress(bar, { done: 0, total: preview.probeCount });
      if (labelEl) labelEl.textContent = 'Starting Light SERP…';
      if (detailEl) detailEl.textContent = `0 / ${preview.probeCount}`;

      const started = await api(
        `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/serp-probe`,
        {
          method: 'POST',
          body: JSON.stringify({
            ...(scopedIndices ? { indices: scopedIndices } : {}),
          }),
        },
      );
      const jobId = started.jobId;
      if (!jobId) throw new Error('Probe did not return a job id');
      play('job');

      await new Promise((resolve, reject) => {
        const tick = async () => {
          try {
            const job = await api(`/api/discovery/serp-probe-jobs/${encodeURIComponent(jobId)}`);
            setDeterminateProgress(bar, { done: job.done || 0, total: job.total });
            if (labelEl) {
              labelEl.textContent =
                job.status === 'running'
                  ? `Probing ${job.done || 0} / ${job.total}`
                  : `Probe ${job.status}`;
            }
            if (detailEl) {
              detailEl.textContent = job.currentLabel
                ? job.currentLabel
                : `ok ${job.ok || 0} · errors ${job.errors || 0} · ${formatMoney(job.costUsd || 0)}`;
            }
            if (job.status === 'running') {
              setTimeout(tick, 400);
              return;
            }
            resolve(job);
          } catch (error) {
            reject(error);
          }
        };
        tick();
      }).then(async (job) => {
        await loadDiscoveryBatches();
        await selectDiscoveryBatch(job.batchId || state.discoveryBatchId);
        setDeterminateProgress(bar, {});
        if (progress) progress.classList.add('hidden');
        const p = job.probe || job;
        const payErr =
          isDataForSeoPaymentError(job.error) ||
          (Array.isArray(job.results) && job.results.some((r) => isDataForSeoPaymentError(r.error))) ||
          (Array.isArray(p.results) && p.results.some((r) => isDataForSeoPaymentError(r.error)));
        if (payErr) {
          announceBanner('DataForSEO needs funds — add credit, then retry Light SERP.', {
            tone: 'err',
          });
        } else if (job.status === 'error') {
          announceBanner('Light SERP failed', { tone: 'err' });
        } else {
          announceStepComplete('Light SERP');
        }
        if (payErr) {
          await showModal({
            title: 'DataForSEO needs funds',
            confirmLabel: 'OK',
            bodyHtml: dataForSeoPaymentHelpHtml({
              failedCount: Number(p.errors ?? job.errors) || 0,
              createdOk: false,
            }),
          });
        } else {
          await showModal({
            title: 'Light SERP complete',
            confirmLabel: 'OK',
            bodyHtml: `<p>Probed <strong>${esc(String(p.probed || job.total || 0))}</strong> · ok ${esc(
              String(p.ok ?? job.ok ?? 0),
            )} · errors ${esc(String(p.errors ?? job.errors ?? 0))}</p>
          <p>Map Pack Yes ${esc(String(p.mapPackYes ?? job.mapPackYes ?? 0))} · No ${esc(
              String(p.mapPackNo ?? job.mapPackNo ?? 0),
            )} · flips to Yes ${esc(String(p.flipsToYes ?? job.flipsToYes ?? 0))} · flips to No ${esc(
              String(p.flipsToNo ?? job.flipsToNo ?? 0),
            )}</p>
          <p><strong>Cost:</strong> ${
            (p.costUsd ?? job.costUsd) != null
              ? esc(formatMoney(p.costUsd ?? job.costUsd))
              : '—'
          }</p>`,
          });
        }
        showDiscoverySidebarStep(null);
        await loadDfsBalance();
      });
    } catch (error) {
      setDeterminateProgress(bar, {});
      if (progress) progress.classList.add('hidden');
      if (error.code === 'LIGHT_SERP_CONCURRENCY') {
        await explainConcurrencyLimit({
          key: 'lightSerp',
          running: error.running,
          limit: error.limit ?? state.concurrency?.lightSerp ?? 2,
        });
      } else {
        await showModal({
          title: isDataForSeoPaymentError(error.message)
            ? 'DataForSEO needs funds'
            : 'Light SERP failed',
          confirmLabel: 'OK',
          bodyHtml: isDataForSeoPaymentError(error.message)
            ? dataForSeoPaymentHelpHtml({ createdOk: false })
            : `<p>${esc(error.message)}</p>`,
        });
      }
    } finally {
      const progress = document.getElementById('discovery-probe-progress');
      if (progress) progress.classList.add('hidden');
      syncDiscoveryLightSerpButton();
    }
  }

  document.getElementById('discovery-accept-selected')?.addEventListener('click', async () => {
    await acceptDiscoveryIndices([...state.discoverySelected]);
  });
  document.getElementById('discovery-accept-all')?.addEventListener('click', async () => {
    const view = getDiscoveryViewRows();
    const indices = view
      .filter(({ row }) => row.recommended_decision)
      .map(({ index }) => index);
    if (!indices.length) {
      await showModal({
        title: 'Nothing to accept',
        confirmLabel: 'OK',
        bodyHtml: '<p>No recommended decisions on the visible rows.</p>',
      });
      return;
    }
    const ok = await showModal({
      title: 'Accept all recommendations?',
      confirmLabel: `Accept ${indices.length}`,
      bodyHtml: `<p>Use the suggestion for <strong>${esc(
        String(indices.length),
      )}</strong> visible row(s) (respects current filters).</p>`,
    });
    if (!ok) return;
    await acceptDiscoveryIndices(indices);
    updateDiscoveryStepChecks(
      state.discoveryBatches.find((b) => b.id === state.discoveryBatchId) || { id: state.discoveryBatchId },
      state.discoveryRows,
    );
  });

  const discoveryTbody = document.querySelector('#discovery-table tbody');
  discoveryTbody?.addEventListener('change', (e) => {
    const el = e.target;
    if (!(el instanceof HTMLSelectElement)) return;
    if (el.dataset.field !== 'human_decision') return;
    const idx = Number(el.dataset.idx);
    if (!Number.isFinite(idx)) return;
    void persistDiscoveryRowFromDom(idx);
  });

  document.getElementById('discovery-bulk-human')?.addEventListener('change', async (e) => {
    const sel = e.target;
    if (!(sel instanceof HTMLSelectElement)) return;
    const raw = sel.value;
    if (!raw) return;
    const human_decision = raw === '__clear' ? '' : raw;
    if (human_decision && !DISCOVERY_DECISION_OPTS.includes(human_decision)) {
      sel.value = '';
      return;
    }
    const selected = [...(state.discoverySelected || [])]
      .map((n) => Number(n))
      .filter((n) => Number.isFinite(n));
    const editable = selected.filter((idx) => {
      const row = state.discoveryRows[idx];
      return row && !isDiscoveryRowProcessed(row);
    });
    if (!editable.length) {
      sel.value = '';
      await showModal({
        title: 'Nothing to update',
        confirmLabel: 'OK',
        hideCancel: true,
        bodyHtml:
          '<p>Selected rows are already processed, tracked, or ignored. Reopen them first, or select editable rows.</p>',
      });
      return;
    }
    const updates = editable.map((idx) => {
      const fromDom = discoveryDecisionUpdateFromDom(idx);
      return {
        index: idx,
        human_decision,
        decision_notes: fromDom?.decision_notes ?? state.discoveryRows[idx]?.decision_notes ?? '',
      };
    });
    try {
      await persistDiscoveryDecisions(updates);
      updateDiscoveryStepChecks(
        state.discoveryBatches.find((b) => b.id === state.discoveryBatchId) || {
          id: state.discoveryBatchId,
        },
        state.discoveryRows,
      );
      updateDiscoveryProcessControls();
      renderDiscoveryTable();
    } catch (error) {
      await showModal({
        title: 'Save failed',
        confirmLabel: 'OK',
        hideCancel: true,
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    } finally {
      sel.value = '';
    }
  });
  discoveryTbody?.addEventListener('input', (e) => {
    const el = e.target;
    if (!(el instanceof HTMLInputElement)) return;
    if (el.dataset.field !== 'decision_notes') return;
    const idx = Number(el.dataset.idx);
    if (!Number.isFinite(idx)) return;
    scheduleDiscoveryNotesAutosave(idx);
  });
  discoveryTbody?.addEventListener(
    'blur',
    (e) => {
      const el = e.target;
      if (!(el instanceof HTMLInputElement)) return;
      if (el.dataset.field !== 'decision_notes') return;
      const idx = Number(el.dataset.idx);
      if (!Number.isFinite(idx)) return;
      void flushDiscoveryNotesAutosave(idx);
    },
    true,
  );

  const bindFilter = (id, key) => {
    document.getElementById(id)?.addEventListener('input', (e) => {
      state.discoveryFilters[key] = e.target.value;
      renderDiscoveryTable();
      persistUiRestore();
    });
    document.getElementById(id)?.addEventListener('change', (e) => {
      state.discoveryFilters[key] = e.target.value;
      renderDiscoveryTable();
      persistUiRestore();
    });
  };
  bindFilter('discovery-filter-text', 'text');
  bindFilter('discovery-filter-human', 'human');
  bindFilter('discovery-filter-rec', 'rec');
  bindFilter('discovery-filter-mappack', 'mapPack');
  bindFilter('discovery-filter-role', 'role');

  document.getElementById('discovery-reopen-selected')?.addEventListener('click', async () => {
    const indices = [...state.discoverySelected].filter((idx) =>
      isDiscoveryRowProcessed(state.discoveryRows[idx]),
    );
    if (!indices.length) {
      await showModal({
        title: 'Nothing to reopen',
        confirmLabel: 'OK',
        bodyHtml: '<p>Select processed, tracked, or ignored rows first.</p>',
      });
      return;
    }
    const ok = await showModal({
      title: 'Reopen selected rows?',
      confirmLabel: `Reopen ${indices.length}`,
      bodyHtml:
        '<p>Clears processed/tracked/ignored markers so you can change Decision and Process again. Existing Candidate files are kept.</p>',
    });
    if (!ok) return;
    await reopenDiscoveryIndices(indices);
  });

  document.getElementById('discovery-backfill-light-serp')?.addEventListener('click', async () => {
    if (!state.discoveryBatchId) return;
    const btn = document.getElementById('discovery-backfill-light-serp');
    if (btn) btn.disabled = true;
    try {
      const result = await api(
        `/api/discovery/batches/${encodeURIComponent(state.discoveryBatchId)}/backfill-light-serp`,
        { method: 'POST', body: JSON.stringify({}) },
      );
      await loadCandidates();
      await showModal({
        title: 'Light SERP backfill complete',
        confirmLabel: 'OK',
        hideCancel: true,
        bodyHtml: `<p>Updated <strong>${esc(String(result.updatedCount ?? 0))}</strong> Candidate seed(s).</p>
          <p class="muted">Skipped ${esc(String(result.skippedCount ?? 0))} (no Light SERP columns) · missing Candidate ${esc(
            String(result.missingCount ?? 0),
          )}.</p>
          <p>Open <strong>Research</strong> — Map Pack / Homepages / Subpages should show from Discovery until you run Eval 1 · SERP / Volume.</p>`,
      });
    } catch (error) {
      await showModal({
        title: 'Backfill failed',
        confirmLabel: 'OK',
        hideCancel: true,
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    } finally {
      updateDiscoveryProcessControls();
    }
  });

  document.getElementById('discovery-known-open')?.addEventListener('click', async () => {
    try {
      await enterDiscoveryKnownMode();
    } catch (error) {
      await showModal({
        title: 'Could not load anti-dupe list',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });

  document.getElementById('discovery-known-back')?.addEventListener('click', () => {
    exitDiscoveryKnownMode();
  });

  document.getElementById('discovery-known-remove')?.addEventListener('click', async () => {
    const keys = [...state.discoveryKnownSelected];
    if (!keys.length) return;
    const selectedRows = state.discoveryKnownRows.filter((r) =>
      keys.includes(discoveryKnownRowKey(r)),
    );
    const candN = selectedRows.filter((r) => r.source === 'candidate').length;
    const trackedN = selectedRows.length - candN;
    const ok = await showModal({
      title: 'Remove from do-not-repropose?',
      confirmLabel: `Remove ${selectedRows.length}`,
      bodyHtml: `<p>Remove <strong>${esc(String(selectedRows.length))}</strong> selected pair(s).</p>
        <ul>
          <li><strong>${esc(String(candN))}</strong> Candidate — permanently deleted from Research</li>
          <li><strong>${esc(String(trackedN))}</strong> Tracked-only — unblocked for Claude</li>
        </ul>`,
    });
    if (!ok) return;
    try {
      const result = await api('/api/discovery/known/remove', {
        method: 'POST',
        body: JSON.stringify({
          keys: selectedRows.map((r) => ({ niche: r.niche, city: r.city, state: r.state })),
        }),
      });
      state.discoveryKnownRows = Array.isArray(result.rows) ? result.rows : [];
      state.discoveryKnownSelected = new Set();
      state.discoveryKnownCheckAnchor = null;
      const sub = document.getElementById('discovery-known-sub');
      if (sub) {
        const n = state.discoveryKnownRows.length;
        const cand = state.discoveryKnownRows.filter((r) => r.source === 'candidate').length;
        sub.textContent = `${n} pairs · ${cand} Candidate · ${n - cand} Tracked`;
      }
      await loadCandidates();
      renderDiscoveryTable();
    } catch (error) {
      await showModal({
        title: 'Remove failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });

  document.getElementById('discovery-known-prune')?.addEventListener('click', async () => {
    try {
      const data = await api('/api/discovery/known');
      const p = data.prunePreview || {};
      const ok = await showModal({
        title: 'Wipe do-not-repropose to Active Research?',
        confirmLabel: 'Wipe',
        bodyHtml: `<p>Keep <strong>${esc(String(p.keepCount ?? 0))}</strong> Active Candidates.</p>
          <ul>
            <li>Permanently delete <strong>${esc(String(p.archivedDeleteCount ?? 0))}</strong> archived / orphan Candidate id(s)</li>
            <li>Skip <strong>${esc(String(p.archivedProtectedCount ?? 0))}</strong> archived Launched (never deleted)</li>
            <li>Drop <strong>${esc(String(p.trackedDropCount ?? 0))}</strong> tracked-only pair(s) outside Active</li>
          </ul>
          <p class="muted">Generate pack will use this shorter list and will not suggest the removed pairs again.</p>`,
      });
      if (!ok) return;
      const result = await api('/api/discovery/known/prune-to-active', { method: 'POST', body: '{}' });
      await loadCandidates();
      if (state.discoveryKnownMode) {
        state.discoveryKnownRows = Array.isArray(result.rows) ? result.rows : [];
        state.discoveryKnownSelected = new Set();
        state.discoveryKnownCheckAnchor = null;
        const sub = document.getElementById('discovery-known-sub');
        if (sub) {
          const n = state.discoveryKnownRows.length;
          const cand = state.discoveryKnownRows.filter((r) => r.source === 'candidate').length;
          sub.textContent = `${n} pairs · ${cand} Candidate · ${n - cand} Tracked`;
        }
        renderDiscoveryTable();
      }
      await showModal({
        title: 'Wipe complete',
        confirmLabel: 'OK',
        bodyHtml: `<p>Kept <strong>${esc(String(result.keepCount ?? 0))}</strong> Active.
          Deleted <strong>${esc(String(result.archivedDeleted ?? 0))}</strong> archived/orphan.
          Dropped <strong>${esc(String(result.trackedDropped ?? 0))}</strong> tracked.
          Known list now <strong>${esc(String(result.knownCount ?? 0))}</strong>.</p>`,
      });
    } catch (error) {
      await showModal({
        title: 'Wipe failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });

  document.getElementById('discovery-process-btn')?.addEventListener('click', async () => {
    if (!state.discoveryBatchId) return;
    // Flush any pending notes timers, then persist all DOM edits
    for (const timer of discoveryNotesSaveTimers.values()) clearTimeout(timer);
    discoveryNotesSaveTimers.clear();
    const updates = state.discoveryRows
      .map((_, idx) => discoveryDecisionUpdateFromDom(idx))
      .filter(Boolean);
    await persistDiscoveryDecisions(updates);

    const withDecision = state.discoveryRows.filter(isDiscoveryRowPendingProcess);
    const alreadyCount = state.discoveryRows.filter(isDiscoveryRowProcessed).length;
    const pursueCount = withDecision.filter((r) => r.human_decision === 'pursue').length;
    const promoteCount = withDecision.filter((r) =>
      ['pursue', 'maybe', 'review', 'hold'].includes(r.human_decision),
    ).length;
    const trackCount = withDecision.filter((r) => r.human_decision === 'pass').length;
    const ignoreCount = withDecision.filter((r) => r.human_decision === 'ignore').length;
    if (!withDecision.length) {
      await showModal({
        title: 'Nothing to process',
        confirmLabel: 'OK',
        bodyHtml: alreadyCount
          ? '<p>All decided rows are already processed. Set decisions on remaining rows, Reopen tracked/ignored rows, or open Candidates.</p>'
          : '<p>Set Decisions (or Accept recommendations) first.</p>',
      });
      return;
    }
    const evalRunMode = getEvalRunMode();
    const estLow = (pursueCount * 0.2).toFixed(2);
    const estHigh = (pursueCount * 1.5).toFixed(2);
    const adsMode = getAdsMode();
    const adsLine =
      pursueCount > 0 && evalRunMode === 'all'
        ? `<p><strong>Search volumes:</strong> ${
            adsMode === 'standard'
              ? 'Standard queue (cheaper, slower — overnight is fine)'
              : 'Live (faster)'
          }. Change this on Research, next to Ad volumes.</p>`
        : pursueCount > 0
          ? `<p>Search volumes are not started. On Research, run the required steps: a search snapshot, then the written story.</p>`
          : '';
    const ok = await showModal({
      title: 'Process discovery batch?',
      confirmLabel:
        pursueCount && evalRunMode === 'all'
          ? `Process + SERP / Volume (${pursueCount} pursue)`
          : 'Process',
      bodyHtml: `<p><strong>${esc(String(promoteCount))}</strong> → Candidates · <strong>${esc(
        String(trackCount),
      )}</strong> tracked (pass) · <strong>${esc(String(ignoreCount))}</strong> ignored · already done ${esc(
        String(alreadyCount),
      )}.</p>
        ${
          pursueCount && evalRunMode === 'all'
            ? `<p><strong>Pursue → SERP / Volume:</strong> ${esc(String(pursueCount))} · est. $${esc(estLow)}–$${esc(estHigh)} DFS</p>`
            : pursueCount
              ? `<p><strong>Pursue → Research Candidates:</strong> ${esc(String(pursueCount))} (no auto Ads)</p>`
              : ''
        }
        ${adsLine}
        <p class="muted">Pass is remembered and will not be suggested again. Ignore can come back.</p>`,
    });
    if (!ok) return;
    const processDetail = document.getElementById('dp-overlay-detail');
    if (processDetail) {
      const pending = withDecision.length;
      processDetail.textContent =
        pursueCount && evalRunMode === 'all'
          ? `Creating candidates (${pending})… SERP / Volume starts after candidates are created.`
          : `Creating candidates (${pending})…`;
    }
    setRoverJobOverlayVisible('discovery-process-overlay', true);
    await new Promise((resolve) => {
      requestAnimationFrame(() => requestAnimationFrame(resolve));
    });
    let result;
    let processError = null;
    try {
      const batchId = state.discoveryBatchId;
      result = await api(
        `/api/discovery/batches/${encodeURIComponent(batchId)}/process`,
        {
          method: 'POST',
          body: JSON.stringify({
          runStage1ForPursue: getEvalRunMode() === 'all',
          evalRunMode: getEvalRunMode(),
          concurrency: 1,
          adsMode,
        }),
        },
      );
    } catch (error) {
      processError = error;
    } finally {
      setRoverJobOverlayVisible('discovery-process-overlay', false);
    }
    if (processError) {
      await showModal({
        title: 'Process failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(processError.message)}</p>`,
      });
      return;
    }
    try {
      const batchId = state.discoveryBatchId;
      state.discoveryRows = result.rows;
      renderDiscoveryTable();
      await loadCandidates();
      await loadDiscoveryBatches();
      if (result.batchJob?.id) {
        state.activeBatchJobId = result.batchJob.id;
        state.activeAct = 'research';
        pollBatchJob(result.batchJob.id);
      }
      const alreadySkipped = (result.skipped || []).filter(
        (s) => s.reason === 'already processed',
      ).length;
      const fullyDone =
        (result.rows || []).length > 0 &&
        (result.rows || []).every((r) => isDiscoveryRowProcessed(r));
      const openCandidates =
        fullyDone && (result.promoted?.length || 0) > 0;
      const promotedN = result.promoted?.length || 0;
      const trackedN = result.tracked?.length || 0;
      const ignoredN = result.ignored?.length || 0;
      const pursueN = result.pursueIds?.length || 0;
      const linkedN = (result.promoted || []).filter((p) => p.linkedExisting).length;
      const adsQueued = evalRunMode === 'all' && pursueN > 0;
      const nextSentence = adsQueued
        ? ` Search volumes were queued for ${pursueN} pursue.`
        : promotedN > 0
          ? ' Open Research and run the required steps: a search snapshot, then the written story.'
          : '';
      await showModal({
        title: fullyDone ? 'Batch fully processed' : 'Batch processed',
        confirmLabel: openCandidates ? 'Open Research' : 'OK',
        bodyHtml: `<p><strong>${esc(String(promotedN))}</strong> new candidates. <strong>${esc(
          String(trackedN),
        )}</strong> tracked (pass). <strong>${esc(
          String(ignoredN),
        )}</strong> ignored. <strong>${esc(String(result.skipped?.length || 0))}</strong> skipped${
          alreadySkipped
            ? ` (${esc(String(alreadySkipped))} already processed)`
            : ''
        }.${nextSentence}${
          linkedN
            ? ` ${esc(String(linkedN))} linked to candidates that already exist.`
            : ''
        }</p><p class="muted">${
          openCandidates
            ? 'Opening Research, filtered to this batch.'
            : 'Pass is remembered and will not be suggested again. Ignore can come back. Reopen a row to change your mind.'
        }</p>`,
      });
      updateDiscoveryStepChecks(result.batch, result.rows);
      if (openCandidates) {
        state.candidateBatchFilter = batchId;
        fillCandidateBatchFilterSelect();
        setView('research');
        renderList();
        renderActions();
      }
    } catch (error) {
      await showModal({
        title: 'Process failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  });
}

async function pollBatchJob(batchJobId) {
  const progress = document.getElementById('job-progress');
  const detailEl = document.getElementById('job-progress-detail');
  const bar = progress?.querySelector('.job-progress-bar');
  if (progress) progress.classList.remove('hidden');
  const tick = async () => {
    try {
      const batch = await api(`/api/jobs/batches/${encodeURIComponent(batchJobId)}`);
      state.lastBatchJob = batch;
      const total = batch.children?.length || 0;
      const done = (batch.done || 0) + (batch.failed || 0);
      setDeterminateProgress(bar, { done, total });
      const failBits = (batch.children || [])
        .filter((c) => c.status === 'error')
        .slice(0, 2)
        .map((c) => `${c.candidateId}: ${c.error || 'error'}`)
        .join(' · ');
      if (detailEl) {
        const stepBits = (batch.children || [])
          .filter((c) => c.status === 'running' && c.step)
          .slice(0, 2)
          .map((c) => `${c.candidateId}: ${jobActLabel(c.step)}`)
          .join(' · ');
        detailEl.textContent = `${jobActLabel(batch.act)}: ${done}/${total} finished · ${
          batch.running || 0
        } running · ${batch.pending || 0} queued${stepBits ? ` · ${stepBits}` : ''}${
          failBits ? ` · ${failBits}` : ''
        }`;
      }
      state.jobStatusLine = detailEl?.textContent || '';
      if (state.selectedIds.size > 1) renderMultiDetail();
      if (batch.status === 'running') {
        state.pollTimer = setTimeout(tick, 800);
        return;
      }
      state.activeBatchJobId = null;
      state.activeAct = null;
      setDeterminateProgress(bar, {});
      if (progress) progress.classList.add('hidden');
      const failedKids = (batch.children || []).filter((c) => c.status === 'error');
      const payFail = failedKids.some((c) => isDataForSeoPaymentError(c.error));
      if (batch.status === 'ok' || batch.status === 'done') {
        announceStepComplete(`Batch ${jobActLabel(batch.act)}`);
      } else {
        announceBanner(
          payFail
            ? 'DataForSEO needs funds — add credit, then retry SERP / Volume.'
            : `Batch ${jobActLabel(batch.act)} failed`,
          { tone: 'err' },
        );
      }
      await loadCandidates();
      if (state.selectedIds.size > 1) renderMultiDetail();
      else if (state.selectedId) {
        await loadSelectedCandidateDetail(state.selectedId);
        renderDetail();
      }
      renderActions();
      if (payFail) {
        await showModal({
          title: 'DataForSEO needs funds',
          confirmLabel: 'OK',
          bodyHtml: `<p>Status: <strong>${esc(batch.status)}</strong> · ok ${esc(
            String(batch.done),
          )} · failed ${esc(String(batch.failed))}</p>${dataForSeoPaymentHelpHtml({
            failedCount: failedKids.length,
            createdOk: true,
          })}`,
        });
      } else {
        const failList = failedKids
          .slice(0, 8)
          .map((c) => `<li>${esc(c.candidateId)}: ${esc(c.error || 'error')}</li>`)
          .join('');
        await showModal({
          title: 'Batch jobs finished',
          confirmLabel: 'OK',
          bodyHtml: `<p>Status: <strong>${esc(batch.status)}</strong> · ok ${esc(
            String(batch.done),
          )} · failed ${esc(String(batch.failed))}</p>${
            failList ? `<ul>${failList}</ul>` : ''
          }`,
        });
      }
    } catch (error) {
      state.activeBatchJobId = null;
      setDeterminateProgress(bar, {});
      if (progress) progress.classList.add('hidden');
      await showModal({
        title: 'Batch poll failed',
        confirmLabel: 'OK',
        bodyHtml: `<p>${esc(error.message)}</p>`,
      });
    }
  };
  tick();
}

if (!document.getElementById('app-boot-loading')?.classList.contains('hidden')) {
  noteTabWorking('boot', true);
}

try {
  await loadHealth();
  void loadApiCost();
  startBalancePolling();
  await loadRubric();
  wireSettingsUi();
  wireApiCostUi();
  wireJobsUi();
  wireHelpUi();
  await loadConcurrencySettings();
  wireUi();
  syncClaudeModeToggle();
  renderDiscoverySourceLegend();
  const deepLink = readWebsiteCandidateLink();
  const claudePeek = peekClaudeUiRestore();
  const uiPeek = peekUiRestore();
  applyUiFilterSnapshot(uiPeek);
  if (deepLink?.candidate) state.tab = 'site-config';
  else if (claudePeek?.tab) state.tab = claudePeek.tab;
  const restoreView = deepLink?.candidate
    ? 'website-builder'
    : CLAUDE_UI_VIEWS.has(claudePeek?.view)
      ? claudePeek.view
      : CLAUDE_UI_VIEWS.has(uiPeek?.view)
        ? uiPeek.view
        : 'discovery';
  setView(restoreView);
  try {
    await loadDiscoveryPresets();
    await loadDiscoveryBatches();
  } catch {
    /* discovery optional until server restart */
  }
  await loadCandidates();
  if (deepLink?.candidate) applyDeepLinkClusterFilter(deepLink.candidate);
  syncUiRestoreControls();
  const wantBatch = String(uiPeek?.discoveryBatchId || state.discoveryBatchId || '').trim();
  if (wantBatch && (state.discoveryBatches || []).some((b) => b.id === wantBatch)) {
    try {
      await selectDiscoveryBatch(wantBatch);
    } catch {
      /* batch may have been deleted */
    }
  }
  if (deepLink?.candidate) {
    try {
      await selectCandidate(deepLink.candidate);
    } catch {
      /* candidate may have been deleted */
    }
  } else if (claudePeek) await applyClaudeUiRestore();
  else await applyUiSelectionRestore(uiPeek);
} finally {
  hideAppBootLoading();
}
startJobStreamLeader();
wireCandidatesBroadcast();
